// Generated by TyraX. Do not edit - regenerated on every build.
#include "game_runtime.gen.hpp"

namespace Character_generator {


int TerrainGame::resolveClipIndex(int objectIndex, const char* clipName) const {
  if (objectIndex < 0 || objectIndex >= (int)runtimeObjects.size()) return -1;
  const RuntimeObject& o = runtimeObjects[objectIndex];
  if (o.data.animModel < 0 || o.data.animModel >= (int)gameAnimModels.size())
    return -1;
  const GameAnimModel& gam = gameAnimModels[o.data.animModel];
  if (!gam.src) return -1;
  if (!clipName || !clipName[0]) return 0;  // "" = the file's first clip
  for (size_t c = 0; c < gam.src->clips.size(); ++c)
    if (gam.src->clips[c].name == clipName) return (int)c;
  return -1;
}



// Creates this object's skeletal instance and resets its playback state
// to the object's authored defaults. Called for every object on scene load.
void TerrainGame::setupAnimObject(int index) {
  RuntimeObject& o = runtimeObjects[index];
  ObjectGeometry& g = objectGeometry[index];
  g.animInst.reset();
  g.animParts.clear();  // bags point into the instance - drop them together
  g.animInfoBag.reset();
  g.animLastTick = 0;  // fresh instance skins on its first in-view frame
  // type 5 = animated Model, type 6 = a third-person Player avatar (same path)
  if ((o.data.type != 5 && o.data.type != 6) || o.data.animModel < 0 ||
      o.data.animModel >= (int)gameAnimModels.size())
    return;
  GameAnimModel& gam = gameAnimModels[o.data.animModel];
  if (!gam.src) return;

  g.animInst = std::make_unique<SkelInstance>(gam.src.get());
  DynamicMesh* mesh = g.animInst->mesh.get();
  for (size_t m = 0; m < mesh->materials.size(); ++m) {
    MeshMaterial* mat = mesh->materials[m];
    // texture links are per material id and every instance has fresh ids
    if (m < gam.textures.size() && gam.textures[m])
      gam.textures[m]->addLink(mat->id);
    // material albedo (glTF baseColorFactor). The lit VU1 programs ignore
    // this single color - it rides in the per-part light colors below - but
    // it is kept in sync for any single-color path that may read it.
    const float* base = gam.src->parts[m].color;
    mat->ambient.set(base[0] * 128.0F, base[1] * 128.0F, base[2] * 128.0F,
                     128.0F);
  }

  // Static-pipeline bags around the skinned arrays (rebuilt in place every
  // skin; bboxVersion bumps keep the frustum boxes honest). One info bag
  // per object carries the model matrix; parts share it.
  g.animMat.identity();
  g.animLightMat.identity();
  g.animInfoBag = std::make_unique<StaPipInfoBag>();
  g.animInfoBag->model = &g.animMat;
  g.animInfoBag->shadingType = TyraShadingGouraud;  // per-vertex lighting
  g.animInfoBag->frustumCulling = PipelineInfoBagFrustumCulling_Precise;
  g.animInfoBag->fullClipChecks = true;  // near-camera geometry, like objects
  g.animParts.clear();
  g.animParts.resize(mesh->materials.size());
  for (size_t m = 0; m < mesh->materials.size(); ++m) {
    ObjectGeometry::AnimPart& ap = g.animParts[m];
    MeshMaterialFrame* frame = mesh->materials[m]->frames[0];
    ap.colorBag = std::make_unique<StaPipColorBag>();
    ap.colorBag->single = &mesh->materials[m]->ambient;
    ap.lightBag = std::make_unique<StaPipLightingBag>();
    ap.lightBag->lightMatrix = &g.animLightMat;
    ap.lightBag->normals = frame->normals;
    // Fold this part's material albedo into its light colors so the lit VU1
    // program renders the .glb material color (outputColor = albedo * light),
    // not the plain scene light color (gray). Scene light/ambient here mirror
    // updateAndRenderAnimObjects; each part owns its probe directions.
    {
      const float* base = gam.src->parts[m].color;
      const float amb = 128.0F * SCENE_BRIGHTNESS * SCENE_AMBIENT;
      const float dif = 128.0F * SCENE_BRIGHTNESS * SCENE_DIFFUSE;
      ap.litColors[0].set(dif * SCENE_LIGHT_COL_R * base[0],
                          dif * SCENE_LIGHT_COL_G * base[1],
                          dif * SCENE_LIGHT_COL_B * base[2], 1.0F);
      ap.litColors[1].set(0.0F, 0.0F, 0.0F, 1.0F);
      ap.litColors[2].set(0.0F, 0.0F, 0.0F, 1.0F);
      ap.litColors[3].set(amb * base[0], amb * base[1], amb * base[2], 128.0F);
      ap.animLights = std::make_unique<PipelineDirLightsBag>(true);
      ap.litDirs[0].set(SCENE_LIGHT_X, 0.0F, 0.0F, 1.0F);
      ap.litDirs[1].set(SCENE_LIGHT_Y, 0.0F, 0.0F, 1.0F);
      ap.litDirs[2].set(SCENE_LIGHT_Z, 0.0F, 0.0F, 1.0F);
      ap.animLights->setLightsManually(ap.litColors, ap.litDirs);
      ap.lightBag->dirLights = ap.animLights.get();
    }
    ap.bag = std::make_unique<StaPipBag>();
    ap.bag->info = g.animInfoBag.get();
    ap.bag->color = ap.colorBag.get();
    ap.bag->vertices = frame->vertices;
    ap.bag->count = frame->count;
    ap.bag->lighting = ap.lightBag.get();
    if (m < gam.textures.size() && gam.textures[m] && frame->textureCoords) {
      ap.texBag = std::make_unique<StaPipTextureBag>();
      ap.texBag->texture = gam.textures[m];
      ap.texBag->coordinates = frame->textureCoords;
      ap.bag->texture = ap.texBag.get();
    }
  }

  o.animClip = resolveClipIndex(index, o.data.animClip);
  if (o.animClip < 0) {
    if (o.data.animClip && o.data.animClip[0])
      TYRA_WARN("Unknown animation clip: ", o.data.animClip);
    o.animClip = 0;
  }
  o.animLoop = o.data.animLoop != 0;
  o.animSpeed = o.data.animSpeed;
  o.animPlaying = o.data.animAutoplay != 0;
  o.animRestart = true;  // clip applied on the first anim update
  o.animFinished = false;
  o.animFade = 0.0F;

  // A living face, if the rig has one (the Character Generator's does):
  // nodes by name, so any .glb with these bones gets it.
  const SkelModel* sm = gam.src.get();
  g.faceHead = (s16)sm->findNode("mixamorig:Head");
  g.faceJaw = (s16)sm->findNode("mixamorig:Jaw");
  g.faceEye[0] = (s16)sm->findNode("mixamorig:LeftEye");
  g.faceEye[1] = (s16)sm->findNode("mixamorig:RightEye");
  g.faceLid[0] = (s16)sm->findNode("mixamorig:LeftEyelid");
  g.faceLid[1] = (s16)sm->findNode("mixamorig:RightEyelid");
  g.faceLive = false;
  g.faceSeed = 2654435761u * (u32)(index + 1);
  g.blinkIn = 0.5F + (float)(g.faceSeed >> 28) * 0.3F;  // never in unison
  g.blinkT = -1.0F;
  g.lookYaw = g.lookPitch = g.jawOpen = g.talkPhase = 0.0F;
  g.lipEnv = nullptr;
  g.lipLen = 0;
}



// A generated character's face: it blinks, its eyes and head turn to the
// player, its jaw talks. Rotation overrides on top of whatever clip plays
// (SkelInstance::setRotationOverride), on the nodes setupAnimObject found
// by name. Beyond FACE_DISTANCE a face is a few pixels at PS2 resolution:
// the overrides are dropped and the instance shares its pose again.
void TerrainGame::updateFace(int index, float dist2) {
  RuntimeObject& o = runtimeObjects[index];
  ObjectGeometry& g = objectGeometry[index];
  SkelInstance* inst = g.animInst.get();
  if (!inst || (g.faceHead < 0 && g.faceJaw < 0 && g.faceLid[0] < 0)) return;
  const float FACE_DISTANCE = 10.0F;
  if (dist2 > FACE_DISTANCE * FACE_DISTANCE || g.animLastTick == 0) {
    // (animLastTick 0: never skinned - node globals hold nothing yet)
    if (g.lipEnv && !splitSecondPass && !g_gameplayPaused) g.lipT += g_frameDt;
    if (g.faceLive) {
      inst->clearRotationOverrides();
      g.faceLive = false;
    }
    return;
  }
  // One clock per frame: the split screen's second pass re-renders the
  // same instant (and sets the very same overrides).
  const float dt = (splitSecondPass || g_gameplayPaused) ? 0.0F : g_frameDt;
  auto rnd = [&g]() {
    g.faceSeed = g.faceSeed * 1664525u + 1013904223u;
    return (float)((g.faceSeed >> 8) & 0xFFFF) / 65535.0F;
  };

  // Blink every 2-6 s (one in six comes as a double): 60 ms closing, 30 ms
  // shut, 80 ms opening - the shape of a real one.
  float lid = 0.0F;
  g.blinkIn -= dt;
  if (g.blinkT < 0.0F && g.blinkIn <= 0.0F) {
    g.blinkT = 0.0F;
    g.blinkIn = rnd() < 0.17F ? 0.3F : 2.0F + 4.0F * rnd();
  }
  if (g.blinkT >= 0.0F) {
    g.blinkT += dt;
    const float t = g.blinkT;
    lid = t < 0.06F   ? t / 0.06F
          : t < 0.09F ? 1.0F
          : t < 0.17F ? 1.0F - (t - 0.09F) / 0.08F
                      : 0.0F;
    if (t >= 0.17F) g.blinkT = -1.0F;
  }

  // Look at the player (the camera: in third person the character meets
  // your eye, which is the point). Within 4.5 m and in front of the face;
  // the player's own avatar looks where it goes.
  float wantYaw = 0.0F, wantPitch = 0.0F;
  if (o.data.type != 6 && g.faceHead >= 0) {
    const M4x4& m = g.animMat;
    const float d[3] = {cameraPosition.x - m.data[12],
                        cameraPosition.y - m.data[13],
                        cameraPosition.z - m.data[14]};
    float local[3];  // the camera in model space (columns are orthogonal)
    for (int a = 0; a < 3; ++a) {
      const float* c = &m.data[a * 4];
      const float l2 = c[0] * c[0] + c[1] * c[1] + c[2] * c[2];
      local[a] = l2 > 1e-12F ? (d[0] * c[0] + d[1] * c[1] + d[2] * c[2]) / l2
                             : 0.0F;
    }
    // from between the eyes (or the head joint, on a rig without eyes)
    float from[3];
    if (g.faceEye[0] >= 0 && g.faceEye[1] >= 0) {
      const M4x4& a = inst->nodeGlobal((u32)g.faceEye[0]);
      const M4x4& b = inst->nodeGlobal((u32)g.faceEye[1]);
      for (int k = 0; k < 3; ++k) from[k] = 0.5F * (a.data[12 + k] + b.data[12 + k]);
    } else {
      const M4x4& h = inst->nodeGlobal((u32)g.faceHead);
      for (int k = 0; k < 3; ++k) from[k] = h.data[12 + k];
    }
    const float v[3] = {local[0] - from[0], local[1] - from[1],
                        local[2] - from[2]};
    const float flat = sqrtf(v[0] * v[0] + v[2] * v[2]);
    const float yaw = atan2f(v[0], v[2]);  // model forward is +Z
    if (dist2 < 4.5F * 4.5F && fabsf(yaw) < 1.75F && flat > 0.05F) {
      wantYaw = yaw;
      wantPitch = atan2f(v[1], flat);
    }
  }
  const float lookRate = dt * 4.0F < 1.0F ? dt * 4.0F : 1.0F;
  g.lookYaw += (wantYaw - g.lookYaw) * lookRate;
  g.lookPitch += (wantPitch - g.lookPitch) * lookRate;
  auto clampf = [](float x, float lo, float hi) {
    return x < lo ? lo : (x > hi ? hi : x);
  };
  // The head takes most of a turn, the eyes the rest (and lead it: they are
  // clamped tighter but never smoothed twice).
  const float headYaw = clampf(g.lookYaw * 0.65F, -0.8F, 0.8F);
  const float headPitch = clampf(g.lookPitch * 0.5F, -0.35F, 0.35F);
  const float eyeYaw = clampf(g.lookYaw - headYaw, -0.4F, 0.4F);
  const float eyePitch = clampf(g.lookPitch - headPitch, -0.25F, 0.25F);

  // Talking: a scripted talk(), or a clip named like "Idle_Talking_Loop".
  bool talking = o.talkTime > 0.0F;
  if (o.talkTime > 0.0F) o.talkTime -= dt;
  if (!talking && o.animClip >= 0 &&
      o.animClip < (int)inst->model->clips.size() &&
      strstr(inst->model->clips[o.animClip].name.c_str(), "Talk"))
    talking = true;
  float wantJaw = 0.0F;
  if (g.lipEnv) {
    // lip-sync: the speaking sound's loudness, sampled where it is now
    const int at = (int)(g.lipT * (float)LIP_SYNC_RATE);
    if (at < g.lipLen) {
      wantJaw = (float)g.lipEnv[at] / 255.0F;
      talking = false;  // the real voice wins over the syllable machine
    } else {
      g.lipEnv = nullptr;
    }
    g.lipT += dt;
  }
  if (talking) {
    // syllables (~4 a second, uneven) with breaths between phrases
    g.talkPhase += dt;
    const float t = g.talkPhase;
    const float syllable = fabsf(sinf(t * 8.5F + 1.6F * sinf(t * 2.1F)));
    const float phrase = sinf(t * 1.1F) + sinf(t * 0.63F + 2.0F);
    wantJaw = syllable * (phrase > -0.9F ? 1.0F : 0.1F);
  } else {
    g.talkPhase = 0.0F;
  }
  const float jawRate = dt * 22.0F < 1.0F ? dt * 22.0F : 1.0F;
  g.jawOpen += (wantJaw - g.jawOpen) * jawRate;

  // Overrides, in each bone's own frame (the rig binds with identity
  // rotations: +X is the character's left-right axis, +Y up, +Z forward).
  float q[4];
  auto axisQuat = [&q](int axis, float angle) {
    q[0] = q[1] = q[2] = 0.0F;
    q[axis] = sinf(angle * 0.5F);
    q[3] = cosf(angle * 0.5F);
  };
  auto yawPitchQuat = [&q](float yaw, float pitch) {
    // yaw about +Y, then pitch about +X (a positive X turn tips the face
    // down, so looking up is a negative one)
    const float sy = sinf(yaw * 0.5F), cy = cosf(yaw * 0.5F);
    const float sx = sinf(-pitch * 0.5F), cx = cosf(-pitch * 0.5F);
    q[0] = cy * sx;
    q[1] = sy * cx;
    q[2] = -sy * sx;
    q[3] = cy * cx;
  };
  if (g.faceHead >= 0) {
    yawPitchQuat(headYaw, headPitch);
    inst->setRotationOverride((u32)g.faceHead, q);
  }
  for (int s = 0; s < 2; ++s) {
    if (g.faceEye[s] >= 0) {
      yawPitchQuat(eyeYaw, eyePitch);
      inst->setRotationOverride((u32)g.faceEye[s], q);
    }
    if (g.faceLid[s] >= 0) {
      // 54 degrees shuts it; the lid also rides the eye up and down a little
      axisQuat(0, clampf(lid * 0.95F - eyePitch * 0.6F, -0.2F, 0.95F));
      inst->setRotationOverride((u32)g.faceLid[s], q);
    }
  }
  if (g.faceJaw >= 0) {
    axisQuat(0, g.jawOpen * 0.21F);  // 12 degrees: speech, not a yawn
    inst->setRotationOverride((u32)g.faceJaw, q);
  }
  g.faceLive = true;
}



// The animated-models pass of the scene render. Real-hardware numbers drove
// this shape (PCSX2's fast EE hides all of it): each visible 1092-vert
// instance costs ~0.9 ms pose+skin plus ~1 ms submit on the EE, and the old
// code paid it for every instance every frame - 7 spiders saturated the
// 20 ms PAL budget on their own and halved the frame rate to 25.
// Three measures keep the pass inside the budget:
//  - instances whose conservative all-clips AABB is outside the frustum
//    skip pose/skin/submit entirely (playback still advances, so
//    animFinished and re-entry poses stay honest);
//  - instances striking the identical pose (same clip advanced in lockstep,
//    the ambient-prop / enemy-pack case) share one skinned mesh - the
//    nearest one skins, the rest re-point their bags at its arrays;
//  - with ANIM_LOD_DISTANCE set (Preferences > Rendering), far instances
//    refresh their pose every 2nd frame and every 4th beyond twice the
//    distance, staggered per object; playback time is unaffected and a
//    just-(re)appeared instance always skins immediately;
//  - with MESH_LOD_DISTANCE set, far instances render the decimated
//    variants baked into the .tskl (~50% verts, ~25% beyond twice the
//    distance) - less skinning, packing, clipping and VU1 per instance;
//  - the skinned arrays render through the SAME static pipeline as the rest
//    of the scene: one submission per vertex (DynPip uploads every vertex
//    twice for its from/to lerp), no VU1 program swap mid-frame, and the
//    EE clipper handles screen-edge crossers like all other geometry.
// In-view instances draw nearest-first: the front-to-back order lets the GS
// z-reject overdraw and makes each pose group's mesh owner its closest
// on-screen member (the LOD refresh rate follows the closest copy).
// One directional light matches the baked static lighting; baked point
// lights cannot follow animated meshes, but DYNAMIC lights (+ the
// flashlight) are sampled once per model per frame into the ambient term
// (see the dynLightAt pickup below) - a character walking into a torch's
// pool of light brightens with it.
/** Dynamic lighting (docs/global-illumination.md) - the opt-in per-object twin
 * of what animated models have always done. One probe sample at the object's
 * centre per frame, split the way a single VU1 light slot forces: L0 into the
 * ambient term, L1 reconstructed along the sun direction into the one
 * directional slot. dynLightAt goes in too, because the engine hands a LIT bag
 * no dynamic-light slot (StaPipCore::render) - without folding it in by hand,
 * an object that opted into dynamic lighting would be the one thing in the
 * scene the flashlight cannot touch. */
void TerrainGame::updateDynLitObjects() {
  if (!SCENE_PROBES) return;
  // The shared light DIRECTIONS - the anim path sets these too, but it bails
  // out early when a scene has no animated models, and this pass must not
  // depend on that having happened.
  // The direction array is a MATRIX, not three vectors: VU1 computes
  //   out = D[0]*n.x + D[1]*n.y + D[2]*n.z
  // and out.i - the term that multiplies light color i - is ROW i dotted with
  // the normal. So light i's direction goes in COLUMN i, i.e. this array holds
  // the transpose. Filled row-wise (which is what it looks like it wants) the
  // single sun silently degrades to out.x = SCENE_LIGHT_X * n.x: shading that
  // follows one coordinate of the normal, scaled by one coordinate of the
  // light. On a cylinder that reads as vertical bands; on a character it just
  // reads as "a bit dark". See pipeline_lighting_options.hpp.
  animLightDirs[0].set(SCENE_LIGHT_X, 0.0F, 0.0F, 1.0F);
  animLightDirs[1].set(SCENE_LIGHT_Y, 0.0F, 0.0F, 1.0F);
  animLightDirs[2].set(SCENE_LIGHT_Z, 0.0F, 0.0F, 1.0F);
  for (int i = 0; i < (int)runtimeObjects.size(); ++i) {
    RuntimeObject& o = runtimeObjects[i];
    if (!o.active || !o.visible || o.data.dynLit == 0) continue;
    fillDynLitColors(i);
  }
}



// The light colors for ONE dyn-lit object, read from the probe grid at its
// position. Split out of the per-frame pass because geometry is also rebuilt
// from INSIDE the render loop (renderObjects re-runs a dirty object), i.e.
// after this frame's updateDynLitObjects has already been and gone: a bag
// wired there would draw once with the zero-initialized litColors - black for
// a frame on every rebuild, which is every Live Link edit, not just the load.
// rebuildObjectGeometry therefore calls this the moment it wires a lit bag.
void TerrainGame::fillDynLitColors(int i) {
  if (!SCENE_PROBES) return;
  if (i < 0 || i >= (int)runtimeObjects.size()) return;
  if (i >= (int)objectGeometry.size()) return;
  RuntimeObject& o = runtimeObjects[i];
  ObjectGeometry& g = objectGeometry[i];
  if (g.parts.empty()) return;
  const V3 sun = {SCENE_LIGHT_X, SCENE_LIGHT_Y, SCENE_LIGHT_Z};
  {
    // Kept as 0..1 FRACTIONS here and scaled per part below: the color space
    // a lit surface lands in depends on whether that part is textured
    // (GeoPart::litScale), and this object may hold both kinds at once.
    float amb[3] = {SCENE_BRIGHTNESS * SCENE_AMBIENT,
                    SCENE_BRIGHTNESS * SCENE_AMBIENT,
                    SCENE_BRIGHTNESS * SCENE_AMBIENT};
    float dif[3] = {SCENE_BRIGHTNESS * SCENE_DIFFUSE * SCENE_LIGHT_COL_R,
                    SCENE_BRIGHTNESS * SCENE_DIFFUSE * SCENE_LIGHT_COL_G,
                    SCENE_BRIGHTNESS * SCENE_DIFFUSE * SCENE_LIGHT_COL_B};
    V3 ldir = sun;
    GiSample gs;
    const bool hasProbe = giProbeAt(o.data.position[0], o.data.position[1],
                                    o.data.position[2], gs);
    float dl[3];
    dynLightAt(engine, o.data.position[0], o.data.position[1],
               o.data.position[2], dl);
    for (GeoPart& part : g.parts) {
      if (!part.litBag) continue;
      const float* base = part.litAlbedo;
      const float s = part.litScale;
      part.litBag->dirLights->signedSH = hasProbe;
      if (hasProbe) {
        giSHLights(gs, dl, base, s, part.litDirs, part.litColors);
        continue;
      }
      part.litColors[0].set(s * dif[0] * base[0], s * dif[1] * base[1],
                            s * dif[2] * base[2], 1.0F);
      part.litColors[1].set(0.0F, 0.0F, 0.0F, 1.0F);
      part.litColors[2].set(0.0F, 0.0F, 0.0F, 1.0F);
      part.litColors[3].set(s * (amb[0] + dl[0]) * base[0],
                            s * (amb[1] + dl[1]) * base[1],
                            s * (amb[2] + dl[2]) * base[2], 128.0F);
      // Per-object directions, so this cannot ride the shared animLightDirs.
      // The array is the TRANSPOSE of the three light directions - light i
      // goes in COLUMN i (see pipeline_lighting_options.hpp) - and only slot 0
      // carries a light here.
      part.litDirs[0].set(ldir.x, 0.0F, 0.0F, 1.0F);
      part.litDirs[1].set(ldir.y, 0.0F, 0.0F, 1.0F);
      part.litDirs[2].set(ldir.z, 0.0F, 0.0F, 1.0F);
    }
  }
}



void TerrainGame::updateAndRenderAnimObjects() {
  if (gameAnimModels.empty()) return;
  bool any = false;
  for (int i = 0; i < (int)runtimeObjects.size() && !any; ++i)
    any = runtimeObjects[i].active && runtimeObjects[i].visible &&
          objectGeometry[i].animInst != nullptr;
  if (!any) return;

  const float amb = 128.0F * SCENE_BRIGHTNESS * SCENE_AMBIENT;
  const float dif = 128.0F * SCENE_BRIGHTNESS * SCENE_DIFFUSE;
  // manual dir-lights layout: [0..2] directional colors, [3] ambient
  animLightColors[0].set(dif * SCENE_LIGHT_COL_R, dif * SCENE_LIGHT_COL_G,
                         dif * SCENE_LIGHT_COL_B, 1.0F);
  animLightColors[1].set(0.0F, 0.0F, 0.0F, 1.0F);
  animLightColors[2].set(0.0F, 0.0F, 0.0F, 1.0F);
  animLightColors[3].set(amb, amb, amb, 128.0F);
  // The direction array is a MATRIX, not three vectors: VU1 computes
  //   out = D[0]*n.x + D[1]*n.y + D[2]*n.z
  // and out.i - the term that multiplies light color i - is ROW i dotted with
  // the normal. So light i's direction goes in COLUMN i, i.e. this array holds
  // the transpose. Filled row-wise (which is what it looks like it wants) the
  // single sun silently degrades to out.x = SCENE_LIGHT_X * n.x: shading that
  // follows one coordinate of the normal, scaled by one coordinate of the
  // light. On a cylinder that reads as vertical bands; on a character it just
  // reads as "a bit dark". See pipeline_lighting_options.hpp.
  animLightDirs[0].set(SCENE_LIGHT_X, 0.0F, 0.0F, 1.0F);
  animLightDirs[1].set(SCENE_LIGHT_Y, 0.0F, 0.0F, 1.0F);
  animLightDirs[2].set(SCENE_LIGHT_Z, 0.0F, 0.0F, 1.0F);

  // pass 1: playback bookkeeping for every instance; collect the in-view
  // ones with their camera distance
  struct VisibleAnim {
    int obj;
    float dist2;
  };
  static std::vector<VisibleAnim> inView;
  inView.clear();

  for (int i = 0; i < (int)runtimeObjects.size(); ++i) {
    RuntimeObject& o = runtimeObjects[i];
    ObjectGeometry& g = objectGeometry[i];
    SkelInstance* inst = g.animInst.get();
    if (!inst || !o.active || !o.visible) continue;
    const GameAnimModel& gam = gameAnimModels[o.data.animModel];

    if (o.animClip < 0 || o.animClip >= (int)gam.src->clips.size())
      o.animClip = 0;
    // Playback bookkeeping runs once per FRAME, not once per render pass -
    // the split screen's second half re-renders the same instant.
    if (!splitSecondPass) {
      if (o.animRestart) {
        o.animRestart = false;
        o.animFinished = false;
        // animFade > 0 crossfades from the pose currently showing
        inst->play((u32)o.animClip, o.animLoop, o.animFade);
        o.animFade = 0.0F;  // consumed by this restart
      }
      inst->setLoop(o.animLoop);
      // time always advances by wall-clock seconds (speed scales the step),
      // visible or not - animFinished stays honest for offscreen instances
      const float step =
          (o.animPlaying && !g_gameplayPaused) ? g_frameDt * o.animSpeed : 0.0F;
      o.animFinished = inst->advance(step);
    }

    // draw-distance cut-off (same rule as the static path in renderScene);
    // the distance doubles as the LOD tier and the draw-order key below
    const float dx = o.data.position[0] - cameraPosition.x;
    const float dy = o.data.position[1] - cameraPosition.y;
    const float dz = o.data.position[2] - cameraPosition.z;
    const float dist2 = dx * dx + dy * dy + dz * dz;
    if (o.data.drawDistance > 0.0F &&
        dist2 > o.data.drawDistance * o.data.drawDistance)
      continue;

    // model matrix straight from the object data: T * R(X,Y,Z) * Ryaw * S -
    // the same transform the static path bakes through pushVert()/rotated(),
    // plus the content-forward correction (modelYaw) as a pre-rotation
    // around the model's own Y, so an X-forward-authored mesh renders
    // turned while the LOGIC yaw (walker faceYaw, AI turn-to-face, authored
    // rotation) stays convention-pure.
    V3 sx = {o.data.scale[0], 0.0F, 0.0F};
    V3 sy = {0.0F, o.data.scale[1], 0.0F};
    V3 sz = {0.0F, 0.0F, o.data.scale[2]};
    if (o.data.modelYaw != 0.0F) {
      const float ya = o.data.modelYaw * (PI / 180.0F);
      const float yc = cosf(ya), ys = sinf(ya);
      auto preYaw = [&](const V3& v) {
        return V3{v.x * yc + v.z * ys, v.y, -v.x * ys + v.z * yc};
      };
      sx = preYaw(sx);
      sy = preYaw(sy);
      sz = preYaw(sz);
    }
    const V3 bx = rotated(sx, o.data.rotation);
    const V3 by = rotated(sy, o.data.rotation);
    const V3 bz = rotated(sz, o.data.rotation);
    M4x4& m = g.animMat;  // the geometry transform
    m.identity();
    m.data[0] = bx.x, m.data[1] = bx.y, m.data[2] = bx.z;
    m.data[4] = by.x, m.data[5] = by.y, m.data[6] = by.z;
    m.data[8] = bz.x, m.data[9] = bz.y, m.data[10] = bz.z;
    m.data[12] = o.data.position[0];
    m.data[13] = o.data.position[1];
    m.data[14] = o.data.position[2];
    // The VU1 lit programs do not normalize after this matrix multiply.
    // Remove instance scale or resizing a model changes its light intensity.
    // Like the existing skinner this assumes rotation/uniform-scale normals;
    // nonuniformly scaled surfaces still need a normalized inverse transpose.
    g.animLightMat.identity();
    for (int axis = 0; axis < 3; ++axis) {
      const float scale = fabsf(o.data.scale[axis]);
      const float inv = scale > 0.00001F ? 1.0F / scale : 0.0F;
      for (int c = 0; c < 3; ++c)
        g.animLightMat.data[axis * 4 + c] = m.data[axis * 4 + c] * inv;
    }


    // pose + skin + submit only when the conservative box touches the view
    if (gam.cullBox.frustumCheck(
            engine->renderer.core.renderer3D.frustumPlanes.getAll(), m) ==
        CoreBBoxFrustum::OUTSIDE_FRUSTUM)
      continue;

    inView.push_back({i, dist2});
  }
  if (inView.empty()) return;
  std::sort(inView.begin(), inView.end(),
            [](const VisibleAnim& a, const VisibleAnim& b) {
              return a.dist2 < b.dist2;
            });
  if (!splitSecondPass) ++animLodTick;  // frame counter, not pass counter

  // pass 2, nearest first: group equal poses per mesh-LOD tier, gate far
  // skins, submit
  struct RenderedAnim {
    int obj;
    int meshOwner;
    u8 meshLod;
  };
  static std::vector<RenderedAnim> rendered;
  rendered.clear();

  for (const VisibleAnim& va : inView) {
    const int i = va.obj;
    RuntimeObject& o = runtimeObjects[i];
    ObjectGeometry& g = objectGeometry[i];
    SkelInstance* inst = g.animInst.get();
    // before the pose-sharing test: a live face is a pose of its own
    updateFace(i, va.dist2);

    // mesh LOD tier: which baked variant this instance renders (the .tskl
    // clamps per part - a file without chains always renders the full mesh).
    // Per-object override first: -1 = project preference, 0 = never LOD,
    // > 0 = this object's own distance (each Player object - P1 and P2 of a
    // two-player scene - carries its own).
    const float meshLodDist =
        o.data.meshLod < 0.0F ? MESH_LOD_DISTANCE : o.data.meshLod;
    u8 meshLod = 0;
    if (meshLodDist > 0.0F) {
      const float m2 = meshLodDist * meshLodDist;
      meshLod = va.dist2 > m2 * 4.0F ? 2 : va.dist2 > m2 ? 1 : 0;
    }

    // pose sharing: follow an already-rendered instance in the same pose
    // AND the same tier (each tier holds its own skinned buffers)
    int meshOwner = i;
    for (const RenderedAnim& r : rendered) {
      if (r.meshLod != meshLod) continue;
      if (runtimeObjects[r.obj].data.animModel != o.data.animModel) continue;
      if (!inst->poseEquals(*objectGeometry[r.obj].animInst)) continue;
      meshOwner = r.meshOwner;
      break;
    }

    // animation LOD: a far mesh owner refreshes its pose every 2nd frame
    // (every 4th beyond twice the distance), staggered by object index. An
    // instance that just (re)entered the view skins immediately - its held
    // pose could be arbitrarily stale. The split screen's second half never
    // re-skins (same instant, already skinned) - unless this half's camera
    // distance lands the instance in a different mesh-LOD tier, which the
    // tier-switch check below still forces into that tier's buffers.
    bool allowSkin = !splitSecondPass;
    const float animLodDist =
        o.data.animLod < 0.0F ? ANIM_LOD_DISTANCE : o.data.animLod;
    if (allowSkin && animLodDist > 0.0F && meshOwner == i &&
        g.animLastTick != 0 && animLodTick - g.animLastTick <= 4) {
      const float lod2 = animLodDist * animLodDist;
      if (va.dist2 > lod2 * 4.0F)
        allowSkin = ((animLodTick + (u32)i) & 3) == 0;
      else if (va.dist2 > lod2)
        allowSkin = ((animLodTick + (u32)i) & 1) == 0;
    }
    g.animLastTick = animLodTick;

    ObjectGeometry& owner = objectGeometry[meshOwner];
    SkelInstance* ownerInst = owner.animInst.get();
    // a tier switch always re-skins (the other tier's buffers hold an older
    // skin, or the bind pose before their first ever use)
    const bool reskinned =
        meshOwner == i && (allowSkin || inst->currentLod() != meshLod)
            ? inst->ensurePose(meshLod)
            : false;
    // Dynamic light pickup: one sample at the model's center added to each
    // part's ambient term - a torch or the flashlight visibly lights the
    // character, without per-vertex VU1 cost (litColors[3] mirrors
    // setupAnimObject's albedo fold; alpha stays 128).
    {
      float dl[3];
      dynLightAt(engine, o.data.position[0],
                 o.data.position[1] + o.data.scale[1] * 0.5F,
                 o.data.position[2], dl);
      // One weighted probe lookup per visible instance, independent of pose
      // sharing and skinning LOD. Directions live in WORLD space: animLightMat
      // transforms the skinned local normals in the existing VU1 program.
      float amb[3] = {SCENE_BRIGHTNESS * SCENE_AMBIENT,
                      SCENE_BRIGHTNESS * SCENE_AMBIENT,
                      SCENE_BRIGHTNESS * SCENE_AMBIENT};
      float dif[3] = {SCENE_BRIGHTNESS * SCENE_DIFFUSE * SCENE_LIGHT_COL_R,
                      SCENE_BRIGHTNESS * SCENE_DIFFUSE * SCENE_LIGHT_COL_G,
                      SCENE_BRIGHTNESS * SCENE_DIFFUSE * SCENE_LIGHT_COL_B};
      const V3 sun = {SCENE_LIGHT_X, SCENE_LIGHT_Y, SCENE_LIGHT_Z};
      V3 ldir = sun;
      GiSample gs;
      const bool hasProbe = giProbeAt(o.data.position[0],
                    o.data.position[1] + o.data.scale[1] * 0.5F,
                    o.data.position[2], gs);
      const GameAnimModel& gam = gameAnimModels[o.data.animModel];
      for (size_t p = 0; p < g.animParts.size(); ++p) {
        if (!g.animParts[p].bag) continue;
        const float* base = gam.src->parts[p].color;
        auto& ap = g.animParts[p];
        ap.animLights->signedSH = hasProbe;
        if (hasProbe) {
          giSHLights(gs, dl, base, 128.0F, ap.litDirs, ap.litColors);
          continue;
        }
        ap.litColors[1].set(0.0F, 0.0F, 0.0F, 0.0F);
        ap.litColors[2].set(0.0F, 0.0F, 0.0F, 0.0F);
        g.animParts[p].litDirs[0].set(ldir.x, 0.0F, 0.0F, 1.0F);
        g.animParts[p].litDirs[1].set(ldir.y, 0.0F, 0.0F, 1.0F);
        g.animParts[p].litDirs[2].set(ldir.z, 0.0F, 0.0F, 1.0F);
        g.animParts[p].litColors[0].set(128.0F * dif[0] * base[0],
                                        128.0F * dif[1] * base[1],
                                        128.0F * dif[2] * base[2], 1.0F);
        g.animParts[p].litColors[3].set(
            128.0F * (amb[0] + dl[0]) * base[0],
            128.0F * (amb[1] + dl[1]) * base[1],
            128.0F * (amb[2] + dl[2]) * base[2], 128.0F);
      }
    }
    for (size_t p = 0; p < g.animParts.size(); ++p) {
      ObjectGeometry::AnimPart& ap = g.animParts[p];
      if (!ap.bag) continue;
      // bags may point at another frame's group leader or tier - re-aim
      const SkelInstance::LodArrays la = ownerInst->lodArrays(p, meshLod);
      ap.bag->vertices = la.vertices;
      ap.bag->count = la.count;
      ap.lightBag->normals = la.normals;
      if (ap.texBag) ap.texBag->coordinates = la.textureCoords;
      if (meshOwner == i) {
        if (reskinned) ap.bag->bboxVersion = ++g_bboxStamp;  // skinned in place
      } else {
        // identical pointer + version = followers reuse the owner's cached
        // frustum boxes instead of recomputing them per instance
        ap.bag->bboxVersion = owner.animParts[p].bag->bboxVersion;
      }
      stapip.core.render(ap.bag.get());
    }
    rendered.push_back({i, meshOwner, meshLod});
  }
}



// Shared player-vs-scene collision (both walkers). Box mode reproduces the
// classic behavior (XZ box + stand-on-top + step up 0.5), with models sized
// by their real mesh AABB instead of the unit scale box. Mesh mode collides
// with the model's triangles in object-local space: a downward ray finds the
// walkable ground (ramps/stairs work) and steep faces push the player out
// like walls. Rotation is honored in mesh mode and ignored in box mode.
// ceiling collects the lowest surface overhead (box undersides, mesh hits of
// an upward ray) so the walkers can clamp jumps below it.
void TerrainGame::collidePlayer(float prevX, float prevZ, float* nextX,
                                float* nextZ, float feetY, float eyeHeight,
                                float* ground, float* ceiling) {
  const float playerRadius = 0.35F;
  for (int oi = 0; oi < (int)runtimeObjects.size(); ++oi) {
    const RuntimeObject& o = runtimeObjects[oi];
    // The carried object rides in front of the face - letting it block its
    // own carrier would wedge the player against thin air.
    if (oi == carryIndex) continue;
    // Markers, lights, decals, areas, volumes, belts and "collision: none"
    // block nothing - one list, shared with the camera sweep (objectCollides).
    if (!o.active || !o.visible || !objectCollides(o.data)) continue;
    // Portal pass-through (updatePortalPass): while the walker stands in a
    // linked portal's opening, the geometry that opening is cut into stops
    // colliding - the mounting wall becomes a doorway. One rule, shared
    // with the camera/carry sweep and the physics pass.
    // A WALL portal's doorway opens the WALLS only. The floor the opening is
    // cut into keeps carrying the walker - a merged cellar mesh holds its own
    // floor, and a terrace slab's top face holds the pierce point - so
    // skipping the whole object made the arrival side of every doorway a
    // hole to fall through (showcase: walk through the gate, drop under the
    // map). A FLOOR portal (plane facing up or down) still opens all of it:
    // falling through it IS the crossing.
    const bool doorway =
        portalPassOn && portalDoorwayOpens(o, portalPassPlane, portalPassPoint);
    if (doorway && fabsf(portalPassPlane[1]) >= 0.5F) continue;

    const GameModel* gm = nullptr;
    if (o.data.type == 5 && o.data.model >= 0 &&
        o.data.model < (int)gameModels.size())
      gm = &gameModels[o.data.model];

    if (o.data.collision == 1 && gm && !gm->collider.empty()) {
      // --- mesh mode ---
      const float sx = o.data.scale[0] > 0.0001F ? o.data.scale[0] : 0.0001F;
      const float sy = o.data.scale[1] > 0.0001F ? o.data.scale[1] : 0.0001F;
      const float sz = o.data.scale[2] > 0.0001F ? o.data.scale[2] : 0.0001F;
      // Far away, out before any of the work below (two rotations per query,
      // three queries): the mesh fits in a sphere about the object's origin
      // whatever its rotation, and every query here is a vertical ray or a
      // sphere at the player - so a player further off horizontally than
      // that sphere plus its own reach cannot touch a triangle. This used to
      // be paid by every mesh-mode object in the scene, every frame.
      {
        const float* cmn = gm->collider.aabbMin();
        const float* cmx = gm->collider.aabbMax();
        const float s3[3] = {sx, sy, sz};
        float r2 = 0.0F;
        for (int k = 0; k < 3; ++k) {
          const float e = (fabsf(cmn[k]) > fabsf(cmx[k]) ? fabsf(cmn[k]) : fabsf(cmx[k])) * s3[k];
          r2 += e * e;
        }
        const float mvx = *nextX - prevX, mvz = *nextZ - prevZ;
        const float reach = sqrtf(r2) + playerRadius + 0.6F * (sx > sz ? sx : sz) +
                            sqrtf(mvx * mvx + mvz * mvz);
        const float dx = *nextX - o.data.position[0];
        const float dz = *nextZ - o.data.position[2];
        if (dx * dx + dz * dz > reach * reach) continue;
      }
      auto toLocal = [&](float wx, float wy, float wz) {
        V3 p = {wx - o.data.position[0], wy - o.data.position[1],
                wz - o.data.position[2]};
        p = invRotated(p, o.data.rotation);
        return V3{p.x / sx, p.y / sy, p.z / sz};
      };
      auto toWorld = [&](const V3& l) {
        V3 p = {l.x * sx, l.y * sy, l.z * sz};
        p = rotated(p, o.data.rotation);
        return V3{p.x + o.data.position[0], p.y + o.data.position[1],
                  p.z + o.data.position[2]};
      };

      // walls: push a chest-height sphere out of steep triangles (the radius
      // is approximated by the average XZ scale - exact for uniform scales).
      // "Steep" is judged in WORLD space: a tumbled physics model lying on
      // its side has world-walls whose LOCAL normal reads as a walkable
      // floor - so world-up rides into mesh space with the query.
      const V3 c = toLocal(*nextX, feetY + eyeHeight * 0.5F, *nextZ);
      Vec4 center(c.x, c.y, c.z, 1.0F);
      const float sAvg = (sx + sz) * 0.5F;
      const V3 upL = invRotated({0.0F, 1.0F, 0.0F}, o.data.rotation);
      // prev rides along so the push is side-aware: a step longer than the
      // radius that lands past a wall's plane is ejected BACK to the side
      // the player came from - the plain two-sided push pointed inward
      // there and sucked fast walkers inside the mesh.
      const V3 pc = toLocal(prevX, feetY + eyeHeight * 0.5F, prevZ);
      const Vec4 prevLocal(pc.x, pc.y, pc.z, 1.0F);
      if (!doorway &&
          gm->collider.resolveSphere(&center, playerRadius / sAvg, 0.7F,
                                     Vec4(upL.x, upL.y, upL.z, 0.0F),
                                     &prevLocal)) {
        const V3 w = toWorld({center.x, center.y, center.z});
        *nextX = w.x;
        *nextZ = w.z;
      }

      // ground: a ray from step height (0.5 above the feet) straight down,
      // transformed into local space so rotated/scaled models stay exact
      const V3 ro = toLocal(*nextX, feetY + 0.5F, *nextZ);
      const V3 rq = toLocal(*nextX, feetY - 100.0F, *nextZ);
      V3 rd = {rq.x - ro.x, rq.y - ro.y, rq.z - ro.z};
      const float rl = sqrtf(rd.x * rd.x + rd.y * rd.y + rd.z * rd.z);
      if (rl > 0.0001F) {
        rd.x /= rl, rd.y /= rl, rd.z /= rl;
        float t;
        if (gm->collider.raycast(Vec4(ro.x, ro.y, ro.z, 1.0F),
                                 Vec4(rd.x, rd.y, rd.z, 0.0F), rl, &t)) {
          const V3 hit =
              toWorld({ro.x + rd.x * t, ro.y + rd.y * t, ro.z + rd.z * t});
          if (hit.y > *ground) *ground = hit.y;
        }
      }

      // ceiling: a ray from step height straight up past the head finds the
      // underside of overhead geometry (door lintels, floors jumped against)
      const V3 co = toLocal(*nextX, feetY + 0.5F, *nextZ);
      const V3 cq =
          toLocal(*nextX, feetY + eyeHeight + EYE_CLEARANCE + 1.0F, *nextZ);
      V3 cd = {cq.x - co.x, cq.y - co.y, cq.z - co.z};
      const float cl = sqrtf(cd.x * cd.x + cd.y * cd.y + cd.z * cd.z);
      if (!doorway && cl > 0.0001F) {
        cd.x /= cl, cd.y /= cl, cd.z /= cl;
        float t;
        if (gm->collider.raycast(Vec4(co.x, co.y, co.z, 1.0F),
                                 Vec4(cd.x, cd.y, cd.z, 0.0F), cl, &t)) {
          const V3 hit =
              toWorld({co.x + cd.x * t, co.y + cd.y * t, co.z + cd.z * t});
          if (hit.y < *ceiling) *ceiling = hit.y;
        }
      }
      continue;
    }

    // --- box mode --- (models: real mesh AABB; primitives: unit scale box;
    // animated models: the baked AABB, a union over every clip's poses -
    // mesh mode is a static-model feature, so .glb objects collide as boxes).
    // The box comes from objectCollisionBox, the same one the camera boom
    // sweeps and the editor's overlay draws.
    const CollisionBox cb = objectCollisionBox(o);
    const float ex = cb.half[0], ey = cb.half[1], ez = cb.half[2];
    // World box center: the model-AABB offset lives in the object's own frame,
    // so it rotates with the object (a primitive's offset is 0, so this is
    // just its position).
    const V3 cWorld =
        boxRotate({cb.center[0], cb.center[1], cb.center[2]}, o.data);
    const float cx = o.data.position[0] + cWorld.x;
    const float cy = o.data.position[1] + cWorld.y;
    const float cz = o.data.position[2] + cWorld.z;
    const float hx = ex + playerRadius;
    const float hz = ez + playerRadius;
    const float top = cy + ey;
    const float bottom = cy - ey;

    // Footprint test in the box's OWN horizontal frame, so a yaw-rotated box
    // blocks along its real (rotated) faces instead of an axis-aligned bound
    // that juts into empty space at the corners. Vertical (top/bottom) stays
    // world-space: a yaw does not tilt the box, and box mode does not model a
    // tilted top - a pitched/rolled box still collides upright, as before
    // (mesh collision is the escape hatch for those). Reduces exactly to the
    // old AABB test when the object is unrotated.
    //
    // The frame is YAW ONLY, never the full 3D rotation: physics bodies
    // tumble (spin writes pitch/roll into rotation), and projecting a pitched
    // frame onto XZ is not an isometry - part of the horizontal offset
    // escapes into local Y and gets dropped, so far-away points read as
    // "inside" and the back-projection contracts the committed position
    // toward the box center (the player teleported into thrown objects and
    // stuck inside them).
    // modelYaw rides along: it is a rotation about the same (model) Y, so for
    // the yaw-only frame the two simply add.
    const float yaw = (o.data.rotation[1] + cb.yaw) * PI / 180.0F;
    const float yawC = cosf(yaw), yawS = sinf(yaw);
    auto toLocalXZ = [&](float wx, float wz, float& lx, float& lz) {
      const float dx = wx - cx, dz = wz - cz;
      lx = dx * yawC - dz * yawS;
      lz = dx * yawS + dz * yawC;
    };
    float lnx, lnz, lpx, lpz;
    toLocalXZ(*nextX, *nextZ, lnx, lnz);
    toLocalXZ(prevX, prevZ, lpx, lpz);

    const bool nextInside = lnx > -hx && lnx < hx && lnz > -hz && lnz < hz;
    if (!nextInside) continue;

    const bool wasInsideX = lpx > -hx && lpx < hx;
    const bool wasInsideZ = lpz > -hz && lpz < hz;
    // Re-projects a (possibly axis-cancelled) local target back to world.
    auto commitLocal = [&](float lx, float lz) {
      *nextX = cx + lx * yawC + lz * yawS;
      *nextZ = cz - lx * yawS + lz * yawC;
    };

    if (feetY + 0.5F >= top) {
      // low enough to walk onto - candidate floor
      if (top > *ground) *ground = top;
    } else if (doorway) {
      // the opened wall: its sides and underside are the doorway
    } else if (bottom >= feetY + eyeHeight) {
      // box entirely above the head - overhead surface for the jump clamp
      if (bottom < *ceiling) *ceiling = bottom;
      if (bottom < feetY + eyeHeight + EYE_CLEARANCE) {
        // walking under would leave the eye closer than the clip plane -
        // block, unless the player is already under it (let them walk out)
        if (!wasInsideX || !wasInsideZ)
          commitLocal(wasInsideX ? lnx : lpx, wasInsideZ ? lnz : lpz);
      }
    } else if (feetY < top) {
      // vertical overlap: also the lowest surface overhead when the box sank
      // onto the player (moving platforms) - lets the clamp push them out
      if (bottom >= feetY && bottom < *ceiling) *ceiling = bottom;
      // blocked - cancel the local axes that entered the box this frame, so
      // the residual slide runs along the (rotated) wall. Already inside on
      // both axes = a full stop.
      if (wasInsideX && wasInsideZ)
        commitLocal(lpx, lpz);
      else
        commitLocal(wasInsideX ? lnx : lpx, wasInsideZ ? lnz : lpz);
    }
  }

  // --- generated geometry ---------------------------------------------------
  // Merged prefab/procedural geometry has no objects behind it, so it gets its
  // own pass over the world AABBs procAddMergedObject collected. Same rules the
  // object box path uses - a low top is a step to walk onto, anything else is a
  // wall that cancels the axis that entered it - just without the orientation
  // (these are already conservative axis-aligned boxes).
  for (const StaticBox& b : procColliders) {
    // Cheap reject first: hundreds of boxes per frame per walker is fine only
    // if the common case is two compares. A prefab room is tens of units wide,
    // so a 3-unit skirt around the player's step never misses one it touches.
    if (b.mn[0] > *nextX + 3.0F || b.mx[0] < *nextX - 3.0F ||
        b.mn[2] > *nextZ + 3.0F || b.mx[2] < *nextZ - 3.0F)
      continue;
    const float headY = feetY + eyeHeight;
    const float stepY = feetY + 0.6F;
    if (b.mx[1] <= feetY + 0.01F || b.mn[1] >= headY) {
      // Entirely below the feet or above the head: it can still be the floor.
      if (b.mx[1] <= stepY && b.mx[1] > *ground && *nextX + playerRadius > b.mn[0] &&
          *nextX - playerRadius < b.mx[0] && *nextZ + playerRadius > b.mn[2] &&
          *nextZ - playerRadius < b.mx[2])
        *ground = b.mx[1];
      if (b.mn[1] >= headY && b.mn[1] < *ceiling &&
          *nextX + playerRadius > b.mn[0] && *nextX - playerRadius < b.mx[0] &&
          *nextZ + playerRadius > b.mn[2] && *nextZ - playerRadius < b.mx[2])
        *ceiling = b.mn[1];
      continue;
    }
    const float lo0 = b.mn[0] - playerRadius, hi0 = b.mx[0] + playerRadius;
    const float lo2 = b.mn[2] - playerRadius, hi2 = b.mx[2] + playerRadius;
    if (*nextX <= lo0 || *nextX >= hi0 || *nextZ <= lo2 || *nextZ >= hi2) continue;
    if (b.mx[1] <= stepY) {  // low enough to step onto rather than be stopped by
      if (b.mx[1] > *ground) *ground = b.mx[1];
      continue;
    }
    const bool wasInsideX = prevX > lo0 && prevX < hi0;
    const bool wasInsideZ = prevZ > lo2 && prevZ < hi2;
    if (wasInsideX && wasInsideZ) {
      *nextX = prevX;
      *nextZ = prevZ;
    } else {
      if (!wasInsideX) *nextX = prevX;
      if (!wasInsideZ) *nextZ = prevZ;
    }
  }

  // --- the block world ------------------------------------------------------
  // A block field is not made of objects, so it gets its own pass here - which
  // is also why this is the ONE hook it needs: every walker (both players, the
  // third-person rig, the noclip camera's ground probe) goes through
  // collidePlayer, so the ground, the ceiling and the walls all land at once.
  // procBlocks.active is false unless a runtime volume published a field, and
  // then the whole block costs one branch.
  if (procBlocks.active) {
    // Exactly ONE block is climbable in a stride - the rule every block game
    // uses, and the one that decides whether a landscape of cubes is walkable
    // at all. A shorter step makes every single-block rise a wall; a longer
    // one lets the player wade up a cliff.
    const float step = procBlocks.cell * 1.05F;
    // Walls, per axis, so a diagonal slides along a face instead of stopping
    // dead in the corner. The band starts a step ABOVE the feet: anything
    // lower is something to walk UP, not something to be stopped by - and it
    // must never be empty, which it would be whenever a block is taller than
    // the player (a 2-unit cube and a 1.8-unit walker is the normal case).
    const float y0 = feetY + step;
    const float y1 = feetY + eyeHeight > y0 ? feetY + eyeHeight : y0;
    if (procBlockBlocks(*nextX, prevZ, y0, y1, playerRadius)) *nextX = prevX;
    if (procBlockBlocks(*nextX, *nextZ, y0, y1, playerRadius)) *nextZ = prevZ;
    // Ground: the top of the highest solid block under the feet (plus the step,
    // so walking onto a one-block ledge lifts the player rather than stopping
    // them). Ceilings come from the same column.
    const float top = procBlockTopAt(*nextX, *nextZ, feetY + step);
    if (top > *ground) *ground = top;
    const float ceil = procBlockCeilAt(*nextX, *nextZ, feetY + step);
    if (ceil < *ceiling) *ceiling = ceil;
  }
}

 // last quantized depth written

// Switches the runtime state to a scene from scene_data.hpp and settles the
// asset residency for it: everything the scene's start-resident layers need
// loads synchronously here (the switch hides behind the loading screen),
// assets no resident layer uses any more - the previous scene's included -
// are freed. Runtime objects are rebuilt; vectors and per-object bags are
// reused/freed here, nothing leaks.
void TerrainGame::loadScene(int sceneIndex) {
  if (sceneIndex < 0 || sceneIndex >= SCENE_COUNT) return;
  currentScene = sceneIndex;
  g_activeScene = sceneIndex;
  sceneGeneration++;  // scene scripts see this and reset their state
  carryIndex = thrownIndex = -1;  // carried objects stay in their old scene
  carryPortalPi = -1;
  thrownFreeIndex = -1;           // and so does the portal-free latch
  portalLiveFlags.clear(); // stale through-views must not survive the switch
  portalPrevPos.clear();   // crossing history restarts with the new objects
  // Before any mesh baking: terrain chunks and object geometry shade with
  // this scene's point lights (see collectScenePointLights).
  collectScenePointLights();
  // Visible light beams + ground pools follow the scene's Point Lights.
  setupLightBeams();
  setupLightPools();
  // Blob shadows follow the scene's moving objects.
  setupBlobShadows();
  // Projected silhouette shadows follow the scene's "Cast shadow" objects.
  setupProjShadows();

  // Scene lightmaps: swap the per-scene textures (the terrain occlusion map
  // and the object atlas carrying occlusion + baked emissive light). Must
  // happen before any chunk/object bake - the bag wiring reads the pointers.
  if (!aoMapTexPath.empty()) releaseTexture(aoMapTexPath);
  if (!aoAtlasTexPath.empty()) releaseTexture(aoAtlasTexPath);
  aoMapTexPath.clear();
  aoAtlasTexPath.clear();
  aoMapTexture = nullptr;
  aoAtlasTexture = nullptr;
  // The terrain map also carries baked emissive light, so - like the object
  // atlas below - it loads whenever it exists, not only with AO enabled.
  if (SCENE_AO_MAP_PATH[0]) {
    aoMapTexPath = SCENE_AO_MAP_PATH;
    aoMapTexture = acquireTexture(aoMapTexPath);
  }
  // ...and for the GI multiply route regardless of the AO preference: on
  // that route the alpha channel is the LIGHT, not ambient occlusion.
  terrainMapOcc = aoMapTexture && SCENE_AO_MAP_OCC &&
                  (SCENE_AO_ENABLED || SCENE_AO_MAP_GILUM);
  // A failed load falls the light back to the per-vertex path rather than
  // dropping it: the chunk shade below reads this flag.
  terrainMapLit = aoMapTexture && SCENE_AO_MAP_LIT;
  // The object atlas also carries baked emissive light, so it loads whenever
  // it exists - a scene can have glowing lamps and no ambient occlusion.
  if (SCENE_AO_ATLAS_PATH[0]) {
    aoAtlasTexPath = SCENE_AO_ATLAS_PATH;
    aoAtlasTexture = acquireTexture(aoAtlasTexPath);
  }
  // Baked shadow decals: their atlas pages swap here for the same reason the
  // lightmaps do, and the geometry comes with them (docs/shadows.md).
  setupShadowDecals();

  // Size the terrain chunk pool for this scene's grid up front (independent
  // of the streamed assets below) so the loading bar's denominator can count
  // the in-view chunks that still have to be built.
  if (infoBag) resetTerrainChunks();
  // Terrain view focus, same source the synchronous drain used to use (the
  // player entity's authored position, else the orbit look-at).
  const float lsFocusX = (PLAYER_INDEX >= 0 && PLAYER_INDEX < SCENE_OBJECT_COUNT)
                             ? SCENE_OBJECTS[PLAYER_INDEX].position[0]
                             : cameraLookAt.x;
  const float lsFocusZ = (PLAYER_INDEX >= 0 && PLAYER_INDEX < SCENE_OBJECT_COUNT)
                             ? SCENE_OBJECTS[PLAYER_INDEX].position[2]
                             : cameraLookAt.z;

  // Loading-screen progress pump. The load is otherwise blocking, so we count
  // the work units (assets to stream + objects to build + terrain chunks) and
  // present a loading-screen frame every ~1/24th of the way through, so the
  // bar reflects real progress. lsStep caps presented frames (rendering every
  // unit would slow chunk-heavy loads). With LOADING_SCREEN off, lsPump is a
  // no-op and the load behaves exactly as before.
  int lsDone = 0, lsMark = 0, lsTotal = 0, lsStep = 1;
  auto lsPump = [&](int n) {
    if (!LOADING_SCREEN) return;
    lsDone += n;
    if (lsDone >= lsMark) {
      lsMark += lsStep;
      loadingscreen::renderFrame(
          engine, sceneIndex, lsTotal > 0 ? (float)lsDone / (float)lsTotal : 1.0F);
    }
  };

  // Streaming layers: desired residency from the scene's authored defaults.
  {
    // The previous scene's runtime objects (spawn-pool clones included) are
    // gone from here on - drop their active flags BEFORE the residency math
    // so no stale clone pins the old scene's assets under new-scene indices.
    for (RuntimeObject& o : runtimeObjects) o.active = false;
    const int lc = SCENE_LAYER_COUNT;
    layerTarget.assign(lc > 0 ? lc : 0, 0);
    layerState.assign(lc > 0 ? lc : 0, 0);
    layerRequest.assign(lc > 0 ? lc : 0, -1);
    layerAutoInside.assign(lc > 0 ? lc : 0, 0);
    // Auto-streamed layers start resident only when the spawn point is
    // inside their zone; everything else follows the authored Start loaded.
    // runtimeObjects are rebuilt further down, so an area zone reads the
    // authored transform straight out of SCENE_OBJECTS here.
    float spawnX = 0.0F, spawnY = 0.0F, spawnZ = 0.0F;
    if (PLAYER_INDEX >= 0) {
      spawnX = SCENE_OBJECTS[PLAYER_INDEX].position[0];
      spawnY = SCENE_OBJECTS[PLAYER_INDEX].position[1];
      spawnZ = SCENE_OBJECTS[PLAYER_INDEX].position[2];
    } else {
      for (int i = 0; i < SCENE_OBJECT_COUNT; ++i)
        if (SCENE_OBJECTS[i].type == 4) {  // spawn point (built-in FPP)
          spawnX = SCENE_OBJECTS[i].position[0];
          spawnY = SCENE_OBJECTS[i].position[1];
          spawnZ = SCENE_OBJECTS[i].position[2];
          break;
        }
    }
    for (int l = 0; l < lc; ++l) {
      const float r = SCENE_LAYER_STREAM_R[l];
      const int az = SCENE_LAYER_STREAM_AREA[l];
      if (r > 0.0F && az >= 0 && az < SCENE_OBJECT_COUNT) {
        // Area zone: the spawn stands in the box (eye height included - the
        // marker sits on the ground, so a floor-hugging box still catches it).
        const bool inside =
            pointInArea(SCENE_OBJECTS[az], spawnX, spawnY, spawnZ) ||
            pointInArea(SCENE_OBJECTS[az], spawnX,
                        spawnY + PP_EYE_HEIGHT(0), spawnZ);
        layerTarget[l] = inside ? 1 : 0;
        layerAutoInside[l] = inside ? 1 : 0;
      } else if (r > 0.0F) {
        const float dx = spawnX - SCENE_LAYER_STREAM_X[l];
        const float dz = spawnZ - SCENE_LAYER_STREAM_Z[l];
        const bool inside = dx * dx + dz * dz < r * r;
        layerTarget[l] = inside ? 1 : 0;
        layerAutoInside[l] = inside ? 1 : 0;
      } else {
        layerTarget[l] = SCENE_LAYER_START[l] ? 1 : 0;
      }
    }
    applyLayerResidency();
    // Now the work is known: assets queued + objects to build + chunks in view.
    if (LOADING_SCREEN) {
      // Runtime procedural generation is the one part of a load that can take
      // a visible amount of time, so it has to be IN the denominator - a bar
      // that reaches 100% and then sits there is worse than no bar. Eight
      // units per volume is the same weight the pump reports back.
      int lsProc = 0;
      if (procrt::ENABLED)
        for (int v = 0; v < procrt::VOLUME_COUNT; ++v)
          if (procrt::VOLUMES[v].scene == sceneIndex &&
              procrt::VOLUMES[v].runAtStart)
            lsProc += 8;
      lsTotal = (int)streamQueue.size() + SCENE_OBJECT_COUNT +
                countPendingChunks(lsFocusX, lsFocusZ) + lsProc;
      lsStep = lsTotal > 0 ? (lsTotal + 23) / 24 : 1;
      loadingscreen::renderFrame(engine, sceneIndex, 0.0F);  // first frame
    }
    while (!streamQueue.empty()) {
      processOneStreamJob();
      lsPump(1);
    }
    for (int l = 0; l < lc; ++l) layerState[l] = layerTarget[l] ? 2 : 0;
  }

  // Terrain, lighting, sky, clipping and post-FX are per scene (Scene >
  // Preferences overrides) - re-apply render settings (the chunk pool was
  // reset at the top; the chunks themselves drain at the end of this
  // function, once the view focus is known).
  if (infoBag) {
    infoBag->fullClipChecks = CLIP_PRECISE;
    skyHorizonR = SKY_R, skyHorizonG = SKY_G, skyHorizonB = SKY_B;
    skyTopR = SKY_TOP_R, skyTopG = SKY_TOP_G, skyTopB = SKY_TOP_B;
    // Park the runtime clock at the authored hour, so a scene's first frame is
    // what the editor previewed rather than wherever the last scene's clock got
    // to. Must happen BEFORE buildSkyDome, which bakes the zenith in.
    daynight::reset(sceneIndex);
    if (daynight::active(sceneIndex)) {
      skyHorizonR = daynight::g_sky[0] * 255.0F;
      skyHorizonG = daynight::g_sky[1] * 255.0F;
      skyHorizonB = daynight::g_sky[2] * 255.0F;
      skyTopR = daynight::g_top[0] * 255.0F;
      skyTopG = daynight::g_top[1] * 255.0F;
      skyTopB = daynight::g_top[2] * 255.0F;
      dayNightTopR = skyTopR, dayNightTopG = skyTopG, dayNightTopB = skyTopB;
      scriptCtx.skyColor = Color(skyHorizonR, skyHorizonG, skyHorizonB);
    }
#ifdef SKY_TEXTURES_ON
    // The painted sky swaps like the lightmaps: release the last scene's
    // crop, take this one's. REPEAT across (the panorama closes on itself),
    // CLAMP down (its bottom row is below the dome's lowest ring).
    if (!skyTexPath.empty()) releaseTexture(skyTexPath);
    skyTexPath.clear();
    skyTex = nullptr;
    if (SKY_TEXTURE_PATH[0]) {
      skyTexPath = SKY_TEXTURE_PATH;
      skyTex = acquireTexture(skyTexPath);
      if (skyTex) skyTex->setWrapSettings(Tyra::Repeat, Tyra::Clamp);
    }
#endif
    buildSkyDome();
    buildStarField();
  }
  // Per-scene clipping override may flip the hidden VU1 clipping mode.
  stapip.core.setVU1Clipping(CLIP_VU1);
  // Per-scene sky color (the loop paints the clear screen from ctx.skyColor)
  // and post effects.
  scriptCtx.skyColor = Color(SKY_R, SKY_G, SKY_B);
  engine->renderer.setClearScreenColor(scriptCtx.skyColor);
  engine->renderer.core.postFx.setBloom(POSTFX_BLOOM);
  engine->renderer.core.postFx.setBloomThreshold(POSTFX_BLOOM_CUT);
  engine->renderer.core.postFx.setBloomSpread(POSTFX_BLOOM_SPREAD);
  engine->renderer.core.postFx.setGrain(POSTFX_GRAIN);
  g_motionBlurBase = POSTFX_MOTIONBLUR;
  engine->renderer.core.postFx.setMotionBlur(POSTFX_MOTIONBLUR);
  // Never carry the previous scene's full-screen history across a load.
  g_mbHavePrev = false;
  g_mbIdleTime = 0.0F;
  g_mbIdleFlushed = false;
  g_mbFlushNext = true;
  engine->renderer.core.postFx.setGodRays(POSTFX_GODRAYS);
  g_flareAmount = POSTFX_FLARE;
  engine->renderer.core.postFx.setDepthOfField(POSTFX_DOF_FOCUS,
                                               POSTFX_DOF_RANGE, POSTFX_DOF);
  // GS hardware distance fog (Scene/Project > Preferences > Fog).
  if (FOG_ENABLED)
    engine->renderer.core.setFog(Color(FOG_R, FOG_G, FOG_B), FOG_START,
                                 FOG_END);
  else
    engine->renderer.core.disableFog();

  // Camera flashlight is a Player property: reset the runtime master to this
  // scene's player Enabled flag (the flow graph can change it later); the
  // on/off toggle starts on.
  g_flashEnabled = FLASHLIGHT_ENABLED;
  g_flashOn = true;
  // A Set Player Input lock must never survive a scene load - a cutscene that
  // switches scenes would otherwise hand the player a world they cannot move in.
  g_playerLocked = false;
  g_camShake = 0.0F;
  g_camShakeT = 0.0F;

  // Authored objects + the dynamic spawn pool (Spawn Object flow node).
  runtimeObjects.assign(SCENE_OBJECT_COUNT + MAX_SPAWNED_OBJECTS,
                        RuntimeObject());
  objectGeometry.clear();
  objectGeometry.resize(SCENE_OBJECT_COUNT + MAX_SPAWNED_OBJECTS);
  // The flashlight's receivers are indices into the table that just went away.
  flashSpotOffList.clear();
  // Pool slots start empty - data arrives from a template at spawn time.
  for (int i = SCENE_OBJECT_COUNT; i < (int)runtimeObjects.size(); ++i) {
    runtimeObjects[i].active = false;
    runtimeObjects[i].visible = false;
    runtimeObjects[i].dirty = false;
  }
  for (int i = 0; i < SCENE_OBJECT_COUNT; ++i) {
    runtimeObjects[i].data = SCENE_OBJECTS[i];
    // spawn points and the player are editor markers, not geometry; emitters
    // honor their Enabled flag (Show/Hide Object flips visible at runtime)
    runtimeObjects[i].visible =
        SCENE_OBJECTS[i].type != 4 && SCENE_OBJECTS[i].type != 6 &&
        !(SCENE_OBJECTS[i].type == 7 && !SCENE_OBJECTS[i].emitEnabled);
    runtimeObjects[i].dirty = true;
    // objects of layers that don't start resident wait for Load Layer
    runtimeObjects[i].active = layerOn(SCENE_OBJECTS[i].layer);
    if (!runtimeObjects[i].active) {
      runtimeObjects[i].visible = false;
      runtimeObjects[i].dirty = false;
    }
    lsPump(1);
  }
  // Animated models: fresh per-object mesh instances + playback defaults
  for (int i = 0; i < SCENE_OBJECT_COUNT; ++i)
    if (runtimeObjects[i].active) setupAnimObject(i);
  // Vehicles seed AFTER the runtime objects: setupVehicles reads each
  // instance's authored transform out of runtimeObjects[..].data, and placed
  // before this loop it read zeros - the sim started every car at the world
  // origin at scale 1 while the body rendered at its authored place, which is
  // "the wheels drove off without the car" seen from another angle. Caught by
  // the VEH use-click telemetry printing car=0,0 for a car authored at 0,-8.


  // Static batching: group the batchStatic-flagged objects (texture x
  // coarse world cell). The always-resident assets - materials included -
  // streamed in above, so the reflective-material opt-out can decide here;
  // the batches themselves bake lazily on the first renderScene.
  buildStaticBatchList();

  // Runtime procedural volumes + prefab instances belong to the scene that
  // made them: nothing generated survives a switch (the geometry references
  // this scene's models and its block field is this scene's ground).
  procChunks.clear();
  procColliders.clear();
  prefabInstances.clear();
  procBlocks.active = false;
  procBlocks.col.clear();
  if (procrt::ENABLED) {
    for (int v = 0; v < procrt::VOLUME_COUNT; ++v) {
      if (procrt::VOLUMES[v].scene != currentScene) continue;
      if (!procrt::VOLUMES[v].runAtStart) continue;
      // Generation is the one part of a load that can take a visible amount of
      // time, so it reports into the same progress pump the asset streaming
      // uses instead of freezing on the last drawn frame.
      procGenerateVolume(v, 0);
      lsPump(8);
    }
  }

  // Roads AFTER the procedural build: that block clears procChunks (nothing
  // generated survives a scene switch), and the first placement of this call
  // sat ten lines above it - five road chunks built and wiped before the
  // first frame, a road only the boot log ever saw.


  // Raytraced mirrors (VU0 PoC): create this scene's reflection textures
  // before the lazy geometry rebuild binds them to the glass quads.
  buildRtMirrors();

  scriptCtx.objects = runtimeObjects.data();
  scriptCtx.objectCount = (int)runtimeObjects.size();
  // Dynamic point lights: request slots per object index (Set Light node).
  lightReq.assign(runtimeObjects.empty() ? 1 : runtimeObjects.size(), -1);
  lightIntens.assign(runtimeObjects.empty() ? 1 : runtimeObjects.size(), -1.0F);
  scriptCtx.lightRequest = lightReq.data();
  scriptCtx.lightIntensity = lightIntens.data();
  scriptCtx.scene = currentScene;
  scriptCtx.sceneGeneration = sceneGeneration;
  scriptCtx.layerState = layerState.data();
  scriptCtx.layerRequest = layerRequest.data();
  scriptCtx.layerCount = (int)layerState.size();
  scriptCtx.usedObject = -1;
  useTargetIndex = -1;

  // Player entity start state for this scene. players[0] = the first Player
  // object (P1), players[1] = the second (P2 of the two-player modes; -1
  // when the scene has only one). Player 2 stays active across scene
  // switches as long as the new scene can host it.
  if (playerTwoActive && PLAYER2_INDEX < 0) {
    playerTwoActive = false;
    syncPlayerCountMenuValue();
  }
  sharedBoom = 0.0F;
  for (int pi = 0; pi < 2; ++pi) {
    PlayerCtl& P = players[pi];
    P.objIndex = PP_INDEX(pi) < SCENE_OBJECT_COUNT ? PP_INDEX(pi) : -1;
    if (P.objIndex < 0) continue;
    P.x = SCENE_OBJECTS[P.objIndex].position[0];
    P.z = SCENE_OBJECTS[P.objIndex].position[2];
    // Respect authored platforms/rooms above the heightfield. Starting every
    // walker on terrain put a raised-floor scene's player below its colliders.
    // Keep the terrain as a lower bound; normal gravity finds the actual floor.
    P.y = (PP_MODE(pi) == 1 || !TERRAIN_ENABLED)
              ? SCENE_OBJECTS[P.objIndex].position[1]
              : fmaxf(SCENE_OBJECTS[P.objIndex].position[1],
                      terrainHeightAt(P.x, P.z));
    // Heading AND elevation from the authored rotation, read the way every
    // other object's is: the player's local forward (+Z, the axis
    // sin(yaw)/cos(yaw) walks along) through rotated(). Reading rotation[1]
    // alone was wrong twice over - a triple the gizmo wraps as
    // [-180, 89, -180] means yaw 91 and pitch 0, not yaw 89 - and it left
    // the start pitch unauthorable, which made every "aim the torch just
    // above the wall's foot" fixture a pad-driven guess (docs/player.md).
    // Positive rotation[0] tilts the look DOWN, like tilting any object.
    {
      const V3 fwd = rotated(V3{0.0F, 0.0F, 1.0F},
                             SCENE_OBJECTS[P.objIndex].rotation);
      P.yaw = atan2f(fwd.x, fwd.z);
      float el = fwd.y > 1.0F ? 1.0F : (fwd.y < -1.0F ? -1.0F : fwd.y);
      P.pitch = asinf(el);
      if (P.pitch > 1.35F) P.pitch = 1.35F;
      if (P.pitch < -1.35F) P.pitch = -1.35F;
    }
    P.velY = 0.0F;
    // Third person: the avatar starts facing its authored yaw and its
    // locomotion clip names resolve to the model's clip indices. The Player
    // object is a rendered avatar only in this mode - in FPP/noclip its model
    // (if any) is never built, so its runtime object stays invisible here.
    // The P2 avatar shows only while player 2 is actually in the game.
    P.faceYaw = P.yaw;
    P.boom = PP_CAM_DIST(pi);  // start fully extended, not easing out from 0
    runtimeObjects[P.objIndex].visible =
        PP_MODE(pi) == 2 && (pi == 0 || playerTwoActive);
    if (PP_MODE(pi) == 2 && PP_CAM_STYLE(pi) != 0) {
      // Fixed-angle style: the camera starts on its authored heading and
      // elevation instead of behind the avatar (the avatar itself still
      // starts facing its authored yaw - P.faceYaw keeps that above).
      P.yaw = PP_CAM_YAW(pi);
      P.pitch = -PP_CAM_PITCH(pi);
    }
    if (PP_MODE(pi) == 2) {
      // Idle/walk fall back to the model's first clip when unset; run/jump are
      // optional, so an empty name stays unmapped (-1) instead of clip 0.
      P.idleClip = resolveClipIndex(P.objIndex, PP_IDLE_CLIP(pi));
      P.walkClip = resolveClipIndex(P.objIndex, PP_WALK_CLIP(pi));
      P.runClip =
          PP_RUN_CLIP(pi)[0] ? resolveClipIndex(P.objIndex, PP_RUN_CLIP(pi)) : -1;
      P.sprintClip = PP_SPRINT_CLIP(pi)[0]
                         ? resolveClipIndex(P.objIndex, PP_SPRINT_CLIP(pi))
                         : -1;
      P.speeds[0] = PP_WALK_SPEED(pi);
      P.speeds[1] = PP_RUN_SPEED(pi);
      P.speeds[2] = PP_SPRINT_SPEED(pi);
      P.jumpClip =
          PP_JUMP_CLIP(pi)[0] ? resolveClipIndex(P.objIndex, PP_JUMP_CLIP(pi)) : -1;
      P.backClip =
          PP_BACK_CLIP(pi)[0] ? resolveClipIndex(P.objIndex, PP_BACK_CLIP(pi)) : -1;
      P.strafeLClip = PP_STRAFE_L_CLIP(pi)[0]
                          ? resolveClipIndex(P.objIndex, PP_STRAFE_L_CLIP(pi))
                          : -1;
      P.strafeRClip = PP_STRAFE_R_CLIP(pi)[0]
                          ? resolveClipIndex(P.objIndex, PP_STRAFE_R_CLIP(pi))
                          : -1;
      // Start ON the idle clip so drivePlayerAnim recognizes it as a locomotion
      // pose from frame one. Without this, setupAnimObject's default (clip 0)
      // would look like a scripted one-shot when idle isn't clip 0, and a
      // looping clip 0 would wedge locomotion off (animFinished never fires).
      if (P.idleClip >= 0 && objectGeometry[P.objIndex].animInst) {
        RuntimeObject& body = runtimeObjects[P.objIndex];
        body.animClip = P.idleClip;
        body.animLoop = true;
        body.animPlaying = true;
        body.animRestart = true;
      }
    }
  }

  buildParticles();

  // Sound emitters: fresh retrigger state; mute the emitter channels (an
  // ADPCM sample can't be stopped - it plays out, but silently). Both cores'
  // sets, because a room can have moved the emitters onto either bus.
  sndTimers.assign(runtimeObjects.size(), 0);
  for (int ch = 16; ch < 24; ++ch) {
    engine->audio.adpcm.setVolume(0, (s8)ch);
    engine->audio.adpcm.setVolume(0, (s8)(ch + 24));
    sndChVol[ch - 16] = 0;  // keep the RPC cache in sync with the mute
    sndChBus[ch - 16] = -1;  // ...and make the next write unconditional
    // The owners are runtime object INDICES, which the new scene renumbers.
    sndSlotOwner[ch - 16] = -1;
  }

  // Reverb: a scene switch is a cut, so drop both rooms instead of ramping one
  // out of the old scene into the new one. The depth cache is invalidated
  // (-1) rather than set, so the first updateReverb writes the hardware even
  // if the new scene wants exactly what the old one had.
  if (REVERB_ZONE_COUNT > 0 || REVERB_HAS_NODE) {
    for (int b = 0; b < 2; ++b) {
      reverbAmt[b] = 0.0F;
      reverbDepthSent[b] = -1;
      engine->audio.reverb.setDepth(
          b == 0 ? Tyra::AudioReverb::BusA : Tyra::AudioReverb::BusB, 0, 0);
    }
    reverbBus = 0;
    scriptCtx.reverbBusBase = 0;
  }

  // A loaded save targeting this scene: apply the stored object state now
  if (pendingObjScene == sceneIndex && !pendingObjState.empty())
    applySavedObjects();

  // Terrain: build every chunk in view of the start focus. From here on
  // renderScene streams the ring. With no loading screen this is the old
  // one-shot drain; with one, the chunks build in lsStep-sized batches so the
  // bar can advance between them (breaking if the pool momentarily can't make
  // progress, which the view-rect-sized pool should never hit at load time).
  if (!LOADING_SCREEN) {
    updateTerrainChunks(lsFocusX, lsFocusZ, 0.0F, 0.0F, false, 0x7FFFFFFF);
  } else {
    int pending = countPendingChunks(lsFocusX, lsFocusZ);
    while (pending > 0) {
      updateTerrainChunks(lsFocusX, lsFocusZ, 0.0F, 0.0F, false, lsStep);
      const int now = countPendingChunks(lsFocusX, lsFocusZ);
      if (now >= pending) break;  // no forward progress (pool cap) - bail out
      lsPump(pending - now);
      pending = now;
    }
    loadingscreen::renderFrame(engine, sceneIndex, 1.0F);  // final frame
  }
}



// --- Sound emitters ----------------------------------------------------
// Volume falls off linearly with the distance to the player; the sound is
// panned left/right by the emitter's position relative to where the camera
// faces (positional stereo). Interval 0 retriggers every frame: tryPlay() is
// skipped while the channel is still busy, so the sample loops seamlessly.
// sndOnPlayer emitters skip all of that: full volume, centered - they play
// "on the player" wherever they are (dialogs, narration). Hiding it mutes.
void TerrainGame::updateSoundEmitters() {
  if (sndSamples.empty()) return;
  // Paused (a menu, or the Live Debugger halting the game): stop RETRIGGERING.
  // Whatever is in flight plays out - an ADPCM voice cannot be stopped - so
  // the world goes quiet within one sample instead of clicking off, and
  // nothing new starts while the game is frozen. updateParticles takes the
  // same early return two functions down; a halted game that keeps ticking
  // its emitters was the odd one out.
  if (g_gameplayPaused) return;
  if (sndTimers.size() != runtimeObjects.size())
    sndTimers.assign(runtimeObjects.size(), 0);

  // Pass 1: what every emitter WANTS this frame. Pure arithmetic - not one
  // RPC - so ranking the whole scene costs the IOP nothing, and an emitter
  // that is out of range, hidden or deactivated simply does not appear.
  sndWants.clear();
  for (int i = 0; i < (int)runtimeObjects.size(); ++i) {
    const RuntimeObject& o = runtimeObjects[i];
    if (o.data.type != 8 || !o.data.sndAuto) continue;
    if (o.data.snd < 0 || o.data.snd >= (int)sndSamples.size()) continue;
    if (!sndSamples[o.data.snd]) continue;  // sample failed to load (too big for SPU2?)
    if (!o.active || !o.visible) continue;
    int vol = 100;
    int pan = 0;
    if (!o.data.sndOnPlayer) {
      const float dx = o.data.position[0] - scriptCtx.playerPosition.x;
      const float dy = o.data.position[1] - scriptCtx.playerPosition.y;
      const float dz = o.data.position[2] - scriptCtx.playerPosition.z;
      const float dist = sqrtf(dx * dx + dy * dy + dz * dz);
      const float range = o.data.sndRange > 0.5F ? o.data.sndRange : 0.5F;
      vol = dist >= range ? 0 : (int)(100.0F * (1.0F - dist / range));
      // Pan: project the horizontal direction to the emitter onto the camera's
      // screen-right axis; -100 = full left, +100 = full right. Screen-right is
      // fwd x up = (-fwd.z, fwd.x) in this right-handed Y-up world - NOT the
      // particle billboards' (fwd.z, -fwd.x), which is mirrored (billboard quads
      // are symmetric so the sign never mattered there; ears notice).
      Vec4 fwd = cameraLookAt - cameraPosition;
      float rx = -fwd.z, rz = fwd.x;
      const float rl = sqrtf(rx * rx + rz * rz);
      if (rl > 0.0001F) {
        rx /= rl; rz /= rl;
        const float ex = o.data.position[0] - cameraPosition.x;
        const float ez = o.data.position[2] - cameraPosition.z;
        const float el = sqrtf(ex * ex + ez * ez);
        if (el > 0.0001F) {
          pan = (int)(((ex * rx + ez * rz) / el) * 100.0F);
          if (pan > 100) pan = 100; else if (pan < -100) pan = -100;
        }
      }
    }
    // Master SFX volume (menu "Sound volume" option block); 100 = unscaled.
    vol = vol * scriptCtx.sfxVolume / 100;
    // audsrv RPCs are synchronous and share one client lock with the music
    // stream - an RPC per emitter per frame stalls the main thread whenever
    // the song thread holds the lock (measured 50 -> 42 FPS in PCSX2 with
    // one emitter + music). Quantize and only send real changes; a static
    // player near a static emitter then costs zero RPCs per frame. The
    // quantization is also what the steal margin is measured in.
    vol = ((vol + 2) / 5) * 5;
    if (vol > 100) vol = 100;
    if (vol <= 0) continue;  // inaudible: wants no channel at all
    pan = pan >= 0 ? ((pan + 5) / 10) * 10 : -(((-pan + 5) / 10) * 10);
    SoundWant w;
    w.obj = i;
    w.vol = vol;
    w.pan = pan;
    w.prio = o.data.sndPriority;
    sndWants.push_back(w);
  }

  // Pass 2: hand the eight channels to the loudest of them.
  pickSoundSlots(sndWants);

  // Pass 3: drive each channel. Emitters own channels 16-23 OF THE ROOM'S
  // BUS: +0 on core 1, +24 on core 0 (docs/reverb.md). A room change moves an
  // emitter to a different channel, and its next trigger is heard through the
  // incoming room while whatever it has in flight finishes in the outgoing one.
  for (int s = 0; s < 8; ++s) {
    const s8 ch = (s8)(scriptCtx.reverbBusBase + 16 + s);
    if (sndChBus[s] != scriptCtx.reverbBusBase) {
      // The cached volume/pan describe the channel on the bus we just left, so
      // they say nothing about this one - force the writes below.
      sndChVol[s] = -1;
      sndChPan[s] = -999;
      sndChBus[s] = scriptCtx.reverbBusBase;
    }
    const int owner = sndSlotOwner[s];
    if (owner < 0) {
      // Nobody wants this channel. Mute it once so a stale level cannot come
      // back with the next emitter that lands here before its own write.
      if (sndChVol[s] != 0) {
        engine->audio.adpcm.setVolume(0, ch);
        sndChVol[s] = 0;
      }
      continue;
    }
    // The want computed in pass 1 (the ranking already found it, so this is a
    // lookup and not a recomputation).
    const SoundWant* want = sndWantOf(sndWants, owner);
    const int vol = want ? want->vol : 0;
    const int pan = want ? want->pan : 0;
    if (vol != sndChVol[s] || pan != sndChPan[s]) {
      engine->audio.adpcm.setVolumeAndPan((u8)vol, (s8)pan, ch);
      sndChVol[s] = vol;
      sndChPan[s] = pan;
    }
    // An emitter with no channel does not tick either: its interval starts
    // counting when it is loud enough to be heard, so walking up to a 10 s
    // emitter cannot make it fire instantly with a countdown it spent silent.
    if (sndTimers[owner] > 0) {
      --sndTimers[owner];
      continue;
    }
    const RuntimeObject& o = runtimeObjects[owner];
    // Reverb send for this channel. The send is one BIT per voice, so an
    // emitter opting out just clears its channel's bit - and because a channel
    // changes hands, the emitter that plays owns the setting. AudioReverb
    // holds the mask and compares before touching the hardware, which is also
    // why nothing here keeps a copy: Play Sound nodes write the same mask from
    // the generated graphs, and a second cache would let the two clobber each
    // other's bits.
    engine->audio.reverb.setChannelSend(ch, o.data.sndReverb != 0);
    if (engine->audio.adpcm.tryPlay(sndSamples[o.data.snd], ch) == ADPCM_OK)
      // It really started: a Speaker (lip-sync) starts reading its envelope.
      for (int k = 0; k < LIP_SYNC_COUNT; ++k) {
        const LipSyncData& ls = LIP_SYNCS[k];
        if (ls.scene != g_activeScene || ls.emitter != owner) continue;
        if (ls.speaker < 0 || ls.speaker >= (int)objectGeometry.size()) continue;
        ObjectGeometry& sg = objectGeometry[ls.speaker];
        sg.lipEnv = &LIP_ENVELOPES[ls.first];
        sg.lipLen = ls.count;
        sg.lipT = 0.0F;
      }
    sndTimers[owner] = everyFrames(o.data.sndInterval);
  }
}



// --- Reverb zones -----------------------------------------------------
// docs/reverb.md. The SPU2 has ONE reverb unit and audsrv puts every sound
// effect on its core, so "which room am I in" is a single global decision
// made here once per frame. The cost is a few dot products plus, at most, one
// IOP RPC - the mixing itself is the sound chip's, not the EE's.
void TerrainGame::updateReverb() {
  // Compile-time: a project with no reverb zone and no Set Reverb node still
  // has this function, but the whole body folds away to nothing.
  if (REVERB_ZONE_COUNT == 0 && !REVERB_HAS_NODE) return;

  int wantPreset = 0;   // nothing found = dry
  int wantAmount = 0;   // 0..100
  int wantDelay = 64, wantFeedback = 64;

  if (scriptCtx.reverbPreset >= 0) {
    // A Set Reverb node is in force: it overrides the geometry outright.
    wantPreset = scriptCtx.reverbPreset;
    wantAmount = scriptCtx.reverbAmount;
    wantDelay = scriptCtx.reverbDelay;
    wantFeedback = scriptCtx.reverbFeedback;
  } else {
    // The listener is player 1. With split-screen two players can stand in
    // different rooms and there is still only one reverb - that is a real
    // limit of the hardware, documented rather than papered over.
    const float lx = scriptCtx.playerPosition.x;
    const float ly = scriptCtx.playerPosition.y;
    const float lz = scriptCtx.playerPosition.z;
    int bestPrio = 0;
    bool found = false;
    for (int i = 0; i < REVERB_ZONE_COUNT; ++i) {
      const ReverbZoneData& z = REVERB_ZONES[i];
      if (z.scene != g_activeScene) continue;
      if (z.object < 0 || z.object >= (int)runtimeObjects.size()) continue;
      const RuntimeObject& a = runtimeObjects[z.object];
      // An area on an unloaded streaming layer catches nobody, exactly like a
      // layer zone or an In Area trigger.
      if (!a.active) continue;
      if (!pointInArea(a.data, lx, ly, lz)) continue;
      // Ties go to the later zone, so a room authored on top of another wins
      // without needing a priority typed in.
      if (found && z.priority < bestPrio) continue;
      bestPrio = z.priority;
      found = true;
      wantPreset = z.preset;
      wantAmount = z.amount;
      wantDelay = z.delay;
      wantFeedback = z.feedback;
    }
  }

  // "Silence" covers both "no zone here" and an authored preset of Off: either
  // way the answer is to ramp this bus down, NOT to hand the room to the other
  // one. Skipping the swap there is what stops a player stepping in and out of
  // a doorway from zeroing a work area every time.
  const bool wantSilence = wantPreset == 0 || wantAmount <= 0;

  // A change of ALGORITHM goes to the other bus, which can only take it while
  // it is silent - its work area is about to be zeroed. If the other bus is
  // still fading out (a second room entered before the first finished leaving)
  // this simply waits, and the ramp below keeps running meanwhile.
  const int other = 1 - reverbBus;
  if (!wantSilence && wantPreset != reverbPresetCur[reverbBus] &&
      reverbAmt[other] <= 0.0F) {
    const Tyra::AudioReverb::Bus b = other == 0 ? Tyra::AudioReverb::BusA
                                                : Tyra::AudioReverb::BusB;
    reverbPresetCur[other] = wantPreset;
    engine->audio.reverb.setDelay(b, (u8)wantDelay);
    engine->audio.reverb.setFeedback(b, (u8)wantFeedback);
    engine->audio.reverb.setPreset(b, (Tyra::AudioReverb::Preset)wantPreset);
    // From this frame on, new sounds play on the incoming room's core. The
    // ones already in flight keep going on the outgoing bus and finish in the
    // room they started in.
    reverbBus = other;
    scriptCtx.reverbBusBase = reverbBus * 24;
  }

  // The active bus goes to the room's amount, the other one to zero: that IS
  // the cross-fade. ~0.3 s for the full travel, frame-rate independent.
  const float step = g_frameDt * (1.0F / 0.3F);
  for (int b = 0; b < 2; ++b) {
    float goal = 0.0F;
    if (b == reverbBus && !wantSilence) goal = (float)wantAmount * 0.01F;
    if (reverbAmt[b] < goal) {
      reverbAmt[b] += step;
      if (reverbAmt[b] > goal) reverbAmt[b] = goal;
    } else if (reverbAmt[b] > goal) {
      reverbAmt[b] -= step;
      if (reverbAmt[b] < goal) reverbAmt[b] = goal;
    }

    // Quantize to 64 steps and only push a real change: this is a synchronous
    // RPC to the IOP, sharing the SIF with the music stream.
    int q = (int)(reverbAmt[b] * 64.0F + 0.5F);
    if (q < 0) q = 0;
    if (q > 64) q = 64;
    if (q != reverbDepthSent[b]) {
      reverbDepthSent[b] = q;
      const s16 depth = (s16)((q * 0x7FFF) / 64);
      engine->audio.reverb.setDepth(
          b == 0 ? Tyra::AudioReverb::BusA : Tyra::AudioReverb::BusB, depth,
          depth);
    }
  }
}



void TerrainGame::buildParticles() {
  particles.clear();
  for (int i = 0; i < (int)runtimeObjects.size(); ++i) {
    if (runtimeObjects[i].data.type != 7) continue;
    if (!runtimeObjects[i].active) continue;  // emitter streamed out - no pool
    buildParticleSystem(i, -1);
    // The library effect's extra layers (docs/particles.md): authored objects
    // only - a spawned clone's index is not the one the table was keyed by.
    if (i < SCENE_OBJECT_COUNT)
      for (int k = 0; k < EMITTER_LAYER_COUNT; ++k)
        if (EMITTER_LAYERS[k].scene == currentScene && EMITTER_LAYERS[k].object == i)
          buildParticleSystem(i, k);
  }
}



void TerrainGame::buildParticleSystem(int i, int layer) {
  {
    const SceneObjectData& src =
        layer >= 0 ? EMITTER_LAYER_OBJECTS[layer] : runtimeObjects[i].data;
    ParticleSystem ps;
    ps.objectIndex = i;
    ps.layer = layer;
    ps.rng = 12345u + (unsigned int)i * 7919u + (unsigned int)(layer + 1) * 104729u;
    int n = src.emitCount;  // data copy: spawn slots too
    if (n < 1) n = 1;
    if (n > 256) n = 256;
    ps.pos.assign(n, Vec4(0.0F, 0.0F, 0.0F, 1.0F));
    ps.vel.assign(n, Vec4(0.0F, 0.0F, 0.0F, 0.0F));
    ps.life.assign(n, 0.0F);  // dead -> staggered respawn over the first frames
    ps.maxLife.assign(n, 1.0F);
    ps.params.assign(n, Vec4(0.0F, 0.0F, 0.0F, 0.0F));
    ps.cols.assign(n, Color(0.0F, 0.0F, 0.0F, 0.0F));
    ps.infoBag = std::make_unique<StaPipInfoBag>();
    ps.infoBag->model = &model;
    ps.infoBag->shadingType = TyraShadingGouraud;
    // VU1 billboard bags cull per quad on VU1 - no EE frustum/clip work.
    // None is safe for billboard bags only: the VU1 program ADCs any quad
    // whose corner leaves the GS raster window (ordinary bags must never
    // use None - see the engine skill's wrap pitfall).
    ps.infoBag->frustumCulling = PipelineInfoBagFrustumCulling_None;
    ps.infoBag->fullClipChecks = false;
    ps.colorBag = std::make_unique<StaPipColorBag>();
    ps.cols.bind(ps.colorBag);
    ps.billboardBag = std::make_unique<StaPipBillboardBag>();
    ps.bag = std::make_unique<StaPipBag>();
    ps.bag->info = ps.infoBag.get();
    ps.bag->color = ps.colorBag.get();
    ps.bag->lighting = nullptr;
    ps.bag->billboard = ps.billboardBag.get();
    ps.pos.bind(ps.bag);
    ps.bag->count = 0;
    // The texture bag is mandatory for billboard bags - its coordinates
    // channel carries the per-particle basis weights. Textured particles:
    // the emitter's material supplies the map (its Kd is ignored - the
    // emitter color is the tint); corner UVs are fixed in the VU1 program.
    ps.texBag = std::make_unique<StaPipTextureBag>();
    ps.texBag->texture = nullptr;
    ps.params.bind(ps.texBag);
    const int mi = src.material;  // data copy: spawn slots too
    if (mi >= 0 && mi < (int)gameMaterials.size() && gameMaterials[mi].texture)
      ps.texBag->texture = gameMaterials[mi].texture;
    ps.bag->texture = ps.texBag.get();
    // Depth-tested but never writing depth - the tyre smoke's rule: a
    // translucent puff that wrote Z carved a soft-edged texture's whole quad
    // out of every puff drawn after it (docs/particles.md). Additive emitters
    // (fire, sparks) add light on top: Cs * FIX + Cd.
    ps.infoBag->zTestType = PipelineZTest_TestOnly;
    if (src.emitAdditive) ps.infoBag->additiveBlendFix = 128;
    particles.push_back(std::move(ps));
  }
}



void TerrainGame::updateParticles() {
  if (particles.empty() || !g_particlesOn) return;  // Set Particles switch
  // Paused: leave every billboard bag exactly as it was last built - the
  // scene render still draws them, so particles hang frozen behind the menu.
  if (g_gameplayPaused) return;
  const float dt = g_frameDt;

  // camera right/up shared by every billboard basis this frame
  Vec4 fwd = cameraLookAt - cameraPosition;
  const float fl = sqrtf(fwd.x * fwd.x + fwd.y * fwd.y + fwd.z * fwd.z);
  if (fl > 0.0001F) fwd.x /= fl, fwd.y /= fl, fwd.z /= fl;
  float rx = fwd.z, rz = -fwd.x;
  const float rl = sqrtf(rx * rx + rz * rz);
  if (rl > 0.0001F) rx /= rl, rz /= rl;
  else rx = 1.0F, rz = 0.0F;
  const float ux = -rz * fwd.y;
  const float uy = rz * fwd.x - rx * fwd.z;
  const float uz = rx * fwd.y;

  for (ParticleSystem& ps : particles) {
    const RuntimeObject& o = runtimeObjects[ps.objectIndex];
    if (!o.active || !o.visible) {
      ps.bag->count = 0;  // Hide Object turns the emitter off
      continue;
    }
    // An extra layer wears its EMITTER_LAYERS row, placed and turned by the
    // live emitter (so moving or hiding the emitter moves or hides them all).
    SceneObjectData layerData;
    if (ps.layer >= 0) {
      layerData = EMITTER_LAYER_OBJECTS[ps.layer];
      const EmitterLayerData& L = EMITTER_LAYERS[ps.layer];
      for (int a = 0; a < 3; ++a) {
        layerData.position[a] = o.data.position[a] + L.offset[a];
        layerData.rotation[a] = o.data.rotation[a];
        layerData.scale[a] = o.data.scale[a] * L.area[a];
      }
      layerData.emitEnabled = o.data.emitEnabled;
      layerData.emitFollow = o.data.emitFollow;
    }
    const SceneObjectData& d = ps.layer >= 0 ? layerData : o.data;
    const int kind = d.emitKind;
    const int n = (int)ps.life.size();

    // Flipbook (docs/particles.md): frames live at material .. material+N-1,
    // and animating is swapping the ONE bag's texture pointer - no extra
    // submit, no per-particle work.
    ps.animTime += dt;  // the flipbook's clock and the fire's sway/flicker
    if (d.emitFrames > 1 && d.material >= 0) {
      const int f = (int)(ps.animTime * d.emitFps) % d.emitFrames;
      const int mi = d.material + f;
      if (mi < (int)gameMaterials.size() && gameMaterials[mi].texture)
        ps.texBag->texture = gameMaterials[mi].texture;
    }

    // Per-emitter billboard basis for the VU1 expansion. Rain streaks hang
    // from world-up (vertical quads); everything else faces the camera
    // plane. A portal pass re-renders these bags with the VIRTUAL camera's
    // basis swapped in - the centers below are view-independent.
    ps.billboardBag->right = Vec4(rx, 0.0F, rz, 0.0F);
    ps.billboardBag->up = kind == 4 ? Vec4(0.0F, 1.0F, 0.0F, 0.0F)
                                    : Vec4(ux, uy, uz, 0.0F);

    // Follow player: the emitter position becomes an offset from the camera
    // (place it at X=0/Z=0 and the height above the player's head) - rain
    // that tracks the player instead of soaking the whole map.
    float bx = d.position[0], by = d.position[1], bz = d.position[2];
    if (d.emitFollow) {
      bx += cameraPosition.x;
      by += cameraPosition.y;
      bz += cameraPosition.z;
    }
    // Automatic overdraw budget: simulation remains exact, but while the
    // adaptive raster is paying back a missed field, distant emitters submit
    // half their quads. Player-following rain/fog stays full density because
    // it surrounds the camera and the reduction would be immediately visible.
    int drawN = n;
    if (adaptiveReduced && !d.emitFollow) {
      const float pdx = bx - cameraPosition.x;
      const float pdy = by - cameraPosition.y;
      const float pdz = bz - cameraPosition.z;
      if (pdx * pdx + pdy * pdy + pdz * pdz > 144.0F)
        drawN = (n + 1) / 2;
    }

    // Custom kind: emission direction = the object's +Y axis rotated by the
    // object rotation (tilt the emitter for a horizontal pipe leak), plus an
    // orthonormal tangent basis for the spread cone.
    V3 edir = {0.0F, 1.0F, 0.0F}, et1 = {1.0F, 0.0F, 0.0F},
       et2 = {0.0F, 0.0F, 1.0F};
    if (kind == 5) {
      edir = rotated({0.0F, 1.0F, 0.0F}, d.rotation);
      const V3 seed =
          fabsf(edir.y) < 0.9F ? V3{0.0F, 1.0F, 0.0F} : V3{1.0F, 0.0F, 0.0F};
      et1 = {seed.y * edir.z - seed.z * edir.y, seed.z * edir.x - seed.x * edir.z,
             seed.x * edir.y - seed.y * edir.x};
      const float tl =
          sqrtf(et1.x * et1.x + et1.y * et1.y + et1.z * et1.z);
      if (tl > 0.0001F) et1.x /= tl, et1.y /= tl, et1.z /= tl;
      et2 = {edir.y * et1.z - edir.z * et1.y, edir.z * et1.x - edir.x * et1.z,
             edir.x * et1.y - edir.y * et1.x};
    }

    // Fire (docs/particles.md, "The fire motion"): the whole flame sways and
    // flickers together - once per emitter per frame, not per particle. Keep
    // in sync with drawEmitterPreviews.
    const float fT = ps.animTime;
    const float fireSwayX = kind == 0 ? 0.35F * sinf(fT * 1.7F) + 0.15F * sinf(fT * 4.3F) : 0.0F;
    const float fireSwayZ = kind == 0 ? 0.25F * sinf(fT * 1.3F + 1.0F) : 0.0F;
    const float fireFlicker =
        kind == 0 ? 0.8F + 0.2F * sinf(fT * 13.7F) * sinf(fT * 5.9F + 0.7F) : 1.0F;

    for (int i = 0; i < n; ++i) {
      ps.life[i] -= dt;
      if (ps.life[i] <= 0.0F) {
        const float r1 = prand(ps.rng), r2 = prand(ps.rng), r3 = prand(ps.rng);
        const float sx = bx + (r1 - 0.5F) * d.scale[0];
        const float sz = bz + (r3 - 0.5F) * d.scale[2];
        ps.pos[i] = Vec4(sx, by, sz, 1.0F);
        if (kind == 0) {  // fire: a centre-weighted base, slow start - buoyancy does the rest
          const float r4 = prand(ps.rng);
          ps.pos[i].x = bx + (r1 + r4 - 1.0F) * 0.5F * d.scale[0];
          ps.pos[i].z = bz + (r3 + r2 - 1.0F) * 0.5F * d.scale[2];
          ps.vel[i] = Vec4((r1 - 0.5F) * 0.3F, 0.6F + r2 * 0.6F, (r3 - 0.5F) * 0.3F, 0.0F);
          ps.maxLife[i] = 0.55F + r2 * 0.5F;
        } else if (kind == 1) {  // smoke: slow rise with drift
          ps.vel[i] = Vec4((r1 - 0.5F) * 0.5F, 0.5F + r2 * 0.5F, (r3 - 0.5F) * 0.5F, 0.0F);
          ps.maxLife[i] = 2.0F + r2 * 1.5F;
        } else if (kind == 2) {  // fog: big lazy puffs hugging the ground
          ps.vel[i] = Vec4((r1 - 0.5F) * 0.25F, 0.02F, (r3 - 0.5F) * 0.25F, 0.0F);
          ps.maxLife[i] = 3.0F + r2 * 3.0F;
        } else if (kind == 4) {  // rain: fast streaks, die on the terrain
          const float fall = 14.0F + r2 * 6.0F;
          ps.vel[i] = Vec4((r1 - 0.5F) * 0.6F, -fall, (r3 - 0.5F) * 0.6F, 0.0F);
          // Fall distance = how far the ground is below the emitter. With no
          // terrain (docs/terrain.md) that is the void, and a drop would live
          // for hours - so the emitter's own height is the fall instead, which
          // keeps the volume raining.
          float drop = TERRAIN_ENABLED ? by - terrainHeightAt(sx, sz)
                                       : d.scale[1];
          if (drop < 0.5F) drop = 0.5F;
          ps.maxLife[i] = drop / fall;
        } else if (kind == 5) {  // custom: cone jet, physics from the knobs
          const float th = d.emitSpread * (PI / 180.0F) * prand(ps.rng);
          const float ph = 2.0F * PI * prand(ps.rng);
          const float ct = cosf(th), st = sinf(th);
          const float cp = cosf(ph), sp = sinf(ph);
          const float spd = d.emitSpeed * (0.8F + 0.4F * r2);
          ps.vel[i] = Vec4((edir.x * ct + (et1.x * cp + et2.x * sp) * st) * spd,
                           (edir.y * ct + (et1.y * cp + et2.y * sp) * st) * spd,
                           (edir.z * ct + (et1.z * cp + et2.z * sp) * st) * spd,
                           0.0F);
          ps.maxLife[i] = d.emitLife * (0.75F + 0.5F * r1);
        } else {  // sparks: radial burst pulled down by gravity
          ps.vel[i] = Vec4((r1 - 0.5F) * 5.0F, 1.5F + r2 * 2.5F, (r3 - 0.5F) * 5.0F, 0.0F);
          ps.maxLife[i] = 0.35F + r2 * 0.5F;
        }
        ps.life[i] = ps.maxLife[i] * (0.05F + 0.95F * prand(ps.rng));  // stagger
      }
      if (kind == 3) ps.vel[i].y -= 6.0F * dt;
      if (kind == 0) {
        // Hot gas ACCELERATES upward, and the column pulls in on itself, so
        // the tongues stretch and taper into a point; the sway grows with
        // height, as it does on a real flame.
        ps.vel[i].y += 2.6F * dt;
        ps.vel[i].x += (bx - ps.pos[i].x) * 2.2F * dt;
        ps.vel[i].z += (bz - ps.pos[i].z) * 2.2F * dt;
        const float h = ps.pos[i].y - by;
        ps.pos[i].x += fireSwayX * h * dt;
        ps.pos[i].z += fireSwayZ * h * dt;
      }
      if (kind == 5) {
        // gravity + air drag ~ 1/weight: applied after the pull, so heavy
        // particles keep falling while light ones reach a slow terminal
        // drift (steam) - a natural terminal velocity
        ps.vel[i].y -= d.emitGravity * dt;
        const float w = d.emitWeight < 0.05F ? 0.05F : d.emitWeight;
        float damp = 1.0F - (0.6F / w) * dt;
        if (damp < 0.0F) damp = 0.0F;
        ps.vel[i].x *= damp;
        ps.vel[i].y *= damp;
        ps.vel[i].z *= damp;
      }
      ps.pos[i].x += ps.vel[i].x * dt;
      ps.pos[i].y += ps.vel[i].y * dt;
      ps.pos[i].z += ps.vel[i].z * dt;
      // custom + Die on terrain: the particle vanishes this frame (alpha 0)
      // and respawns next - water soaks into the ground instead of clipping
      if (kind == 5 && d.emitDieGround &&
          ps.pos[i].y <= terrainHeightAt(ps.pos[i].x, ps.pos[i].z))
        ps.life[i] = 0.0F;

      // life fraction drives size, alpha (0-128) and the color ramp
      const float t = ps.life[i] / ps.maxLife[i];
      float size = d.emitSize;
      float sizeUp = 0.0F;  // rain: extra world-up half-height (streaks)
      float alpha;
      float cr = d.color[0] * 128.0F, cg = d.color[1] * 128.0F, cb = d.color[2] * 128.0F;
      if (kind == 0) {
        // unfurls quickly at birth, then narrows toward the tip; fades IN
        // (no pop at the base) and the whole fire flickers
        const float age = 1.0F - t;
        const float unfurl = age < 0.15F ? 0.45F + age * (0.55F / 0.15F) : 1.0F;
        size *= unfurl * (0.35F + 0.75F * t);
        alpha = 96.0F * (age < 0.1F ? age * 10.0F : 1.0F) * (0.35F + 0.65F * t) *
                fireFlicker;
        cg *= 0.35F + 0.65F * t;  // orange cools to red as it dies
        cb *= 0.25F * t;
      } else if (kind == 1) {
        size *= 1.6F - t;  // smoke grows while fading
        alpha = 40.0F * t;
      } else if (kind == 2) {
        size *= 3.0F;
        // density knob: Opacity 0..1 -> peak alpha 0..60 (old look ~= 0.3)
        alpha = d.emitOpacity * 60.0F *
                (t < 0.5F ? t * 2.0F : (1.0F - t) * 2.0F);  // fade in+out
      } else if (kind == 4) {
        sizeUp = size * 0.5F;  // size = streak length
        size *= 0.06F;         // thin
        alpha = 70.0F * (t < 0.15F ? t * (1.0F / 0.15F) : 1.0F);  // fade at impact
      } else if (kind == 5) {
        size *= 1.0F + (d.emitGrow - 1.0F) * (1.0F - t);  // 1 -> Grow over life
        alpha = d.emitOpacity * 128.0F * (t < 0.25F ? t * 4.0F : 1.0F);
      } else {
        size *= 0.35F;
        alpha = 110.0F * t;
      }

      // The quad itself is built on VU1: corner = center +/- (right*m00 +
      // up*m01) +/- (right*m10 + up*m11). Rain streaks hang from world-up
      // (the emitter basis above) with an independent half-height; fog
      // puffs additionally swirl - the billboard slowly rotates in the
      // camera plane, alternating direction per puff (the swirling fog
      // roll) - keep in sync with the viewport preview
      // (drawEmitterPreviews).
      float m00 = size, m01 = 0.0F, m10 = 0.0F, m11 = size;
      if (kind == 2) {
        const float age = ps.maxLife[i] - ps.life[i];
        const float ang = (float)i * 2.4F + (i & 1 ? 0.3F : -0.3F) * age;
        const float ca = cosf(ang), sa = sinf(ang);
        m00 = ca * size;
        m01 = sa * size;
        m10 = -sa * size;
        m11 = ca * size;
      }
      if (sizeUp > 0.0F) m11 = sizeUp;  // rain: thin width, streak height
      if (kind == 0) m11 *= 1.45F;      // flames are taller than wide
      // The camera basis above is (screen-LEFT, screen-DOWN) - the world is
      // viewed down +Z with +X on the left - so a quad built on it is turned
      // 180 degrees and a texture shows upside down (a symmetric puff hid it
      // for years; a flame did not). Negating the weights turns it back in
      // EVERY pass, the portal and split views included, which rebuild the
      // basis but never these. Rain hangs from world-up and is left alone.
      // Every other particle is also mirrored on odd slots - free variety
      // for one texture. Keep in sync with drawEmitterPreviews.
      if (kind != 4) {
        const float mir = (i & 1) && kind != 2 ? -1.0F : 1.0F;
        m00 = -m00 * mir, m01 = -m01 * mir, m10 = -m10, m11 = -m11;
      }
      ps.params[i] = Vec4(m00, m01, m10, m11);
      // Additive (docs/particles.md): the GS adds Cs * FIX and never reads
      // alpha, so the fade has to ride the colour - keep in sync with the
      // viewport preview (drawEmitterPreviews).
      if (d.emitAdditive) {
        const float k = alpha * (1.0F / 128.0F);
        cr *= k, cg *= k, cb *= k;
      }
      ps.cols[i] = Color(cr, cg, cb, alpha);
    }
    ps.bag->count = (u32)drawN;
  }
}


// Picks the nearest usable object the camera is close to and looking at
// (thresholds in controls.hpp). BTN_USE on it -> scriptCtx.usedObject for
// one frame, which fires the flow graph "On Used" trigger.
void TerrainGame::updateUseTarget() {
  useTargetIndex = -1;
  scriptCtx.usedObject = -1;
  // Hands full: BTN_USE means "drop" (updateCarriedObject), so no use
  // targeting - and no prompt - while carrying.
  if (carryIndex >= 0) return;
  // A "Hide HUD" cutscene suppresses the whole interaction, not just its
  // prompt. Note this test runs from the PLAYER's camera and BEFORE the
  // cutscene override is applied further down, so a cutscene changes nothing
  // about it by itself: a player left standing in front of a usable prop -
  // usually the one whose On Used started the cutscene - keeps the prompt on
  // screen over the cinematic and can press it again. Tied to that flag and not
  // to "a cutscene is playing", because a cutscene that animates something
  // while the player keeps the camera must keep USE working
  // (docs/cutscenes.md).
  if (scriptCtx.hudSuppressed) return;

  Vec4 dir = cameraLookAt - cameraPosition;
  const float dirLen = sqrtf(dir.x * dir.x + dir.y * dir.y + dir.z * dir.z);
  if (dirLen < 0.0001F) return;
  dir.x /= dirLen, dir.y /= dirLen, dir.z /= dirLen;

  float bestDist = 0.0F;
  for (int i = 0; i < (int)runtimeObjects.size(); ++i) {
    const RuntimeObject& o = runtimeObjects[i];
    if (!o.active || !(o.data.usable || o.data.pickable) || !o.visible) continue;
    if (o.data.type == 4 || o.data.type == 6 || o.data.type == 7 ||
        o.data.type == 8 || o.data.type == 9 || o.data.type == 11 ||
        o.data.type == 14 || o.data.type == 17 || o.data.type == 18 ||
        o.data.type == 19 || o.data.type == 20)
      continue;

    const float dx = o.data.position[0] - cameraPosition.x;
    const float dy = o.data.position[1] - cameraPosition.y;
    const float dz = o.data.position[2] - cameraPosition.z;
    const float dist = sqrtf(dx * dx + dy * dy + dz * dz);
    float half = o.data.scale[0];
    if (o.data.scale[1] > half) half = o.data.scale[1];
    if (o.data.scale[2] > half) half = o.data.scale[2];
    half *= 0.5F;
    if (dist > USE_DISTANCE + half || dist < 0.001F) continue;

    const float dot = (dx * dir.x + dy * dir.y + dz * dir.z) / dist;
    if (dot < USE_LOOK_DOT && dist > half) continue;  // inside = always "looking"

    if (useTargetIndex < 0 || dist < bestDist) {
      useTargetIndex = i;
      bestDist = dist;
    }
  }

  if (useTargetIndex >= 0 && inputClicked(engine->pad, IA_ROLE_USE)) {
    // A pickable object can also be usable: it fires On Used AND gets picked
    // up on the same press (a grab sound wired in the graph, for instance).
    if (runtimeObjects[useTargetIndex].data.usable)
      scriptCtx.usedObject = useTargetIndex;

    if (runtimeObjects[useTargetIndex].data.pickable) {
      carryIndex = useTargetIndex;
      carryGrabbed = true;  // don't read this same press as "drop"
      if (thrownIndex == carryIndex) thrownIndex = -1;  // caught mid-flight
      RuntimeObject& g = runtimeObjects[carryIndex];
      // Catching a body kills its momentum and its tumble (a crate caught
      // mid-flight must not keep spinning in your hands).
      g.velocityX = g.velocityY = g.velocityZ = 0.0F;
      g.spin[0] = g.spin[1] = g.spin[2] = 0.0F;
      // Seed the smoothed reach with the object's current distance: a close
      // grab reels out to full reach, a far one snaps in (the sweep rule).
      const float gx = g.data.position[0] - cameraPosition.x;
      const float gy = g.data.position[1] - cameraPosition.y;
      const float gz = g.data.position[2] - cameraPosition.z;
      carryDist = sqrtf(gx * gx + gy * gy + gz * gz);
      // Logged for the same reason the portal hops are: a report like "I
      // picked it up and something threw me across the room" can only be
      // read off a log if the grab is IN that log, next to the hop. The
      // player position rides along - it is the frame's other half.
      TYRA_LOG("Pick: grabbed ", carryIndex, " at ", g.data.position[0], " ",
               g.data.position[1], " ", g.data.position[2], ", eye ",
               cameraPosition.x, " ", cameraPosition.y, " ",
               cameraPosition.z);
      inputreplay::note(inputreplay::EV_GRAB, carryIndex, -1);
    }
  }

  // Using a save point (type 10) opens the save menu next frame; the
  // "On Used" trigger still fires for its flow graph this frame.
  if (scriptCtx.usedObject >= 0 &&
      SCENE_OBJECTS[scriptCtx.usedObject].type == 10)
    scriptCtx.openSaveMenu = true;
}



// Largest half extent of an object's collision box (mesh/anim AABB when the
// object has one, else the unit scale box) - the sweep radius that keeps the
// whole object clear of walls while carried or in flight.
float TerrainGame::objectHalfExtent(const RuntimeObject& o) const {
  float ex = 0.5F * o.data.scale[0], ey = 0.5F * o.data.scale[1],
        ez = 0.5F * o.data.scale[2];
  const GameModel* gm = nullptr;
  if (o.data.type == 5 && o.data.model >= 0 &&
      o.data.model < (int)gameModels.size())
    gm = &gameModels[o.data.model];
  const SkelModel* anim = nullptr;
  if (o.data.type == 5 && o.data.animModel >= 0 &&
      o.data.animModel < (int)gameAnimModels.size())
    anim = gameAnimModels[o.data.animModel].src.get();
  const float* mn = gm ? gm->mn : (anim ? anim->min : nullptr);
  const float* mx = gm ? gm->mx : (anim ? anim->max : nullptr);
  if (mn && mx) {
    ex = 0.5F * (mx[0] - mn[0]) * o.data.scale[0];
    ey = 0.5F * (mx[1] - mn[1]) * o.data.scale[1];
    ez = 0.5F * (mx[2] - mn[2]) * o.data.scale[2];
  }
  float r = ex > ey ? ex : ey;
  if (ez > r) r = ez;
  if (r < 0.05F) r = 0.05F;
  return r;
}



// Carry whisker: the third-person spring arm's pre-block, turned around.
// The spring arm pulls the CAMERA in when the boom sweep hits a wall; here
// the same sweep pushes the WALKER back when the carried object no longer
// fits in front of the face - so pressing "face first" against a wall while
// carrying is simply blocked, instead of the object being parked inside the
// wall. Called by every walker after collidePlayer, on the carrying player
// only. The probe is horizontal (yaw only): with the look pitch in it, the
// terrain underfoot would read as a wall whenever the player looks down.
void TerrainGame::applyCarryWhisker(float prevX, float prevZ, float* nextX,
                                    float* nextZ, float probeY, float yaw,
                                    float feetY, float eyeHeight) {
  if (carryIndex < 0) return;
  const RuntimeObject& o = runtimeObjects[carryIndex];
  if (!o.active || !o.visible) return;
  const float r = objectHalfExtent(o);
  const float need = 0.55F + r;  // the object fully outside the carrier
  const float hx = sinf(yaw), hz = cosf(yaw);
  // Walking a carried object INTO a portal opening must not read the
  // mounting wall as a blocker. portalPassOn (the player's body is IN the
  // opening, published by updatePortalPass and still live here) is
  // authoritative and takes precedence: once the player reaches the plane
  // the forward probe below no longer starts in FRONT of it, so on its own
  // the doorway would slam shut exactly at the crossing and the whisker
  // would bounce the player back out (owner: can't walk through a portal
  // while carrying). The forward probe still covers the approach, before
  // the body column enters the opening.
  if (portalPassOn) {
    sweepPassPlane[0] = portalPassPlane[0];
    sweepPassPlane[1] = portalPassPlane[1];
    sweepPassPlane[2] = portalPassPlane[2];
    sweepPassPlane[3] = portalPassPlane[3];
    sweepPassPoint[0] = portalPassPoint[0];
    sweepPassPoint[1] = portalPassPoint[1];
    sweepPassPoint[2] = portalPassPoint[2];
    sweepPassOn = true;
  } else {
    const float reach = need + r + 0.1F;
    const float a0[3] = {*nextX, probeY, *nextZ};
    const float b0[3] = {*nextX + hx * reach, probeY, *nextZ + hz * reach};
    armSweepPass(a0, b0);
  }
  const float d =
      sweepSphere(*nextX, probeY, *nextZ, hx, 0.0F, hz, need, r, carryIndex);
  sweepPassOn = false;
  if (d < need) {
    // The whisker BLOCKS a step, it does not shove: never take back more
    // than the step that was actually taken. Without this cap the pushback
    // is `need` (0.55 + the object's radius) EVERY frame the probe starts
    // inside something, whatever the player does - and a sweep that begins
    // inside geometry returns 0, which is what a room modelled as one
    // collision mesh does to a probe standing in it. Grabbing a weight in
    // the showcase's cellar therefore slid the walker 0.75 of a unit per
    // frame, 45 a second, with the stick centred, until it was pinned in a
    // corner: "some unknown force moves the player", owner's portal-ball
    // recording, frames 391-407 and again at 712. Standing still now takes
    // back nothing, and walking face-first into a wall with a crate still
    // stops exactly where it always did.
    float back = need - d;
    const float stepX = *nextX - prevX, stepZ = *nextZ - prevZ;
    const float step = sqrtf(stepX * stepX + stepZ * stepZ);
    if (back > step) back = step;
    if (back <= 0.0F) return;
    const float px = *nextX, pz = *nextZ;
    *nextX -= hx * back;
    *nextZ -= hz * back;
    // The pushback is a displacement collidePlayer never saw - unswept it
    // shoves the walker clean through whatever stands at their back (owner
    // repro: carry + reverse into a wall = teleported behind it). Re-run
    // the collision from the pre-push spot; ground/ceiling are discarded.
    float g2 = -1e30F, c2 = 1e30F;
    collidePlayer(px, pz, nextX, nextZ, feetY, eyeHeight, &g2, &c2);
  }
}



// Carried + thrown pickable objects. The carried one rides PICK_CARRY_DIST in
// front of the face, swept against the world each frame so it can neither be
// pushed through a wall nor parked behind one - blocked reach just brings it
// closer. It keeps colliding with the world (the sweep) but not with its
// carrier (collidePlayer/springArm skip it), so it cannot wedge the player.
// BTN_USE drops it in place - already a swept, legal spot - and BTN_THROW
// launches it when the object allows that.
void TerrainGame::updateCarriedObject() {
  // In-flight object: only objects WITHOUT a rigid body reach this path -
  // a thrown physics object is handed straight to updateObjectPhysics
  // (releaseCarried), which already sweeps, bounces, rolls and tumbles it.
  // Integrate under gravity, sweep each step, stop on hit.
  if (thrownIndex >= 0) {
    RuntimeObject& o = runtimeObjects[thrownIndex];
    if (!o.active || !o.visible) {
      thrownIndex = -1;
    } else {
      const float r = objectHalfExtent(o);
      thrownVel[1] -= GRAVITY * g_frameDt * g_frameDt;
      // Terminal fall (30 u/s real time, matching the rigid-body sim): a
      // throw that enters a portal infinite-fall loop keeps flying on this
      // path and would otherwise accelerate without bound.
      const float termFall = 30.0F * g_frameDt;
      if (thrownVel[1] < -termFall) thrownVel[1] = -termFall;
      const float stepLen =
          sqrtf(thrownVel[0] * thrownVel[0] + thrownVel[1] * thrownVel[1] +
                thrownVel[2] * thrownVel[2]);
      bool stop = stepLen < 0.0005F;
      bool hopped = false;
      const float prevT[3] = {o.data.position[0], o.data.position[1],
                              o.data.position[2]};
      if (!stop) {
        const float ix = 1.0F / stepLen;
        // While this frame's intended segment pierces a linked opening,
        // obstacles fully behind that portal's plane stop blocking the
        // sweep - without this the mounting wall stops the center ~r
        // short of the crossing plane and the throw can never cross.
        // Pad the aim segment by the object's extent: the sweep stops the
        // CENTER ~r short of a wall sitting at the plane, so an unpadded
        // center segment never reaches it and the doorway never opens
        // (owner repro: every throw bounced off the mounting wall).
        {
          const float pad = 1.0F + (r + 0.1F) / stepLen;
          const float want[3] = {prevT[0] + thrownVel[0] * pad,
                                 prevT[1] + thrownVel[1] * pad,
                                 prevT[2] + thrownVel[2] * pad};
          armSweepPass(prevT, want);
        }
        const float d = sweepSphere(
            o.data.position[0], o.data.position[1], o.data.position[2],
            thrownVel[0] * ix, thrownVel[1] * ix, thrownVel[2] * ix, stepLen,
            r, thrownIndex);
        sweepPassOn = false;
        o.data.position[0] += thrownVel[0] * ix * d;
        o.data.position[1] += thrownVel[1] * ix * d;
        o.data.position[2] += thrownVel[2] * ix * d;
        stop = d < stepLen;  // hit something on the way
        // Crossed a linked opening: hop through, position and the full
        // velocity vector mapped by the pair isometry; keep flying.
        if (PORTAL_COUNT > 0 &&
            (thrownIndex >= (int)portalHopCool.size() ||
             portalHopCool[thrownIndex] == 0) &&
            portalCarryCrossing(prevT, o.data.position, thrownVel)) {
          stop = false;
          hopped = true;
          if (thrownIndex < (int)portalHopCool.size())
            portalHopCool[thrownIndex] = 6;
          if (thrownIndex < (int)portalLastCrossed.size())
            portalLastCrossed[thrownIndex] = portalLastHop;
        }
      }
      // Ground rest matches updateObjectPhysics, so the handoff is
      // seamless. Skipped on the hop frame (the mapped arrival is legal by
      // continuity) and inside a swallowing floor portal's zone - the
      // terrain over the portal must not catch the throw before its center
      // reaches the plane (the walkers' portalSwallowsPlayer rule).
      if (!hopped) {
        bool swallow = false;
        for (int pi = 0; PORTAL_COUNT > 0 && pi < PORTAL_COUNT; ++pi) {
          const PortalData& p = PORTALS[pi];
          if (p.scene != currentScene || p.object < 0 || p.target < 0)
            continue;
          // player-released flight: any linked floor portal swallows it
          if (p.object >= (int)runtimeObjects.size() ||
              p.target >= (int)runtimeObjects.size())
            continue;
          RuntimeObject& m = runtimeObjects[p.object];
          if (!m.active || !m.visible || !runtimeObjects[p.target].active)
            continue;
          if (portalSwallowSwept(m, 0.5F * m.data.scale[0] + 0.25F,
                                 0.5F * m.data.scale[1] + 0.25F,
                                 Vec4(prevT[0], prevT[1], prevT[2], 1.0F),
                                 Vec4(o.data.position[0], o.data.position[1],
                                      o.data.position[2], 1.0F))) {
            swallow = true;
            break;
          }
        }
        const float floorY =
            terrainHeightAt(o.data.position[0], o.data.position[2]) +
            0.5F * o.data.scale[1];
        if (!swallow && o.data.position[1] <= floorY) {
          o.data.position[1] = floorY;
          stop = true;
        }
      }
      o.dirty = true;
      if (stop) {
        o.velocityX = o.velocityY = o.velocityZ = 0.0F;
        thrownIndex = -1;
      }
    }
  }

  if (carryIndex < 0) {
    carryPortalPi = -1;
    return;
  }
  RuntimeObject& o = runtimeObjects[carryIndex];
  // Despawned or hidden mid-carry (flow graph): the hands just open, and the
  // body wakes so it resumes falling if it is shown again mid-air.
  if (!o.active || !o.visible) {
    TYRA_LOG("Pick: lost ", carryIndex, " mid-carry - despawned or hidden");
    inputreplay::note(inputreplay::EV_CARRY_LOST, carryIndex, -1);
    releaseCarried(o, 0.0F, 0.0F, 0.0F);
    carryIndex = -1;
    carryPortalPi = -1;
    return;
  }

  Vec4 dir = cameraLookAt - cameraPosition;
  const float dirLen = sqrtf(dir.x * dir.x + dir.y * dir.y + dir.z * dir.z);
  if (dirLen < 0.0001F) return;
  dir.x /= dirLen, dir.y /= dirLen, dir.z /= dirLen;

  // Carry origin: the eye in first person; the avatar's head (the camera
  // pivot) in third person - "in front of the face" means the avatar's face,
  // not a camera floating meters behind it.
  float ox = cameraPosition.x, oy = cameraPosition.y, oz = cameraPosition.z;
  if (PLAYER_MODE == 2) {
    ox = cameraLookAt.x, oy = cameraLookAt.y, oz = cameraLookAt.z;
  }

  const float r = objectHalfExtent(o);
  // Same policy as the third-person camera boom (springArm): the sweep is
  // the law - a blocked reach pulls the object IN, even past its comfort
  // distance, and NEVER pushes it back out into geometry (the old
  // "never inside the carrier" clamp did exactly that: face against a wall,
  // the object got parked inside the wall). Snap in on a hit, ease back out
  // when the wall clears, so leaving it doesn't pop. PICK_MIN_DIST keeps the
  // object's near face off the near clip plane; the walkers' carry whisker
  // (a springArm-style pre-block) keeps the player from squeezing that far
  // in the first place.
  // Carrying into a portal opening: obstacles fully behind that portal's
  // plane stop blocking the carry sweep - without this the mounting wall
  // pinned the object at the face and the whisker below shoved the walker
  // back, so a wall portal could only be crossed BACKWARDS (owner report).
  // The probe starts BEHIND the eye (backed up along -dir): armSweepPass
  // only arms when its segment starts in FRONT of the plane, and at the
  // portal centre the eye sits right ON the plane - without the back-up the
  // doorway fails exactly there, the sweep catches the mounting wall and
  // yanks the object onto it (owner: cube stops on the wall dead centre).
  {
    const float reach = PICK_CARRY_DIST + r * 2.0F + 0.1F;
    const float bk = 1.2F;
    const float a0[3] = {ox - dir.x * bk, oy - dir.y * bk, oz - dir.z * bk};
    const float b0[3] = {ox + dir.x * reach, oy + dir.y * reach,
                         oz + dir.z * reach};
    armSweepPass(a0, b0);
  }
  float want = sweepSphere(ox, oy, oz, dir.x, dir.y, dir.z, PICK_CARRY_DIST + r,
                           r, carryIndex);
  sweepPassOn = false;
  // Portal-aware carry: the nearest portal opening the carry ray pierces
  // within reach. If that portal DRAWS the object in its through-view
  // (viewAll or the view list), the object flies on THROUGH it - mapped to
  // the far side, in front of the target, where the through-view renders it
  // as if it went through (and it is skipped in the near main pass so it
  // does not also appear as a distant double). This is what lets a carried
  // object cross smoothly instead of stopping dead at the surface (owner:
  // it pinned like a wall). A portal that would NOT render the object
  // (teleport-only) can't show it on the far side, so there the object is
  // clamped to the plane (half-in slice) as the best available.
  int bendPi = -1;
  float bendT = want;
  bool bendShows = false;
  for (int pi = 0; PORTAL_COUNT > 0 && pi < PORTAL_COUNT; ++pi) {
    const PortalData& p = PORTALS[pi];
    if (p.scene != currentScene || p.object < 0 || p.target < 0) continue;
    if (p.object >= (int)runtimeObjects.size() ||
        p.target >= (int)runtimeObjects.size())
      continue;
    RuntimeObject& pm = runtimeObjects[p.object];
    if (!pm.active || !pm.visible || !runtimeObjects[p.target].active) continue;
    const V3 pax = rotated({1.0F, 0.0F, 0.0F}, pm.data.rotation);
    const V3 pay = rotated({0.0F, 1.0F, 0.0F}, pm.data.rotation);
    const V3 paz = rotated({0.0F, 0.0F, 1.0F}, pm.data.rotation);
    const float denom = dir.x * paz.x + dir.y * paz.y + dir.z * paz.z;
    if (denom >= -1e-4F) continue;  // ray must head into the front (+Z) face
    const float sd = (pm.data.position[0] - ox) * paz.x +
                     (pm.data.position[1] - oy) * paz.y +
                     (pm.data.position[2] - oz) * paz.z;
    const float t = sd / denom;  // ray param at the plane
    // Allow the plane to sit a little BEHIND the eye (t slightly negative):
    // at the portal centre the eye is right on it, and dropping the crossing
    // there would un-bend the object for a frame and snap it to the near
    // pass behind the surface (owner: cube stops at the centre).
    if (t >= bendT || t < -(r + 0.6F)) continue;
    const float cxp = ox + dir.x * t - pm.data.position[0];
    const float cyp = oy + dir.y * t - pm.data.position[1];
    const float czp = oz + dir.z * t - pm.data.position[2];
    const float lxp = cxp * pax.x + cyp * pax.y + czp * pax.z;
    const float lyp = cxp * pay.x + cyp * pay.y + czp * pay.z;
    const float phx = 0.5F * pm.data.scale[0] + 0.25F;
    const float phy = 0.5F * pm.data.scale[1] + 0.25F;
    if (lxp > -phx && lxp < phx && lyp > -phy && lyp < phy) {
      bendPi = pi;
      bendT = t;
      bendShows = portalShowsObject(pi, carryIndex);
    }
  }
  // Aiming through a portal that will render the object on the far side:
  // Aiming through a portal that will render the object on the far side:
  // let the reach run FULL, overriding whatever the sweep returned. The
  // object is NOT pinned or bent - it rides straight ahead, straddling the
  // surface, and the two-sided render (below + the portal's through-view)
  // draws each half. The mounting wall must not clip `want` short (a wall
  // flush with the plane still trips the sweep, and the whole point is that
  // it opens like a doorway). A portal that will NOT render the object
  // (teleport-only) can't show the far half, so there the object clamps to
  // the surface (half-in slice) as the best available.
  if (bendPi >= 0 && bendShows)
    want = PICK_CARRY_DIST + r;
  else if (bendPi >= 0 && !bendShows && bendT > 0.0F && bendT < want)
    want = bendT;
  const float minD = PICK_MIN_DIST + r;
  if (want < minD) want = minD;
  if (want < carryDist) {
    carryDist = want;  // blocked: snap in, never clip into the wall
  } else {
    float k = 0.2F * g_frameScale;
    if (k > 1.0F) k = 1.0F;
    carryDist += (want - carryDist) * k;
  }
  const float d = carryDist;
  // Real position rides straight ahead - the object straddles the surface
  // naturally as the player approaches. carryPortalPi tells renderScene which
  // portal's through-view should draw the far half (mapped to the exit).
  carryPortalPi = (bendPi >= 0 && bendShows) ? bendPi : -1;
  o.data.position[0] = ox + dir.x * d;
  o.data.position[1] = oy + dir.y * d;
  o.data.position[2] = oz + dir.z * d;
  // In the hands the body has no momentum of its own: zero every component
  // (not just Y - the rigid-body sim reads all three) so a release starts
  // from rest instead of resuming whatever it was doing before the grab.
  o.velocityX = o.velocityY = o.velocityZ = 0.0F;
  o.spin[0] = o.spin[1] = o.spin[2] = 0.0F;
  o.dirty = true;

  if (carryGrabbed) {
    carryGrabbed = false;  // the press that grabbed it is not a drop
  } else if (inputClicked(engine->pad, IA_ROLE_USE)) {
    TYRA_LOG("Pick: dropped ", carryIndex, " at ", o.data.position[0], " ",
             o.data.position[1], " ", o.data.position[2], ", eye ",
             cameraPosition.x, " ", cameraPosition.y, " ", cameraPosition.z);
    inputreplay::note(inputreplay::EV_DROP, carryIndex, -1);
    releaseCarried(runtimeObjects[carryIndex], 0.0F, 0.0F, 0.0F);
    carryIndex = -1;
    carryPortalPi = -1;
  } else if (o.data.pickThrow && inputClicked(engine->pad, IA_ROLE_THROW)) {
    const int idx = carryIndex;
    carryIndex = -1;
    carryPortalPi = -1;
    const float vx = dir.x * PICK_THROW_SPEED * g_frameDt;
    const float vy = dir.y * PICK_THROW_SPEED * g_frameDt;
    const float vz = dir.z * PICK_THROW_SPEED * g_frameDt;
    TYRA_LOG("Pick: threw ", idx, " at ", o.data.position[0], " ",
             o.data.position[1], " ", o.data.position[2], ", v ", vx, " ", vy,
             " ", vz);
    inputreplay::note(inputreplay::EV_THROW, idx, -1);
    if (!releaseCarried(runtimeObjects[idx], vx, vy, vz)) {
      // No rigid body to hand off to: fly the hand-rolled arc instead.
      thrownIndex = idx;
      thrownVel[0] = vx;
      thrownVel[1] = vy;
      thrownVel[2] = vz;
    }
  }
}



// Hands a released object back to whatever moves it. A rigid body (Physics
// on) simply takes the velocity and WAKES: the sim sleeps settled bodies
// (physAsleep, per-object physSleep countdown) and skips them entirely, and an object
// picked up off the ground is asleep by definition - without this it would
// hang in mid-air where it was dropped, and a throw would ignore bounce,
// friction and tumble. Returns false for a non-physics object, which has no
// simulation to hand off to (it stays put on a drop; a throw flies the
// hand-rolled arc in updateCarriedObject).
bool TerrainGame::releaseCarried(RuntimeObject& o, float vx, float vy,
                                 float vz) {
  o.dirty = true;
  if (!o.data.physics) return false;
  o.velocityX = vx;
  o.velocityY = vy;
  o.velocityZ = vz;
  o.restFrames = 0;  // wake - see the RuntimeObject sleep contract
  // Player-released: portal-free (crosses any linked portal, like the
  // player) until it settles - updatePortals clears the latch on sleep.
  thrownFreeIndex = (int)(&o - runtimeObjects.data());
  return true;
}



// --- Memory card save menu ----------------------------------------------
// Dpad picks a slot, Cross saves, Circle loads, Triangle closes. Returns
// true while the menu owns the pad - loop() then skips player movement,
// the use target, scripts and object physics (a straight pause).
bool TerrainGame::updateSaveMenu() {
  if (saveFeedbackFrames > 0) --saveFeedbackFrames;

  // Checkpoint requests (flow graph). Save/Load touch only the single RAM
  // buffer - instant, no card, no overlay. Commit turns into a card op.
  scriptCtx.hasCheckpoint = checkpointValid;
  if (scriptCtx.saveCheckpoint) {
    scriptCtx.saveCheckpoint = false;
    captureState(checkpointData);
    checkpointValid = true;
    scriptCtx.hasCheckpoint = true;
  }
  if (scriptCtx.loadCheckpoint) {
    scriptCtx.loadCheckpoint = false;
    if (checkpointValid) applyState(checkpointData);
  }
  if (scriptCtx.commitCheckpoint != -1) {
    const int slot = resolveCommitSlot(scriptCtx.commitCheckpoint);
    scriptCtx.commitCheckpoint = -1;
    if (checkpointValid && slot >= 0 && slot < SAVE_SLOTS) {
      if (SAVE_ASYNC) {
        // The whole point of an async commit: no overlay, no pause. The
        // checkpoint buffer is already a finished payload, so this writes it
        // verbatim (slotSource is not consulted - a commit is a commit).
        if (!saveWriteBusy() && cardOp < 0) {
          if (saveWriteBegin(slot, checkpointData)) {
            asyncSaveSlot = slot;
            spinnerHold = everyFrames(0.6F);
          }
        }
      } else if (cardOp < 0) {
        beginCardOp(2, slot);
      }
    }
  }

  // An async write runs ALONGSIDE the game: step it once per frame and fall
  // through, so it owns neither the pad nor the screen - only the spinner.
  if (SAVE_ASYNC && spinnerHold > 0) --spinnerHold;
  if (SAVE_ASYNC && saveWriteBusy()) {
    bool ok = false;
    if (saveWritePoll(&ok)) {
      if (ok && asyncSaveSlot >= 0 && asyncSaveSlot < SAVE_SLOTS)
        slotUsed[asyncSaveSlot] = true;
      asyncSaveSlot = -1;
      saveFeedback = ok ? 1 : 3;
      saveFeedbackFrames = everyFrames(1.8F);
    }
  }

  // A card op owns the pad. The blocking libmc transfer only runs once the
  // "do not remove the memory card" overlay has been on screen for a few
  // frames; afterwards the warning holds up its minimum time.
  if (cardOp >= 0) {
    if (cardOpDelay > 0) {
      --cardOpDelay;
    } else {
      const int op = cardOp;
      cardOp = -1;
      if (op == 0) {
        doSave(cardOpSlot);
      } else if (op == 1) {
        doLoad(cardOpSlot);
      } else {  // commit the RAM checkpoint to a slot
        const bool ok = saveWrite(cardOpSlot, checkpointData);
        if (ok) slotUsed[cardOpSlot] = true;
        saveFeedback = ok ? 1 : 3;
        saveFeedbackFrames = everyFrames(1.8F);
      }
    }
    return true;
  }
  if (cardBusyFrames > 0) {
    --cardBusyFrames;
    return true;
  }

  if (scriptCtx.openSaveMenu) {
    scriptCtx.openSaveMenu = false;
    if (!saveMenuOpen) {
      saveMenuOpen = true;
      saveMenuSlot = 0;
      // The pad reports garbage transitions while it (re)configures -
      // swallow clicks briefly so opening the menu can't instantly save.
      saveMenuGrace = 15;
      useTargetIndex = -1;  // drop the USE prompt while the menu is up
      refreshSlotStates();
      return true;
    }
  }
  if (!saveMenuOpen) return false;
  if (saveMenuGrace > 0) {
    --saveMenuGrace;
    return true;
  }

  // Menu navigation through the Input Map's menu-* / confirm / back / alt
  // roles (Tools > Input Map), so a project that moves them - or a player who
  // rebinds one - navigates the save menu the same way as everything else.
  // Slots wrap as one list; the PAGE simply follows the cursor, so walking
  // off the bottom row turns the page instead of stopping.
  if (inputClicked(engine->pad, IA_ROLE_MENU_UP))
    saveMenuSlot = (saveMenuSlot + SAVE_SLOTS - 1) % SAVE_SLOTS;
  if (inputClicked(engine->pad, IA_ROLE_MENU_DOWN))
    saveMenuSlot = (saveMenuSlot + 1) % SAVE_SLOTS;
  // Left/right jump a whole page - with dozens of slots, holding down is not
  // a way to reach slot 90.
  if (SAVE_PAGES > 1) {
    if (inputClicked(engine->pad, IA_ROLE_MENU_LEFT))
      saveMenuSlot = (saveMenuSlot + SAVE_SLOTS - SAVE_SLOTS_PER_PAGE) % SAVE_SLOTS;
    if (inputClicked(engine->pad, IA_ROLE_MENU_RIGHT))
      saveMenuSlot = (saveMenuSlot + SAVE_SLOTS_PER_PAGE) % SAVE_SLOTS;
  }
  saveMenuPage = saveMenuSlot / SAVE_SLOTS_PER_PAGE;
  if (inputClicked(engine->pad, IA_ROLE_BACK)) {
    saveMenuOpen = false;
    return true;
  }
  // Buttons come from the remappable input map (main), the work goes through
  // beginCardOp so the "checking memory card" screen is up while the card is
  // touched (the Save Editor batch) - doSave/doLoad are what it calls once the
  // warning has actually been drawn.
  if (inputClicked(engine->pad, IA_ROLE_CONFIRM)) {
    if (SAVE_ASYNC) {
      // Close the menu and hand the write to the background: the spinner is
      // the only thing left on screen and the player is already moving again.
      startAsyncSave(saveMenuSlot);
      saveMenuOpen = false;
    } else {
      beginCardOp(0, saveMenuSlot);
    }
  }
  // Loading stays blocking in both modes - the world is being replaced, so
  // there is nothing to keep playing while it happens.
  if (inputClicked(engine->pad, IA_ROLE_ALT) && slotUsed[saveMenuSlot])
    beginCardOp(1, saveMenuSlot);
  return true;
}



void TerrainGame::beginCardOp(int op, int slot) {
  cardOp = op;
  cardOpSlot = slot;
  cardOpDelay = 3;  // present the warning before the blocking transfer
  cardBusyFrames = everyFrames(1.5F);
}



void TerrainGame::refreshSlotStates() {
  for (int i = 0; i < SAVE_SLOTS; ++i) slotUsed[i] = saveSlotUsed(i);
}



int TerrainGame::nextSaveSlot() {
  for (int i = 0; i < SAVE_SLOTS; ++i) {
    if (i == SAVE_AUTOSAVE_SLOT) continue;  // the game's own slot, not a spare
    if (!slotUsed[i]) return i;
  }
  // All full: cycle, so a run keeps saving instead of quietly stopping.
  for (int n = 0; n < SAVE_SLOTS; ++n) {
    const int i = (nextSaveRotate + n) % SAVE_SLOTS;
    if (i == SAVE_AUTOSAVE_SLOT) continue;
    nextSaveRotate = (i + 1) % SAVE_SLOTS;
    return i;
  }
  return -1;  // every slot is the autosave slot (SAVE_SLOTS == 1)
}



int TerrainGame::resolveCommitSlot(int request) {
  if (request == SAVE_COMMIT_AUTOSAVE) return SAVE_AUTOSAVE_SLOT;  // -1 if none
  if (request == SAVE_COMMIT_NEXT) return nextSaveSlot();
  return request;
}



void TerrainGame::captureState(SaveGameData& d) {
  d = SaveGameData();
  d.magic = SAVE_MAGIC;
  d.version = SAVE_VERSION;
  d.scene = currentScene;
  // Feet position + facing: the Player entity when the scene has one,
  // otherwise derived from the camera (the FPP template player; the orbit
  // camera simply ignores the restore).
  if (PLAYER_INDEX >= 0) {
    d.playerPos[0] = players[0].x;
    d.playerPos[1] = players[0].y;
    d.playerPos[2] = players[0].z;
    d.playerYaw = players[0].yaw * 180.0F / PI;
  } else {
    d.playerPos[0] = cameraPosition.x;
    d.playerPos[1] = cameraPosition.y - EYE_HEIGHT;
    d.playerPos[2] = cameraPosition.z;
    const Vec4 dir = cameraLookAt - cameraPosition;
    d.playerYaw = atan2f(dir.x, dir.z) * 180.0F / PI;
  }
  d.valueCount = SAVE_VALUE_COUNT;
  for (int i = 0; i < SAVE_VALUE_COUNT; ++i) d.values[i] = saveValues[i];
  d.textCount = SAVE_TEXT_COUNT;
  for (int i = 0; i < SAVE_TEXT_COUNT; ++i)
    snprintf(d.texts[i], SAVE_TEXT_LEN, "%s", &saveTexts[i * SAVE_TEXT_LEN]);
  // World Facts: whatever the catalog declared as checkpoint- or save-lived,
  // each row carrying its fact's own id (docs/world-facts.md).
  d.factCount = factSaveCapture(d.facts, FACT_SAVE_MAX);
  d.objectCount = 0;
  for (int i = 0;
       i < SCENE_OBJECT_COUNT && d.objectCount < SAVE_OBJECT_MAX; ++i) {
    if (!SCENE_OBJECTS[i].saveState) continue;  // spawn clones never persist
    SaveObjectState& st = d.objects[d.objectCount++];
    st.index = i;
    for (int a = 0; a < 3; ++a) st.position[a] = runtimeObjects[i].data.position[a];
    for (int a = 0; a < 3; ++a) st.color[a] = runtimeObjects[i].data.color[a];
    st.visible = runtimeObjects[i].visible ? 1 : 0;
  }
}



// What goes in the slot. With SAVE_MENU_CHECKPOINT the menu writes the last
// checkpoint instead of the here-and-now - the "you resume from the shrine"
// model. It falls back to a live snapshot when no checkpoint has been taken,
// so a player who reaches the menu first can still save.
const SaveGameData& TerrainGame::slotSource(SaveGameData& scratch) {
  if (SAVE_MENU_CHECKPOINT && checkpointValid) return checkpointData;
  captureState(scratch);
  return scratch;
}



void TerrainGame::doSave(int slot) {
  static SaveGameData d;  // the payload can be a few KB - keep it off the stack
  const bool ok = saveWrite(slot, slotSource(d));
  if (ok) slotUsed[slot] = true;
  saveFeedback = ok ? 1 : 3;
  saveFeedbackFrames = everyFrames(1.8F);  // ~1.8 s
}



// The async twin of doSave: hand the bytes to saveWriteBegin and return. The
// poll in updateSaveMenu finishes it and raises the feedback.
void TerrainGame::startAsyncSave(int slot) {
  static SaveGameData d;
  if (saveWriteBusy() || cardOp >= 0) return;  // never two transfers at once
  if (saveWriteBegin(slot, slotSource(d))) {
    asyncSaveSlot = slot;
    spinnerHold = everyFrames(0.6F);
  }
}



void TerrainGame::doLoad(int slot) {
  static SaveGameData d;
  if (!saveRead(slot, d)) {
    saveFeedback = 3;
    saveFeedbackFrames = everyFrames(1.8F);
    return;
  }
  applyState(d);
  saveMenuOpen = false;
  saveFeedback = 2;
  saveFeedbackFrames = 90;
}



// Restores a payload captured by captureState - a card slot's or the RAM
// checkpoint's. Mutates d only to NUL-terminate texts (corrupted cards).
void TerrainGame::applyState(SaveGameData& d) {
  for (int i = 0; i < d.valueCount && i < SAVE_VALUE_COUNT; ++i)
    saveValues[i] = d.values[i];
  // Facts are matched to slots BY ID, so a payload written before a fact was
  // renamed, moved or removed still restores everything it still shares with
  // this build - and silently drops the rest instead of writing a value into
  // whatever now sits at that position.
  if (d.factCount > 0 && d.factCount <= FACT_SAVE_MAX)
    factSaveRestore(d.facts, d.factCount);
  for (int i = 0; i < d.textCount && i < SAVE_TEXT_COUNT; ++i) {
    d.texts[i][SAVE_TEXT_LEN - 1] = '\0';  // corrupted cards happen
    snprintf(&saveTexts[i * SAVE_TEXT_LEN], SAVE_TEXT_LEN, "%s", d.texts[i]);
  }
  pendingObjState.assign(d.objects, d.objects + d.objectCount);
  pendingObjScene = d.scene;
  // Restore the player through the teleport request - the flag survives a
  // scene switch and covers both player kinds.
  scriptCtx.teleport = true;
  scriptCtx.teleportPos = Vec4(d.playerPos[0], d.playerPos[1], d.playerPos[2]);
  scriptCtx.teleportYaw = d.playerYaw;
  if (d.scene != currentScene)
    scriptCtx.requestScene = d.scene;  // object state applies after the load
  else
    applySavedObjects();
}



void TerrainGame::applySavedObjects() {
  for (const SaveObjectState& st : pendingObjState) {
    if (st.index < 0 || st.index >= (int)runtimeObjects.size()) continue;
    RuntimeObject& o = runtimeObjects[st.index];
    for (int a = 0; a < 3; ++a) o.data.position[a] = st.position[a];
    for (int a = 0; a < 3; ++a) o.data.color[a] = st.color[a];
    o.visible = st.visible != 0;
    o.velocityX = o.velocityY = o.velocityZ = 0.0F;
    o.spin[0] = o.spin[1] = o.spin[2] = 0.0F;
    o.restFrames = 0;  // wake: the restored position may be mid-air
    o.dirty = true;
  }
  pendingObjState.clear();
  pendingObjScene = -1;
}



void TerrainGame::renderSaveMenu() {
  if (saveMenuOpen) {
    engine->renderer.renderer2D.render(menuDimSprite);
    engine->renderer.renderer2D.render(saveMenuSprite);
    // Row geometry comes from the baked panel (MenuData), and the labels are
    // drawn HERE rather than baked - which is the whole reason a project can
    // have more slots than rows.
    const float baseY = saveMenuSprite.position.y;
    const float baseX = saveMenuSprite.position.x;
    const int row0 = SAVE_MENU_INDEX >= 0 ? MENUS[SAVE_MENU_INDEX].row0Y : 40;
    const int rowH = SAVE_MENU_INDEX >= 0 ? MENUS[SAVE_MENU_INDEX].rowH : 24;
    const int panelW = SAVE_MENU_INDEX >= 0 ? MENUS[SAVE_MENU_INDEX].panelW : 256;
    const int first = saveMenuPage * SAVE_SLOTS_PER_PAGE;
    saveCursorSprite.position.y =
        baseY + (float)row0 + 1.0F + (float)((saveMenuSlot - first) * rowH);
    engine->renderer.renderer2D.render(saveCursorSprite);
    for (int r = 0; r < SAVE_SLOTS_PER_PAGE; ++r) {
      const int slot = first + r;
      if (slot >= SAVE_SLOTS) break;
      if (slotUsed[slot]) {
        saveUsedSprite.position.y = baseY + (float)row0 + 2.0F + (float)(r * rowH);
        engine->renderer.renderer2D.render(saveUsedSprite);
      }
      if (SAVE_MENU_INDEX >= 0) {
        char label[24];
        snprintf(label, sizeof(label), "SLOT %d", slot + 1);
        const MenuData& sm = MENUS[SAVE_MENU_INDEX];
        const float sz = (float)(rowH > 12 ? rowH - 9 : 8);
        // drawFontText CENTRES on the x it is given, so left-aligning at the
        // baked labels' own x (56) means offsetting by half the width -
        // otherwise the row starts under the cursor sprite.
        const float lw = fontTextWidth(sm.font, label, sz);
        drawFontText(engine, sm.font, label, baseX + 56.0F + lw * 0.5F,
                     baseY + (float)row0 + (float)(r * rowH) +
                         (float)rowH * 0.5F,
                     sz);
      }
    }
    // Page indicator, only when there is more than one page to be on.
    if (SAVE_PAGES > 1 && SAVE_MENU_INDEX >= 0) {
      char pg[24];
      snprintf(pg, sizeof(pg), "%d/%d", saveMenuPage + 1, SAVE_PAGES);
      const MenuData& sm = MENUS[SAVE_MENU_INDEX];
      drawFontText(engine, sm.font, pg, baseX + (float)panelW - 30.0F,
                   baseY + (float)row0 - 16.0F, 11.0F);
    }
  }
  // The "do not remove the memory card" warning covers everything while a
  // card op is pending or holding; feedback sprites wait until it clears.
  if (cardOp >= 0 || cardBusyFrames > 0) {
    engine->renderer.renderer2D.render(menuDimSprite);
    engine->renderer.renderer2D.render(saveBusySprite);
    return;
  }
  // The async write's own indicator: no dim, no overlay, just the spinner in
  // its corner, one cell of the strip per few frames.
  if (SAVE_ASYNC && SAVE_SPINNER && (saveWriteBusy() || spinnerHold > 0)) {
    ++spinnerFrame;
    const int cell = (spinnerFrame / SAVE_SPINNER_HOLD) % SAVE_SPINNER_FRAMES;
    saveSpinnerSprite.offset =
        Vec2((float)(cell * SAVE_SPINNER_CELL_W), 0.0F);
    engine->renderer.renderer2D.render(saveSpinnerSprite);
  }
  if (saveFeedbackFrames > 0 && saveFeedback >= 1 && saveFeedback <= 3)
    engine->renderer.renderer2D.render(saveFeedbackSprites[saveFeedback - 1]);
}



// --- Game menus (menu_data.gen.hpp) ---------------------------------------
// Panels are baked by the editor; the runtime only moves a cursor and runs
// entry actions. Dpad picks a row, Cross selects, Triangle pops the submenu
// stack (or closes; a title screen's root cannot be dismissed with Back).
// The Start button opens/closes the designated pause menu (PAUSE_MENU).
// Returns true while an open menu PAUSES gameplay - menus with the pause
// flag off float over the running game (pad presses reach both).
bool TerrainGame::updateGameMenu() {
  scriptCtx.menuEvent = -1;
  // A flow event queued from outside a menu row (a finished credits roll)
  // becomes this frame's menu event, so the On Menu Event triggers see it
  // exactly as if a row had fired it. Promoted HERE because this is the one
  // place that clears menuEvent - a queuer running earlier in the loop would
  // otherwise have its event wiped before any script could read it.
  if (scriptCtx.pendingEvent >= 0) {
    scriptCtx.menuEvent = scriptCtx.pendingEvent;
    scriptCtx.pendingEvent = -1;
  }
  auto pausing = [&] {
    return gameMenuIndex >= 0 && MENUS[gameMenuIndex].pause != 0;
  };
  // Opening a menu from scratch: one sequence, three callers (a queued
  // openMenu, the pause toggle, the cutscene skip confirmation below). The
  // grace counter is pad-garbage protection - see updateSaveMenu.
  auto enterMenu = [&](int target) {
    gameMenuIndex = target;
    gameMenuCursor = 0;
    gameMenuScroll = 0;
    gameMenuOpenT = 0.0F;
    gameMenuClock = 0.0F;
    gameMenuScrollShown = 0.0F;
    gameMenuCursorRow = -1;
    gameMenuStackDepth = 0;
    gameMenuGrace = 15;
    menuRebindRow = -1;
    useTargetIndex = -1;
  };

  if (scriptCtx.openMenu >= 0) {
    const int target = scriptCtx.openMenu;
    scriptCtx.openMenu = -1;
    if (target < MENU_COUNT && !saveMenuOpen && gameMenuIndex < 0) {
      enterMenu(target);
      return pausing();
    }
  }

  // A skippable cutscene OWNS the "menu" action for its duration
  // (docs/cutscenes.md). This has to come before the pause toggle below, and
  // that ordering is the whole fix: a project with a pause menu could never
  // skip a cutscene, because the press opened the menu, the open menu paused
  // the scripts, and the director - which used to test the raw Start button
  // itself - never ran to see it. One press does one thing.
  if (gameMenuIndex < 0 && !saveMenuOpen && sequences::skippable() &&
      inputClicked(engine->pad, IA_ROLE_MENU)) {
    // Ask first, when the project designated a confirmation screen. With no
    // such menu the mode falls back to skipping on the spot: swallowing the
    // press and doing nothing would read as a broken button.
    if (sequences::skipMode() == 1 && SKIP_MENU >= 0 && SKIP_MENU < MENU_COUNT) {
      enterMenu(SKIP_MENU);
      return pausing();
    }
    sequences::stop();
    return false;
  }

  // The "menu" action toggles the pause menu: opens it during gameplay, closes
  // it again while its root is showing (submenus first go back with "back").
  if (PAUSE_MENU >= 0 && !saveMenuOpen &&
      inputClicked(engine->pad, IA_ROLE_MENU)) {
    if (gameMenuIndex < 0) {
      enterMenu(PAUSE_MENU);
      return pausing();
    }
    if (gameMenuIndex == PAUSE_MENU && gameMenuStackDepth == 0 &&
        gameMenuGrace == 0) {
      gameMenuIndex = -1;
      return false;
    }
  }

  // A menu that is closing keeps drawing for the length of its close transition
  // and takes no input. Only the plain dismissals animate: a scene switch or a
  // hand-off to the save menu clears immediately, because a panel lingering over
  // a loading scene is worse than no transition at all.
  if (gameMenuClosing >= 0) {
    gameMenuCloseT += g_frameDt;
    if (gameMenuCloseT >= MENUS[gameMenuClosing].closeSec) gameMenuClosing = -1;
  }

  if (gameMenuIndex < 0) return false;
  if (saveMenuOpen) return pausing();  // save menu on top - hold, no pad
  if (gameMenuGrace > 0) {
    --gameMenuGrace;
    return pausing();
  }

  const MenuData& m = MENUS[gameMenuIndex];

  // A rebind row in capture mode owns the pad completely: the next button the
  // player presses becomes the binding. Nothing else may read input this frame,
  // or the very press being captured would also select a row.
  //
  // Cancel is the RAW Start button, deliberately not the "back" action: back is
  // Triangle by default, and checking it first made Triangle the one button you
  // could never bind (it cancelled instead of being captured). Start is the
  // classic cancel, is not offered as a rebindable action, and using the raw
  // button means this still works when a project moves its `menu` action.
  if (menuRebindRow >= 0) {
    if (menuRebindRow >= m.entryCount) {
      menuRebindRow = -1;
      return pausing();
    }
    const MenuEntryData& re = m.entries[menuRebindRow];
    if (engine->pad.getClicked().Start) {
      menuRebindRow = -1;
      return pausing();
    }
    const int code = inputCapture(engine);
    if (code > 0 && re.inputAction >= 0 && re.param >= 0 &&
        re.param < SAVE_VALUE_COUNT) {
      // The save value is the persisted override; applyInputBindings pushes it
      // into the live bindings (this frame, and again after a load).
      saveValues[re.param] = (float)code;
      menuRebindRow = -1;
    }
    return pausing();
  }

  // Headers, spacers and rows their `enabledWhen` value switched off are
  // skipped - including on the frame the menu opened, so a menu whose first row
  // is a section header still lands on something usable.
  if (!menuRowEnabled(gameMenuIndex, gameMenuCursor))
    menuMoveCursor(gameMenuIndex, 1);
  if (inputClicked(engine->pad, IA_ROLE_MENU_UP)) menuMoveCursor(gameMenuIndex, -1);
  if (inputClicked(engine->pad, IA_ROLE_MENU_DOWN)) menuMoveCursor(gameMenuIndex, 1);
  menuFollowCursor(gameMenuIndex);

  // Toggle/Choice rows: the state is the bound save value (the option
  // index). Cross and dpad right cycle forward, dpad left backward.
  auto cycleValue = [&](const MenuEntryData& e, int dir) {
    if (e.param < 0 || e.param >= SAVE_VALUE_COUNT || e.optionCount <= 0)
      return;
    int v = (int)saveValues[e.param];
    if (v < 0) v = 0;
    if (v >= e.optionCount) v = e.optionCount - 1;
    saveValues[e.param] = (float)((v + dir + e.optionCount) % e.optionCount);
    gameMenuValueFlash = m.valueFlashSec;  // 0 when the sheet asks for none
  };
  if (gameMenuCursor >= 0 && gameMenuCursor < m.entryCount) {
    const MenuEntryData& cur = m.entries[gameMenuCursor];
    if (cur.action == 7 || cur.action == 8) {
      if (inputClicked(engine->pad, IA_ROLE_MENU_LEFT)) cycleValue(cur, -1);
      if (inputClicked(engine->pad, IA_ROLE_MENU_RIGHT)) cycleValue(cur, 1);
    }
    // A rebind row also accepts "clear back to the preset binding" sideways,
    // so a player can undo an override without hunting for the same button.
    if (cur.action == 10 && cur.param >= 0 && cur.param < SAVE_VALUE_COUNT &&
        INPUT_ALLOW_REBIND && inputClicked(engine->pad, IA_ROLE_MENU_LEFT))
      saveValues[cur.param] = 0.0F;
  }

  if (inputClicked(engine->pad, IA_ROLE_BACK)) {
    if (gameMenuStackDepth > 0) {
      gameMenuIndex = gameMenuStack[--gameMenuStackDepth];
      gameMenuCursor = 0;
      gameMenuScroll = 0;
      gameMenuOpenT = 0.0F;
      gameMenuClock = 0.0F;
      gameMenuScrollShown = 0.0F;
      gameMenuCursorRow = -1;
      menuRebindRow = -1;
    } else if (!m.titleScreen) {
      if (m.closeSec > 0.0F) {
        gameMenuClosing = gameMenuIndex;
        gameMenuCloseT = 0.0F;
      }
      gameMenuIndex = -1;
    }
    return pausing();
  }

  if (inputClicked(engine->pad, IA_ROLE_CONFIRM) && gameMenuCursor >= 0 &&
      gameMenuCursor < m.entryCount &&
      menuRowEnabled(gameMenuIndex, gameMenuCursor)) {
    const MenuEntryData& e = m.entries[gameMenuCursor];
    switch (e.action) {
      case 0:  // close
        if (m.closeSec > 0.0F) {
          gameMenuClosing = gameMenuIndex;
          gameMenuCloseT = 0.0F;
        }
        gameMenuIndex = -1;
        gameMenuStackDepth = 0;
        break;
      case 1:  // switch scene
        if (e.param >= 0) {
          scriptCtx.requestScene = e.param;
          gameMenuIndex = -1;
          gameMenuStackDepth = 0;
        }
        break;
      case 2:  // open save menu (replaces this menu next frame)
        gameMenuIndex = -1;
        gameMenuStackDepth = 0;
        scriptCtx.openSaveMenu = true;
        break;
      case 3:  // open submenu
        if (e.param >= 0 && e.param < MENU_COUNT &&
            gameMenuStackDepth < (int)(sizeof(gameMenuStack) / sizeof(int))) {
          gameMenuStack[gameMenuStackDepth++] = gameMenuIndex;
          gameMenuIndex = e.param;
          gameMenuCursor = 0;
          gameMenuScroll = 0;
          gameMenuOpenT = 0.0F;
          gameMenuClock = 0.0F;
          gameMenuScrollShown = 0.0F;
          gameMenuCursorRow = -1;
          menuRebindRow = -1;
        }
        break;
      case 4:  // set save value (menu stays open)
        if (e.param >= 0 && e.param < SAVE_VALUE_COUNT)
          saveValues[e.param] = e.amount;
        break;
      case 5:  // add to save value
        if (e.param >= 0 && e.param < SAVE_VALUE_COUNT)
          saveValues[e.param] += e.amount;
        break;
      case 6:  // flow event: scripts run this frame to catch it
        scriptCtx.menuEvent = e.param;
        break;
      case 7:  // toggle - flip/cycle the bound save value (menu stays open)
      case 8:  // choice
        cycleValue(e, 1);
        break;
      case 9:  // apply video mode: commit the display row's staged selection
        // (a scan-mode switch closes the menu - see applyVideoRequests'
        // caller - so the player judges the new picture unobstructed).
        for (int vmi = 0; vmi < MENU_COUNT; ++vmi) {
          for (int vei = 0; vei < MENUS[vmi].entryCount; ++vei) {
            const MenuEntryData& row = MENUS[vmi].entries[vei];
            if (row.bind != 5 || row.param < 0 ||
                row.param >= SAVE_VALUE_COUNT || row.optionCount <= 0)
              continue;
            int idx = (int)saveValues[row.param];
            if (idx < 0) idx = 0;
            if (idx >= row.optionCount) idx = row.optionCount - 1;
            const int mode = displayOptionMode(row, idx);
            if (mode !=
                (int)engine->renderer.core.getSettings().getDisplayMode()) {
              scriptCtx.requestDisplayMode = mode;
              scriptCtx.displayConfirmSec = 8.0F;  // keep-or-revert net
              g_menuDispOpt = idx;
            }
            vmi = MENU_COUNT;  // first display row wins
            break;
          }
        }
        break;
      case 10:  // rebind an input action: arm capture mode (the row's value
        // becomes whatever the player presses next - see the top of this
        // function). A locked project (Input Map > Allow rebind off) shows the
        // binding but never captures.
        if (INPUT_ALLOW_REBIND && e.inputAction >= 0 &&
            e.inputAction < INPUT_ACTION_COUNT &&
            INPUT_REBINDABLE[e.inputAction])
          menuRebindRow = gameMenuCursor;
        break;
      case 11:  // roll the credits: the menu closes first, so the roll owns a
        // clean screen and its own finish action decides what comes back (a
        // title screen typically sends the player straight back to itself).
        if (e.param >= 0) {
          gameMenuIndex = -1;
          gameMenuStackDepth = 0;
          credits::play(e.param);
        }
        break;
      case 13:  // confirm a cutscene skip: end it and close the menu. Anything
        // that dismisses the menu instead (a Close row, "back") declines and
        // the cutscene carries on from where it froze - so "no" needs no row
        // action of its own (docs/cutscenes.md).
        gameMenuIndex = -1;
        gameMenuStackDepth = 0;
        sequences::stop();
        break;
    }
  }
  return pausing();
}



// Rebind rows (MenuEntry::RebindKey) -> the live bindings. Each row's save
// value holds an INPUT_CODES index (0 = the preset's own binding), so the
// override persists on the memory card like every other menu state and is
// re-applied after a load. Idempotent and cheap: inputSetOverride only
// rebuilds when the code actually changed.
void TerrainGame::applyInputBindings() {
  for (int mi = 0; mi < MENU_COUNT; ++mi) {
    const MenuData& m = MENUS[mi];
    for (int e = 0; e < m.entryCount; ++e) {
      const MenuEntryData& en = m.entries[e];
      if (en.action != 10 || en.inputAction < 0 ||
          en.inputAction >= INPUT_ACTION_COUNT)
        continue;
      if (en.param < 0 || en.param >= SAVE_VALUE_COUNT) continue;
      int code = (int)saveValues[en.param];
      if (code < 0 || code >= INPUT_CODE_COUNT) code = 0;
      if (code != g_inputOverride[en.inputAction])
        inputSetOverride(en.inputAction, code);
    }
  }
}



// Ready-made menu "option blocks" (Menu Editor > Insert option block): a
// Toggle/Choice row bound to a built-in engine setting. Every frame we map the
// row's option index (held in its save value) onto the setting, evenly across
// the row's options - so the same row that persists and previews as a normal
// stateful entry also drives the engine, with no flow graph. Volume / deadzone
// / curve are idempotent (re-applied each frame, cheap). Display mode and
// widescreen rebuild VRAM / arm the confirm prompt, so they fire only when the
// option actually changes, routed through the same scriptCtx video requests
// the Set Display Mode / Set Widescreen flow nodes use. When the project has
// an "apply video mode" row (MENU_HAS_APPLY_VIDEO) the display row defers
// instead: cycling it only stages a selection the APPLY row commits (case 9
// in updateGameMenu), so the player can browse the option list without the
// screen switching under them.
void TerrainGame::applyMenuBindings() {
  for (int mi = 0; mi < MENU_COUNT; ++mi) {
    const MenuData& m = MENUS[mi];
    for (int e = 0; e < m.entryCount; ++e) {
      const MenuEntryData& en = m.entries[e];
      if (en.bind == 0) continue;
      const int cnt = en.optionCount > 0 ? en.optionCount : 1;
      int idx = (en.param >= 0 && en.param < SAVE_VALUE_COUNT)
                    ? (int)saveValues[en.param]
                    : 0;
      if (idx < 0) idx = 0;
      if (idx >= cnt) idx = cnt - 1;
      // t: option index normalized to 0..1 (single-option rows read as full).
      const float t = cnt > 1 ? (float)idx / (float)(cnt - 1) : 1.0F;
      switch (en.bind) {
        case 1:  // music volume 0..100
          engine->audio.song.setVolume((u8)(t * 100.0F + 0.5F));
          break;
        case 2:  // master sfx volume 0..100
          scriptCtx.sfxVolume = (int)(t * 100.0F + 0.5F);
          break;
        case 3:  // deadzone, both sticks 0..0.4
          g_deadzoneL = g_deadzoneR = t * 0.4F;
          break;
        case 4: {  // aim response curve (both sticks): drives the shared
          // g_stickCurve*/g_stickExp* runtime (same globals the Set Stick Curve
          // flow node uses). Option 0 Linear, 1 Smooth (S-curve), 2+ Precise
          // (exponential - finer near center). Uses idx, not the even mapping.
          int curve = 0;
          if (idx == 1) curve = 2;       // S-curve
          else if (idx >= 2) curve = 1;  // exponential
          g_stickCurveL = g_stickCurveR = curve;
          g_stickExpL = g_stickExpR = 2.0F;
          break;
        }
        case 5:  // display / scan mode (option -> mode via displayOptionMode)
          if (MENU_HAS_APPLY_VIDEO) {
            // Deferred: the row only stages a selection while a menu is on
            // screen; the "apply video mode" row commits it. With no menu
            // open, snap the row back to the live mode - a browsed-but-
            // unapplied selection (or a reverted confirm) never lies.
            if (gameMenuIndex < 0 && en.param >= 0 &&
                en.param < SAVE_VALUE_COUNT) {
              const int live = displayOptionIndexOf(
                  en,
                  (int)engine->renderer.core.getSettings().getDisplayMode());
              if (live >= 0 && live != idx) saveValues[en.param] = (float)live;
            }
          } else if (idx != g_menuDispOpt) {
            g_menuDispOpt = idx;
            scriptCtx.requestDisplayMode = displayOptionMode(en, idx);
            scriptCtx.displayConfirmSec = 8.0F;  // keep-or-revert safety net
          }
          break;
        case 6:  // widescreen 4:3 / 16:9
          if (idx != g_menuWideOpt) {
            g_menuWideOpt = idx;
            scriptCtx.widescreen = idx;
          }
          break;
        case 7:  // player count (1P / 2P) - edge-triggered, so the pad-2
          // Start join isn't reverted by the bind on the next frame
          // (setPlayerTwoActive writes the row's save value back in sync).
          if (idx != menuPlayerCountPrev) {
            menuPlayerCountPrev = idx;
            setPlayerTwoActive(idx >= 1);
          }
          break;
        case 8:  // input preset (Tools > Input Map): the option index IS the
          // preset index. inputSetPreset is a no-op when it already matches,
          // and re-applies the player's per-action overrides on top.
          inputSetPreset(idx);
          break;
      }
    }
  }
}



// Keep a bound "Player count" menu row's save value (and the bind's edge
// detector) in line with the actual player-2 state, so a pad-2 Start join
// shows up in the menu instead of fighting it.
void TerrainGame::syncPlayerCountMenuValue() {
  const int idx = playerTwoActive ? 1 : 0;
  menuPlayerCountPrev = idx;
  for (int mi = 0; mi < MENU_COUNT; ++mi) {
    const MenuData& m = MENUS[mi];
    for (int e = 0; e < m.entryCount; ++e) {
      const MenuEntryData& en = m.entries[e];
      if (en.bind == 7 && en.param >= 0 && en.param < SAVE_VALUE_COUNT)
        saveValues[en.param] = (float)idx;
    }
  }
}



// True when a row is currently usable: a label/spacer never is, and a row with
// an `enabledWhen` save value is only usable while that value is non-zero.
bool TerrainGame::menuRowEnabled(int menu, int row) const {
  if (menu < 0 || menu >= MENU_COUNT) return false;
  const MenuData& m = MENUS[menu];
  if (row < 0 || row >= m.entryCount) return false;
  const MenuEntryData& e = m.entries[row];
  if (!e.selectable) return false;
  if (e.enableVal >= 0 && e.enableVal < SAVE_VALUE_COUNT &&
      saveValues[e.enableVal] == 0.0F)
    return false;
  return true;
}



// Moves the cursor `dir` rows, skipping headers, spacers and disabled rows, and
// wrapping like the plain cursor always did. A menu with nothing selectable
// leaves the cursor where it is rather than spinning.
void TerrainGame::menuMoveCursor(int menu, int dir) {
  if (menu < 0 || menu >= MENU_COUNT) return;
  const MenuData& m = MENUS[menu];
  if (m.entryCount <= 0) return;
  for (int step = 0; step < m.entryCount; ++step) {
    gameMenuCursor = (gameMenuCursor + dir + m.entryCount) % m.entryCount;
    if (menuRowEnabled(menu, gameMenuCursor)) return;
  }
}



// Keeps the cursor inside the visible window of a scrolling list.
void TerrainGame::menuFollowCursor(int menu) {
  if (menu < 0 || menu >= MENU_COUNT) return;
  const MenuData& m = MENUS[menu];
  if (m.listTex[0] == '\0' || m.rowsVisible <= 0) {
    gameMenuScroll = 0;
    return;
  }
  if (gameMenuCursor < gameMenuScroll) gameMenuScroll = gameMenuCursor;
  if (gameMenuCursor >= gameMenuScroll + m.rowsVisible)
    gameMenuScroll = gameMenuCursor - m.rowsVisible + 1;
  const int maxScroll = m.entryCount - m.rowsVisible;
  if (gameMenuScroll > maxScroll) gameMenuScroll = maxScroll;
  if (gameMenuScroll < 0) gameMenuScroll = 0;
}



void TerrainGame::renderGameMenu() {
  // A menu that is closing still draws: its transition is the whole reason the
  // index was parked in gameMenuClosing instead of simply cleared.
  const int drawMenu = gameMenuIndex >= 0 ? gameMenuIndex : gameMenuClosing;
  if (drawMenu < 0 || drawMenu >= (int)menuSprites.size()) return;
  if (saveMenuOpen) return;  // the save menu draws on top instead
  const MenuData& m = MENUS[drawMenu];
  Sprite& panel = menuSprites[drawMenu];
  const bool closing = gameMenuIndex < 0;

  // --- resolution scale (docs/menu-styles.md "Resolutions") ----------------
  // A menu is authored in the logical 512x448 space of the interlaced mode, but
  // the framebuffer is 448x448 in 480p, 448x540 in 1080i and 512x512 in full
  // PAL. Scaling by (width/512, height/448) is what keeps the panel the same
  // PHYSICAL size on the TV: the GS display window maps whatever the buffer is
  // across the same raster, so 448 columns cover exactly the width 512 do.
  // That also means the two axes scale by different factors - hence
  // Sprite::drawSize rather than Sprite::scale.
  // Widescreen is ANAMORPHIC (docs/menu-styles.md "Widescreen"): the
  // framebuffer does not change shape, the TV stretches the same signal across
  // a 16:9 raster. A panel drawn with the resolution scale alone would come out
  // a third wider than it was baked, with the text fattened to match - so the
  // horizontal factor divides the window's shape back out and the panel keeps
  // the physical size and proportions it was authored at, whatever the player
  // picks. In 4:3 the ratio is exactly 1 and nothing moves.
  const auto& uiScr = engine->renderer.core.getSettings();
  const float uiAspectFix = (4.0F / 3.0F) / uiScr.getWindowAspect();
  const float uiSX = uiScr.getWidth() / 512.0F * uiAspectFix;
  const float uiSY = uiScr.getHeight() / 448.0F;
  auto sxi = [&](int v) { return (float)v * uiSX; };
  auto syi = [&](int v) { return (float)v * uiSY; };

  // --- the open transition -------------------------------------------------
  // Sprite properties only: an offset added to every piece and one alpha. The
  // baked pixels never move, which is why this costs nothing.
  gameMenuClock += g_frameDt;
  float prog = 1.0F;
  float ofsX = 0.0F, ofsY = 0.0F;
  bool fade = false;
  if (closing) {
    prog = m.closeSec > 0.0F ? 1.0F - menuEase(gameMenuCloseT / m.closeSec, m.closeEase)
                             : 0.0F;
    ofsX = m.closeDX * (1.0F - prog);
    ofsY = m.closeDY * (1.0F - prog);
    fade = m.closeFade != 0;
  } else if (m.openSec > 0.0F) {
    gameMenuOpenT += g_frameDt;
    prog = menuEase(gameMenuOpenT / m.openSec, m.openEase);
    ofsX = m.openDX * (1.0F - prog);
    ofsY = m.openDY * (1.0F - prog);
    fade = m.openFade != 0;
  }
  const unsigned char alpha = (unsigned char)(fade ? 128.0F * prog + 0.5F : 128.0F);
  // The panel is centred on its normalized screen position, in the mode's own
  // buffer, at its scaled size.
  const float baseX =
      m.screenX * uiScr.getWidth() - sxi(m.panelW) * 0.5F + ofsX * uiSX;
  const float baseY =
      m.screenY * uiScr.getHeight() - syi(m.contentH) * 0.5F + ofsY * uiSY;

  if (m.pause) {
    // Sized per frame: a runtime display-mode switch changes the buffer under
    // it, and a dim overlay that misses the edge is very visible.
    menuDimSprite.drawSize = Vec2(uiScr.getWidth(), uiScr.getHeight());
    engine->renderer.renderer2D.render(menuDimSprite);
  }
  // The moving background layer, under everything the panel bakes. Scroll walks
  // the sampling window across the tiled copy; frames jump it between frames.
  // Either way it is one sprite and one offset - no re-bake, no second texture
  // per frame (docs/menu-styles.md "Motion").
  if (m.bgTex[0] != '\0' && drawMenu < (int)menuBgSprites.size()) {
    Sprite& bg = menuBgSprites[drawMenu];
    bg.color.a = alpha;
    bg.drawSize = Vec2(sxi(m.panelW), syi(m.contentH));
    if (m.bgMode == 2 && m.bgFrames > 0) {
      int f = (int)(gameMenuClock / (m.bgSeconds > 0.0F ? m.bgSeconds : 1.0F) *
                    m.bgFrames);
      f %= m.bgFrames;
      if (f < 0) f += m.bgFrames;
      bg.offset = Vec2(0.0F, (float)(f * m.bgFrameH));
    } else {
      auto wrap = [](float v, float span) {
        if (span <= 0.0F) return 0.0F;
        v = fmodf(v, span);
        return v < 0.0F ? v + span : v;
      };
      bg.offset = Vec2(wrap(gameMenuClock * m.bgScrollX, (float)m.bgTileW),
                       wrap(gameMenuClock * m.bgScrollY, (float)m.bgTileH));
    }
    bg.position = Vec2(baseX, baseY);
    engine->renderer.renderer2D.render(bg);
  }

  panel.color.a = alpha;
  panel.drawSize = Vec2(sxi(m.panelW), syi(m.panelH));
  panel.position = Vec2(baseX, baseY);
  engine->renderer.renderer2D.render(panel);

  // A scrolling list settles into its new window instead of jumping. One float:
  // every row-indexed piece below reads `shown` rather than the integer scroll,
  // so the highlight, the values and the rows all move together (they must - a
  // highlight that arrives before its row is worse than no easing).
  if (m.scrollSec > 0.0F) {
    const float k = menuEase(g_frameDt / m.scrollSec, 1);
    gameMenuScrollShown += ((float)gameMenuScroll - gameMenuScrollShown) *
                           (k > 1.0F ? 1.0F : k);
    if (fabsf((float)gameMenuScroll - gameMenuScrollShown) < 0.01F)
      gameMenuScrollShown = (float)gameMenuScroll;
  } else {
    gameMenuScrollShown = (float)gameMenuScroll;
  }
  const float shown = gameMenuScrollShown;

  // --- the row strip of a scrolling list -----------------------------------
  // One window into the strip texture; scrolling moves `offset`, so a 32-row
  // menu costs exactly what an 8-row one does.
  if (m.listTex[0] != '\0' && drawMenu < (int)menuListSprites.size()) {
    Sprite& ls = menuListSprites[drawMenu];
    ls.color.a = alpha;
    ls.offset = Vec2(0.0F, shown * (float)m.rowH);
    ls.drawSize = Vec2(sxi(m.panelW), syi(m.rowsVisible * m.rowH));
    ls.position = Vec2(baseX, baseY + syi(m.row0Y));
    engine->renderer.renderer2D.render(ls);
  }

  // --- row states ----------------------------------------------------------
  // Disabled rows first, then the selected one, all from ONE texture so the
  // draws share a texture bind (a per-row texture switch would re-upload a
  // CLUT every row - see docs/gs-vram.md).
  if (m.rowsTex[0] != '\0' && drawMenu < (int)menuStateSprites.size()) {
    Sprite& ss = menuStateSprites[drawMenu];
    ss.color.a = alpha;
    ss.drawSize = Vec2(sxi(m.rowsCellW), syi(m.rowsCellH));
    const int first = gameMenuScroll;
    const int last = m.rowsVisible > 0 ? first + m.rowsVisible : m.entryCount;
    for (int i = first; i < last && i < m.entryCount; ++i) {
      const MenuEntryData& e = m.entries[i];
      if (e.disCell < 0 || menuRowEnabled(gameMenuIndex, i)) continue;
      ss.offset = Vec2(0.0F, (float)(e.disCell * m.rowsPitch));
      ss.position = Vec2(baseX, baseY + (float)m.row0Y * uiSY +
                                    ((float)i - shown) * (float)m.rowH * uiSY);
      engine->renderer.renderer2D.render(ss);
    }
    const MenuEntryData& sel = m.entries[gameMenuCursor >= 0 && gameMenuCursor < m.entryCount
                                             ? gameMenuCursor
                                             : 0];
    if (sel.selCell >= 0 && menuRowEnabled(gameMenuIndex, gameMenuCursor)) {
      ss.offset = Vec2(0.0F, (float)(sel.selCell * m.rowsPitch));
      ss.position = Vec2(baseX, baseY + (float)m.row0Y * uiSY +
                                    ((float)gameMenuCursor - shown) *
                                        (float)m.rowH * uiSY);
      engine->renderer.renderer2D.render(ss);
      ss.color.a = alpha;  // the pulse is this row's alone
    }
  }

  // --- the selection caret -------------------------------------------------
  // It eases toward its row when the sheet asks for it; with no cursor
  // transition it snaps, which is what every menu did before. A style whose
  // selected row paints a full-width plate turns it off (`marker: none`) - the
  // caret would only sit on top of the plate.
  if (m.entryCount > 0 && m.markerOn) {
    const float targetY =
        (float)m.row0Y + ((float)gameMenuCursor - shown) * (float)m.rowH + 1.0F;
    if (m.cursorSec > 0.0F) {
      if (gameMenuCursorRow != gameMenuCursor) {
        // Re-target: ease from wherever the caret actually is.
        gameMenuCursorRow = gameMenuCursor;
      }
      const float k = menuEase(g_frameDt / m.cursorSec, m.cursorEase);
      gameMenuCursorY += (targetY - gameMenuCursorY) * (k > 1.0F ? 1.0F : k);
      if (gameMenuCursorY < -512.0F || gameMenuCursorY > 1024.0F)
        gameMenuCursorY = targetY;  // first frame / a scene reload
    } else {
      gameMenuCursorY = targetY;
    }
    Sprite& caret = drawMenu < (int)menuCursorSprites.size()
                        ? menuCursorSprites[drawMenu]
                        : menuCursorSprite;
    caret.color.a = alpha;
    caret.drawSize = Vec2(16.0F * uiSX, 16.0F * uiSY);
    const float bob =
        m.bobSec > 0.0F
            ? m.bobPx * sinf(gameMenuClock * 6.2831853F / m.bobSec)
            : 0.0F;
    caret.position = Vec2(baseX + (m.markerX + bob) * uiSX,
                          baseY + gameMenuCursorY * uiSY);
    engine->renderer.renderer2D.render(caret);
  }

  // Toggle/Choice rows: the current option label (or bar), a cell of the baked
  // value strip drawn right-aligned on the row.
  if (m.values[0] != '\0' &&
      drawMenu < (int)menuValueSprites.size()) {
    Sprite& vs = menuValueSprites[drawMenu];
    vs.color.a = alpha;
    vs.drawSize = Vec2(sxi(m.valueCellW), syi(m.valueCellH));
    // The row whose value just changed flashes brighter, which is how a player
    // sees that a press did something on a row whose label never moves.
    if (gameMenuValueFlash > 0.0F) gameMenuValueFlash -= g_frameDt;
    const int first = gameMenuScroll;
    const int last = m.rowsVisible > 0 ? first + m.rowsVisible : m.entryCount;
    for (int i = first; i < last && i < m.entryCount; ++i) {
      const MenuEntryData& e = m.entries[i];
      if (e.cell < 0 || e.optionCount <= 0) continue;
      int v = (e.param >= 0 && e.param < SAVE_VALUE_COUNT)
                  ? (int)saveValues[e.param]
                  : 0;
      if (v < 0) v = 0;
      if (v >= e.optionCount) v = e.optionCount - 1;
      const bool flash = gameMenuValueFlash > 0.0F && i == gameMenuCursor;
      vs.color.r = vs.color.g = vs.color.b = flash ? 255 : 128;
      vs.offset = Vec2(0.0F, (float)((e.cell + v) * m.valuePitch));
      vs.position = Vec2(baseX + sxi(m.valueX),
                         baseY + (float)m.row0Y * uiSY +
                             ((float)i - shown) * (float)m.rowH * uiSY);
      engine->renderer.renderer2D.render(vs);
    }
  }

  // --- the description pane ------------------------------------------------
  // The selected row's cell, drawn into the box the panel already framed.
  if (m.descTex[0] != '\0' && drawMenu < (int)menuDescSprites.size() &&
      gameMenuCursor >= 0 && gameMenuCursor < m.entryCount) {
    const MenuEntryData& e = m.entries[gameMenuCursor];
    if (e.descCell >= 0) {
      Sprite& ds = menuDescSprites[drawMenu];
      ds.color.a = alpha;
      ds.drawSize = Vec2(sxi(m.descCellW), syi(m.descCellH));
      ds.offset = Vec2(0.0F, (float)(e.descCell * m.descPitch));
      ds.position = Vec2(baseX + sxi(m.descX), baseY + syi(m.descY));
      engine->renderer.renderer2D.render(ds);
    }
  }

  // The sheen: a soft band sweeping across the panel, additive so it only ever
  // adds light. It crosses from off the left edge to off the right, then waits
  // out the rest of the period - a sweep every few seconds reads as a highlight,
  // a sweep that never stops reads as a strobe.
  if (m.sheenSec > 0.0F && menuSheenLoaded) {
    const float bandW = m.sheenPx > 0.0F ? m.sheenPx : 48.0F;
    // The band travels from just off the left edge to just off the right, and
    // is CROPPED to the panel on the way in and out. A 2D sprite is not clipped
    // by anything, so without this the sweep is visible beside the menu before
    // it arrives - which is exactly how it was reported. The crop is the same
    // window-into-a-texture trick the value strip uses: move `offset` and
    // shrink `size`, and the sprite samples only the part that belongs inside.
    const float phase = fmodf(gameMenuClock, m.sheenSec) / m.sheenSec;
    const float x0 = phase * ((float)m.panelW + bandW * 2.0F) - bandW;
    const float vx0 = x0 < 0.0F ? 0.0F : x0;
    const float vx1 = x0 + bandW > (float)m.panelW ? (float)m.panelW : x0 + bandW;
    if (vx1 > vx0) {
      const float u0 = (vx0 - x0) / bandW * 64.0F;
      const float u1 = (vx1 - x0) / bandW * 64.0F;
      menuSheenSprite.color.r = (unsigned char)m.sheenR;
      menuSheenSprite.color.g = (unsigned char)m.sheenG;
      menuSheenSprite.color.b = (unsigned char)m.sheenB;
      menuSheenSprite.color.a =
          (unsigned char)((float)m.sheenA * (alpha / 128.0F) * 0.5F);
      menuSheenSprite.offset = Vec2(u0, 0.0F);
      menuSheenSprite.size = Vec2(u1 - u0, 64.0F);
      menuSheenSprite.drawSize = Vec2((vx1 - vx0) * uiSX, syi(m.contentH));
      menuSheenSprite.position = Vec2(baseX + vx0 * uiSX, baseY);
      engine->renderer.renderer2D.render(menuSheenSprite);
    }
  }

  // Rebind rows: the binding name can't be baked (it changes at runtime), so it
  // draws glyph by glyph from the menu font's atlas, right-aligned like the
  // baked option labels. While capturing, the row asks for a press instead.
  if (m.font >= 0 && m.font < FONT_COUNT) {
    const int first = gameMenuScroll;
    const int last = m.rowsVisible > 0 ? first + m.rowsVisible : m.entryCount;
    for (int i = first; i < last && i < m.entryCount; ++i) {
      const MenuEntryData& e = m.entries[i];
      if (e.action != 10) continue;
      const char* txt = "PRESS...";
      char iconTok[40];
      if (menuRebindRow != i) {
        // The LIVE pad binding (inputRebuild already folded the player's
        // override in), shown as the button's ICON when the project has one and
        // as its name otherwise. Never the word "Default" - the row should say
        // what the button IS.
        const int pad = (e.inputAction >= 0 && e.inputAction < INPUT_ACTION_COUNT)
                            ? g_inputBind[e.inputAction].pad
                            : -1;
        const int icon = (pad >= 0 && pad < 16) ? ICON_FOR_PAD[pad] : -1;
        if (icon >= 0) {
          snprintf(iconTok, sizeof(iconTok), "{{%s}}", ICONS[icon].name);
          txt = iconTok;
        } else {
          txt = inputBindLabel(e.inputAction);
        }
      }
      // A long binding ("Left Shift", "Backspace") can still outgrow the right
      // half of a 128px panel, so shrink to fit rather than run over the row's
      // baked label (floor at 50% - below that it stops being readable at PS2
      // resolutions anyway).
      float size = (float)m.rowH * 0.8F * uiSY;
      const float room = (sxi(m.panelW) * 0.5F) - 24.0F * uiSX;
      // The panel around this text is squeezed for widescreen (uiAspectFix),
      // so the binding has to be measured and drawn squeezed too - otherwise
      // it is a third wider than the row it is supposed to sit in.
      float w = fontTextWidth(m.font, txt, size, uiAspectFix);
      if (w > room && w > 0.0F) {
        const float k = room / w;
        size *= k < 0.5F ? 0.5F : k;
        w = fontTextWidth(m.font, txt, size, uiAspectFix);
      }
      drawFontText(engine, m.font, txt, baseX + sxi(m.panelW - 24) - w * 0.5F,
                   baseY + syi(m.row0Y + (i - first) * m.rowH) +
                       syi(m.rowH) * 0.5F,
                   size, uiAspectFix);
    }
  }
}



// Per frame, before any HUD sprite is drawn: apply the flow nodes' requests,
// advance every transition and effect, pose the image and text sprites, and
// integrate the bars. Runs whether or not the HUD is visible, so a hidden
// stack comes back where its animations would have been.
void TerrainGame::updateHudMotion() {
  hudClock += g_frameDt;
  const auto& scr = engine->renderer.core.getSettings();
  const float W = (float)scr.getWidth(), H = (float)scr.getHeight();
  for (int e = 0; e < HUD_ELEM_COUNT; ++e) {
    const bool isText = e >= HUD_ELEM_TEXT0 && e < HUD_ELEM_BAR0;
    // Texts keep the legacy request/timer channel for Set Text Visible, but
    // consume it here so their transition starts in the same frame as image
    // and bar requests. updateAndRenderHudTexts only owns the timer tick/draw.
    if (isText) {
      const int i = e - HUD_ELEM_TEXT0;
      if (scriptCtx.textRequest && scriptCtx.textRequest[i] >= 0) {
        hudTextOn[i] = scriptCtx.textRequest[i] == 2 ? (hudTextOn[i] ? 0 : 1)
                       : scriptCtx.textRequest[i] != 0 ? 1 : 0;
        hudTextTimer[i] = hudTextOn[i] ? scriptCtx.textDuration[i] : 0.0F;
        scriptCtx.textRequest[i] = -1;
      }
    }
    if (hudElemReq[e] >= 0) {
      if (!isText)
        hudElemOn[e] = hudElemReq[e] == 2 ? (hudElemOn[e] ? 0 : 1)
                                          : (hudElemReq[e] != 0 ? 1 : 0);
      hudElemReq[e] = -1;
    }
    if (hudElemFxReq[e] > 0) {
      hudElemFx[e] = hudElemFxReq[e];
      hudElemFxT[e] = 0.0F;
      hudElemFxDur[e] = hudElemFxSecReq[e] < 0.05F ? 0.05F : hudElemFxSecReq[e];
      hudElemFxReq[e] = 0;
    }
    float transSec = 0.0F;
    if (e < HUD_ELEM_TEXT0) transSec = HUD_IMAGES[e].transSec;
    else if (isText) transSec = HUD_TEXTS[e - HUD_ELEM_TEXT0].transSec;
    else transSec = HUD_BARS[e - HUD_ELEM_BAR0].transSec;
    const bool on = isText ? hudTextOn[e - HUD_ELEM_TEXT0] != 0 : hudElemOn[e] != 0;
    const float target = on ? 1.0F : 0.0F;
    if (transSec <= 0.001F) {
      hudElemTrans[e] = target;
    } else {
      const float step = g_frameDt / transSec;
      if (hudElemTrans[e] < target)
        hudElemTrans[e] = hudElemTrans[e] + step > target ? target : hudElemTrans[e] + step;
      else if (hudElemTrans[e] > target)
        hudElemTrans[e] = hudElemTrans[e] - step < target ? target : hudElemTrans[e] - step;
    }
    if (hudElemFx[e] > 0) {
      hudElemFxT[e] += g_frameDt;
      if (hudElemFxT[e] >= hudElemFxDur[e]) hudElemFx[e] = 0;
    }
    hudElemDrawn[e] = 0;
  }
  auto fxProgress = [&](int e) {
    return hudElemFx[e] > 0 ? hudElemFxT[e] / hudElemFxDur[e] : 0.0F;
  };
  // Images: the sprite is re-posed from the baked placement every frame, so
  // no drift accumulates and a Set HUD Visible off/on lands it back exactly.
  for (int i = 0; i < HUD_COUNT && i < (int)hudSprites.size(); ++i) {
    const HudImageData& d = HUD_IMAGES[i];
    float x, y, w, h, a, br;
    if (!hudPose(hudClock, d.anim, d.animPeriod, d.animAmount, d.trans,
                 hudElemTrans[i], hudElemFx[i], fxProgress(i), d.x * W, d.y * H,
                 d.w, d.h, x, y, w, h, a, br))
      continue;
    Sprite& s = hudSprites[i];
    s.position = Vec2(x, y);
    s.size = Vec2(w, h);
    s.color = hudTint(128.0F, 128.0F, 128.0F, br, a);
    hudElemDrawn[i] = 1;
  }
  for (int i = 0; i < HUD_TEXT_COUNT && i < (int)hudTextSprites.size(); ++i) {
    const HudTextData& d = HUD_TEXTS[i];
    const int e = HUD_ELEM_TEXT0 + i;
    float x, y, w, h, a, br;
    if (!hudPose(hudClock, d.anim, d.animPeriod, d.animAmount, d.trans,
                 hudElemTrans[e], hudElemFx[e], fxProgress(e), d.x * W, d.y * H,
                 (float)d.w, (float)d.h, x, y, w, h, a, br))
      continue;
    Sprite& s = hudTextSprites[i];
    s.position = Vec2(x, y);
    s.size = Vec2(w, h);
    s.color = hudTint(128.0F, 128.0F, 128.0F, br, a);
    hudElemDrawn[e] = 1;
  }
  // Bars: the fill eases toward the value; the ghost strip holds where the
  // fill was for a beat, then slides down after it. A rise takes the ghost
  // with it at once - the strip only ever shows what was LOST.
  for (int b = 0; b < HUD_BAR_COUNT; ++b) {
    const HudBarData& d = HUD_BARS[b];
    const float span = d.maxV - d.minV;
    const float raw = (d.source >= 0 && d.source < (int)saveValues.size())
                          ? saveValues[d.source]
                          : hudBarValue[b];
    float target = span > 0.0F ? (raw - d.minV) / span : 0.0F;
    target = target < 0.0F ? 0.0F : target > 1.0F ? 1.0F : target;
    bool snap = d.smoothing <= 0.0F;
    if (hudBarSet[b] >= 0) {
      if (hudBarSet[b] == 2) snap = true;
      hudBarSet[b] = -1;
    }
    float shown = hudBarShown[b];
    if (snap) {
      shown = target;
    } else {
      shown += (target - shown) * (1.0F - expf(-g_frameDt / d.smoothing));
      if (fabsf(target - shown) < 0.0005F) shown = target;
    }
    float ghost = hudBarGhost[b];
    if (snap || shown >= ghost) {
      ghost = shown;
      hudBarHold[b] = 0.35F;
    } else if (hudBarHold[b] > 0.0F) {
      hudBarHold[b] -= g_frameDt;
    } else {
      ghost -= g_frameDt * 1.0F;
      if (ghost < shown) ghost = shown;
    }
    hudBarShown[b] = shown;
    hudBarGhost[b] = ghost;
  }
}



// Draws the bars above the HUD stack: track, ghost, fill (a tinted quad, or
// the fill image cropped to the fraction), then the frame image over all of
// it. A quantized bar lights whole segments instead.
void TerrainGame::renderHudBars() {
  const auto& scr = engine->renderer.core.getSettings();
  const float W = (float)scr.getWidth(), H = (float)scr.getHeight();
  auto quad = [&](float x, float y, float w, float h, const float* c, float bright,
                  float alpha) {
    if (w < 0.5F || h < 0.5F) return;
    hudBarQuad.size = Vec2(w, h);
    hudBarQuad.position = Vec2(x, y);
    hudBarQuad.color = hudTint(c[0], c[1], c[2], bright, alpha);
    engine->renderer.renderer2D.render(hudBarQuad);
  };
  for (int b = 0; b < HUD_BAR_COUNT; ++b) {
    const HudBarData& d = HUD_BARS[b];
    const int e = HUD_ELEM_BAR0 + b;
    float x, y, w, h, a, br;
    if (!hudPose(hudClock, d.anim, d.animPeriod, d.animAmount, d.trans,
                 hudElemTrans[e], hudElemFx[e],
                 hudElemFx[e] > 0 ? hudElemFxT[e] / hudElemFxDur[e] : 0.0F,
                 d.x * W, d.y * H, d.w, d.h, x, y, w, h, a, br))
      continue;
    hudElemDrawn[e] = 1;
    const float shown = hudBarShown[b];
    const float ghost = hudBarGhost[b];
    // The "low" pulse: a slow breath on the fill's alpha once the value is
    // under the authored fraction - the health bar asking for attention.
    float fillA = a;
    if (d.lowFrac > 0.0F && shown < d.lowFrac && shown > 0.0F)
      fillA *= 0.55F + 0.45F * (0.5F + 0.5F * sinf(hudClock * 6.2831853F / 0.6F));
    if (d.kind == 0) {
      quad(x, y, w, h, d.bg, 1.0F, a);
      const float fw = w * shown;
      const float gw = w * ghost;
      const float fx = d.rightToLeft ? x + w - fw : x;
      if (d.hasGhost && gw > fw + 0.5F)
        quad(d.rightToLeft ? x + w - gw : x, y, gw, h, d.ghost, 1.0F, a);
      if (d.fillPath[0] != '\0' && hudBarFillTexW[b] > 0) {
        Sprite& fs = hudBarFillSprites[b];
        const float texW = (float)hudBarFillTexW[b] * shown;
        fs.offset = Vec2(d.rightToLeft ? (float)hudBarFillTexW[b] - texW : 0.0F, 0.0F);
        fs.size = Vec2(texW, (float)hudBarFillTexH[b]);
        fs.drawSize = Vec2(fw, h);
        fs.position = Vec2(fx, y);
        fs.color = hudTint(d.fill[0], d.fill[1], d.fill[2], br, fillA);
        if (fw >= 0.5F) engine->renderer.renderer2D.render(fs);
      } else {
        quad(fx, y, fw, h, d.fill, br, fillA);
      }
    } else {
      const int segs = d.segments < 1 ? 1 : d.segments;
      const int lit = (int)(shown * segs + 0.001F);
      const int litGhost = (int)(ghost * segs + 0.001F);
      const float segW = (w - d.spacing * (segs - 1)) / segs;
      for (int k = 0; k < segs; ++k) {
        const int kk = d.rightToLeft ? segs - 1 - k : k;
        const float sx = x + kk * (segW + d.spacing);
        const bool on = k < lit;
        const bool wasOn = d.hasGhost && !on && k < litGhost;
        const float* c = on ? d.fill : wasOn ? d.ghost : d.bg;
        const float sa = on ? fillA : a;
        if (d.fillPath[0] != '\0' && hudBarFillTexW[b] > 0) {
          Sprite& fs = hudBarFillSprites[b];
          fs.offset = Vec2(0.0F, 0.0F);
          fs.size = Vec2((float)hudBarFillTexW[b], (float)hudBarFillTexH[b]);
          fs.drawSize = Vec2(segW, h);
          fs.position = Vec2(sx, y);
          fs.color = hudTint(c[0], c[1], c[2], on ? br : 1.0F, sa);
          engine->renderer.renderer2D.render(fs);
        } else {
          quad(sx, y, segW, h, c, on ? br : 1.0F, sa);
        }
      }
    }
    if (d.framePath[0] != '\0') {
      Sprite& fr = hudBarFrameSprites[b];
      const float scale = d.w > 0.0F ? w / d.w : 1.0F;
      const float fw = d.frameW * scale, fh = d.frameH * scale;
      fr.size = Vec2(fw, fh);
      fr.position = Vec2(x + w * 0.5F - fw * 0.5F, y + h * 0.5F - fh * 0.5F);
      fr.color = hudTint(128.0F, 128.0F, 128.0F, br, a);
      engine->renderer.renderer2D.render(fr);
    }
  }
}



// On-screen texts: tick the auto-hide timers and draw what is visible. Baked
// sprites - one 2D quad each. Requests were consumed by updateHudMotion so a
// show/hide transition starts in the frame its flow node fires.
// The sprite was posed by updateHudMotion (transition + loop), which is also
// why a text still draws while hudTextOn is 0: it is on its way out.
void TerrainGame::updateAndRenderHudTexts() {
  for (int i = 0; i < (int)hudTextSprites.size(); ++i) {
    if (hudTextOn[i] && hudTextTimer[i] > 0.0F) {
      hudTextTimer[i] -= g_frameDt;
      if (hudTextTimer[i] <= 0.0F) {
        hudTextOn[i] = 0;
        hudTextTimer[i] = 0.0F;
      }
    }
    const int e = HUD_ELEM_TEXT0 + i;
    // A "Hide HUD" cutscene takes the baked texts with the rest of the HUD -
    // but only the DRAWING: the auto-hide countdown above keeps running, or a
    // text shown just before a cutscene would still be on screen after it
    // (docs/cutscenes.md). Runtime text (Display Text) is deliberately not
    // covered - that is where a cutscene's subtitles live.
    if (e < (int)hudElemDrawn.size() && hudElemDrawn[e] &&
        !scriptCtx.hudSuppressed)
      engine->renderer.renderer2D.render(hudTextSprites[i]);
  }
}



// Sun screen effects, part 1 (before the post-fx pass): projects the sun -
// it sits infinitely far along the lighting direction, so only the DIRECTION
// matters - feeds the god-rays pass its screen position + visibility factor,
// and eases the lens flare's occlusion fade (one ray toward the sun: object
// bounding spheres + a terrain march). Part 2 (renderFlare) draws the flare
// sprites AFTER the post-fx pass so they sit on top of DoF and the rays.
void TerrainGame::updateSunFx() {
  auto& postFx = engine->renderer.core.postFx;
  const float amount =
      flareTexturesLoaded ? g_flareAmount * (1.0F / 128.0F) : 0.0F;
  flareAmt = amount;
  const bool wantRays = postFx.getGodRays() > 0;
  if (amount <= 0.0F && !wantRays) {
    flareVis = 0.0F;
    return;
  }

  // A lens flare is the SUN, not "the light". Without a day/night cycle those
  // are the same thing and SCENE_LIGHT_* is the sun vector. With one they are
  // not: after sunset the resolved light is the MOON (clamped above the horizon
  // so the bake stays sane), and pointing the flare at it put a blue glow with
  // ghost rings in the night sky - the moon wearing the sun's lens flare. So a
  // cycle scene aims at SCENE_SUN_* and switches the whole effect off while the
  // sun is down (SCENE_SUN_R is 0 exactly then, the same flag the disc uses).
  float sxd, syd, szd;
  if (daynight::active(currentScene)) {
    if (daynight::g_sunRad <= 0.0F) {
      postFx.setGodRaysSun(0.0F, 0.0F, 0.0F);
      flareVis = 0.0F;
      return;
    }
    sxd = daynight::g_sun[0], syd = daynight::g_sun[1], szd = daynight::g_sun[2];
  } else if (DAYCYCLE_USED) {
    if (SCENE_SUN_R <= 0.0F) {
      postFx.setGodRaysSun(0.0F, 0.0F, 0.0F);
      flareVis = 0.0F;
      return;
    }
    sxd = SCENE_SUN_X, syd = SCENE_SUN_Y, szd = SCENE_SUN_Z;
  } else {
    sxd = SCENE_LIGHT_X, syd = SCENE_LIGHT_Y, szd = SCENE_LIGHT_Z;
  }
  const float sl = sqrtf(sxd * sxd + syd * syd + szd * szd);
  if (sl < 0.0001F) {
    postFx.setGodRaysSun(0.0F, 0.0F, 0.0F);
    flareVis = 0.0F;
    return;
  }
  sxd /= sl, syd /= sl, szd /= sl;

  const auto& scr = engine->renderer.core.getSettings();
  const float W = scr.getWidth(), H = scr.getHeight();
  // THE PROJECTION IS NOT NDC, and its y is not flipped either. Tyra's
  // perspective matrix is built for the VU1 pipeline's fixed 2048 scale:
  // after the homogeneous divide the frustum edges sit at
  // |x| = w * rasterW / 4096 and |y| = w * rasterH / 4096, not at |x| = w
  // (see the tyra-engine-dev skill - "the screen edge is at width/4096 of
  // w, 0.125 at 512 px"). The matrix also already carries the GS's
  // downward y (its data[5] is -h), so raster y is rasterH/2 + 2048 * y/w
  // with no second flip - which is what the engine itself does in
  // RendererCoreBlss::addBagSphere, in Renderer3DUtility::convertVertices
  // and in the shadow-map STs.
  //
  // Reading x/w as [-1, 1] and flipping y therefore pulled the sun
  // 4096/rasterW (8x at 512 px) toward the middle of the screen AND put it
  // on the wrong side of it. Measured on the dawn plaza of examples/
  // day-night: the sun disc the 3D pipeline drew at (410, 127) of a
  // 512x512 raster was reported at (275, 272), so the god rays zoomed
  // toward a point near the screen centre instead of the sun, the flare
  // ghosts walked the wrong axis, and the 80 px / 220 px edge bands (and
  // the "sun off screen" decision) faded at the wrong angles. The
  // flashlight's count rect had the same NDC mistake until 1.65.0.
  //
  // Both consumers want DISPLAY pixels: RendererCorePostFx scales raysSunX
  // by the frame width and raysSunY by getHeight(), and the ghosts are 2D
  // sprites in display space. So normalise against the RASTER the
  // projection was built for - it differs from the display size only under
  // the BLSS raster scale or field rendering - and land the result on the
  // display size.
  const float sunSx = 4096.0F / scr.getRasterWidthF();
  const float sunSy = 4096.0F / scr.getRasterHeightF();

  float target = 0.0F, px = 0.0F, py = 0.0F, raysVis = 0.0F;
  float edge = 0.0F;
  const Vec4 sunWorld(cameraPosition.x + sxd * 500.0F,
                      cameraPosition.y + syd * 500.0F,
                      cameraPosition.z + szd * 500.0F, 1.0F);
  const Vec4 clip = engine->renderer.core.renderer3D.getViewProj() * sunWorld;
  if (clip.w > 0.0F) {
    px = (clip.x / clip.w * sunSx * 0.5F + 0.5F) * W;
    py = (clip.y / clip.w * sunSy * 0.5F + 0.5F) * H;
    const float mx = px < 0.0F ? -px : (px > W ? px - W : 0.0F);
    const float my = py < 0.0F ? -py : (py > H ? py - H : 0.0F);
    const float m = mx > my ? mx : my;
    // Flare fades over an 80px band past the edge; the rays keep working
    // with the sun well off screen (streaks reach in from the border).
    edge = 1.0F - m * (1.0F / 80.0F);
    raysVis = 1.0F - m * (1.0F / 220.0F);
  }
  flareSunX = px, flareSunY = py;
  postFx.setGodRaysSun(px, py, raysVis);

  if (amount > 0.0F && edge > 0.0F) {
    // Flare occlusion: one ray from the camera toward the sun. Objects as
    // bounding spheres (marker types skipped), then a terrain march -
    // cheap enough to run every frame.
    bool clear = true;
    for (int i = 0; i < (int)runtimeObjects.size() && clear; ++i) {
      const RuntimeObject& o = runtimeObjects[i];
      if (!o.active || !o.visible || i == PLAYER_INDEX) continue;
      const int ty = o.data.type;
      if (ty == 4 || ty == 6 || ty == 7 || ty == 8 || ty == 9 || ty == 11 ||
          ty == 13 || ty == 14)
        continue;
      float half = o.data.scale[0];
      if (o.data.scale[1] > half) half = o.data.scale[1];
      if (o.data.scale[2] > half) half = o.data.scale[2];
      const float cx = o.data.position[0] - cameraPosition.x;
      const float cy = o.data.position[1] - cameraPosition.y;
      const float cz = o.data.position[2] - cameraPosition.z;
      const float tca = cx * sxd + cy * syd + cz * szd;
      if (tca < 0.0F) continue;
      const float d2 = cx * cx + cy * cy + cz * cz - tca * tca;
      if (d2 < half * half) clear = false;
    }
    for (float t = 2.0F; t <= 80.0F && clear; t += 2.0F) {
      if (cameraPosition.y + syd * t <=
          terrainHeightAt(cameraPosition.x + sxd * t,
                          cameraPosition.z + szd * t))
        clear = false;
    }
    if (clear) target = edge > 1.0F ? 1.0F : edge;
  }

  // Ease toward the target so occlusion changes never pop.
  const float k = g_frameDt * 6.0F;
  flareVis += (target - flareVis) * (k > 1.0F ? 1.0F : k);

  // Position + tint the ghost sprites now, then draw the MAIN sun glow
  // (sprite 0) before the post-fx pass: the god rays bright-pass picks it
  // up, so the shafts visibly emanate from the sun itself. The remaining
  // ghosts draw after the pass (renderFlare) so they stay crisp.
  if (flareAmt <= 0.0F || flareVis <= 0.01F) return;
  const float axc = W * 0.5F - px, ayc = H * 0.5F - py;
  // A ghost is a 2D SPRITE, and the 2D renderer does not author sprites in
  // display rows: RendererCore2D lays them out in the stock 512x448 space and
  // letterboxes THAT into the raster (SPRITE_SPACE_HEIGHT and its originY
  // term), so in a scan mode with more than 448 rows the sprite at row n lands
  // (renderHeight - 448) / 2 rows further down the picture. The god rays want
  // display pixels (RendererCorePostFx divides by getHeight()), but a flare
  // has to sit on the SUN rather than on the HUD's layout, so the sprites get
  // that offset taken back off. Zero in the stock 512x448 and in
  // InterlacedField (same logical height); 32 rows in Pal576i, 46 in
  // HiDef1080i - measured as a glow hanging ~29 px below the sun disc on the
  // 512x512 dawn plaza of examples/day-night.
  const float spriteDy = (H - 448.0F) * 0.5F;
  // t = position on the sun -> screen-center axis (1 = at the sun,
  // 0 = center, negative = mirrored past center).
  struct Ghost { float t, size, alpha; };
  static const Ghost ghosts[4] = {{1.0F, 160.0F, 1.0F},
                                  {0.55F, 44.0F, 0.35F},
                                  {0.25F, 90.0F, 0.45F},
                                  {-0.35F, 56.0F, 0.30F}};
  const float lr = SCENE_LIGHT_COL_R, lg = SCENE_LIGHT_COL_G,
              lb = SCENE_LIGHT_COL_B;
  for (int i = 0; i < 4; ++i) {
    const Ghost& g = ghosts[i];
    Sprite& s = flareSprites[i];
    const float gx = px + axc * (1.0F - g.t), gy = py + ayc * (1.0F - g.t);
    const float size = g.size * (0.6F + 0.4F * flareAmt);
    s.size = Vec2(size, size);
    s.position = Vec2(gx - size * 0.5F, gy - size * 0.5F - spriteDy);
    const float a = 128.0F * flareAmt * flareVis * g.alpha;
    // Tint by the scene light color (128 = unmodulated texel).
    s.color = Tyra::Color(128.0F * lr, 128.0F * lg, 128.0F * lb, a);
  }
  // Sprites stamp z across their whole rect, and the DoF composite is
  // z-tested - a pre-pass sprite would punch a blur rectangle into it. So
  // the glow feeds the rays only while DoF is off; with DoF active it draws
  // after the pass with the other ghosts (rays then streak scene light only).
  flarePreDrawn = engine->renderer.core.postFx.getDepthOfField() == 0;
  if (flarePreDrawn) engine->renderer.renderer2D.render(flareSprites[0]);
}



// Sun lens flare, part 2: the remaining ghost sprites (the main glow drew in
// updateSunFx, pre-post-fx). Drawn right after the post-fx pass (DoF + god
// rays), under the whole HUD stack.
void TerrainGame::renderFlare() {
  if (flareAmt <= 0.0F || flareVis <= 0.01F) return;
  for (int i = flarePreDrawn ? 1 : 0; i < 4; ++i)
    engine->renderer.renderer2D.render(flareSprites[i]);
}



// The night sky (docs/day-night-cycle.md "Stars"). Builds one additive bag per
// magnitude tier out of the generated STARS table - the same list
// starfield::generate handed the editor, so the console's sky IS the preview's.
//
// Additive is the whole feature: the GS computes Cs*FIX + Cd, so a star ADDS
// its colour to the sky behind it. That is what makes a bright star bright
// (and gives the bloom pass something to flare) rather than a grey pixel, and
// it is why the per-star colour lives in the Gouraud vertex colours.
//
// The quads are built once in WORLD space around the origin and the bag is
// re-centred on the camera each frame like the sky dome; VU1 does the rest.
void TerrainGame::buildStarField() {
  for (int t = 0; t < STAR_TIERS; ++t) {
    starBags[t].verts.clear();
    starBags[t].colors.clear();
    starBags[t].bag.reset();
  }
  if (STAR_COUNT <= 0) return;

  const float diag = TERRAIN_WIDTH > TERRAIN_DEPTH ? TERRAIN_WIDTH : TERRAIN_DEPTH;
  float domeR = diag * 1.5F;
  if (domeR < 60.0F) domeR = 60.0F;
  if (domeR > 450.0F) domeR = 450.0F;
  // Further out than the sun and moon discs (0.94), so a star can never
  // z-fight its way in front of the moon.
  const float dist = domeR * 0.96F;

  for (int i = 0; i < STAR_COUNT; ++i) {
    const StarData& sd = STARS[i];
    int t = sd.tier;
    if (t < 0) t = 0;
    if (t >= STAR_TIERS) t = STAR_TIERS - 1;
    StarBag& sb = starBags[t];
    const float half = dist * sd.size;
    const float cx = sd.x * dist, cy = sd.y * dist, cz = sd.z * dist;
    // A star is a dot: two triangles in the plane perpendicular to its own
    // direction. It is far enough away that not billboarding it costs nothing
    // visible, and it keeps the bag STATIC - which is what makes the whole sky
    // three submits and no per-frame vertex work.
    float rx = -sd.z, ry = 0.0F, rz = sd.x;  // cross(up, dir)
    const float rl = sqrtf(rx * rx + rz * rz);
    if (rl < 1e-4F) { rx = 1.0F; ry = 0.0F; rz = 0.0F; }
    else { rx /= rl; rz /= rl; }
    const float ux = sd.y * rz - sd.z * ry;
    const float uy = sd.z * rx - sd.x * rz;
    const float uz = sd.x * ry - sd.y * rx;
    const Vec4 c0(cx + (-rx - ux) * half, cy + (-ry - uy) * half,
                  cz + (-rz - uz) * half, 1.0F);
    const Vec4 c1(cx + (rx - ux) * half, cy + (ry - uy) * half,
                  cz + (rz - uz) * half, 1.0F);
    const Vec4 c2(cx + (rx + ux) * half, cy + (ry + uy) * half,
                  cz + (rz + uz) * half, 1.0F);
    const Vec4 c3(cx + (-rx + ux) * half, cy + (-ry + uy) * half,
                  cz + (-rz + uz) * half, 1.0F);
    // 128 is full strength in the engine's colour space for an untextured bag.
    const Color col((float)sd.r * 0.5F, (float)sd.g * 0.5F, (float)sd.b * 0.5F,
                    128.0F);
    sb.verts.push_back(c0); sb.verts.push_back(c1); sb.verts.push_back(c2);
    sb.verts.push_back(c0); sb.verts.push_back(c2); sb.verts.push_back(c3);
    // Full-sprite STs: the star IS the soft dot. Without the texture a star
    // draws as a hard little square, which is the "grey pixel" look the whole
    // additive arrangement exists to avoid.
    sb.sts.push_back(Vec4(0.0F, 0.0F, 1.0F, 0.0F));
    sb.sts.push_back(Vec4(1.0F, 0.0F, 1.0F, 0.0F));
    sb.sts.push_back(Vec4(1.0F, 1.0F, 1.0F, 0.0F));
    sb.sts.push_back(Vec4(0.0F, 0.0F, 1.0F, 0.0F));
    sb.sts.push_back(Vec4(1.0F, 1.0F, 1.0F, 0.0F));
    sb.sts.push_back(Vec4(0.0F, 1.0F, 1.0F, 0.0F));
    for (int k = 0; k < 6; ++k) sb.colors.push_back(col);
  }

  for (int t = 0; t < STAR_TIERS; ++t) {
    StarBag& sb = starBags[t];
    if (sb.verts.empty()) continue;
    sb.info = std::make_unique<StaPipInfoBag>();
    sb.info->model = &starMat;  // re-centred on the camera every frame
    sb.info->shadingType = TyraShadingGouraud;
    // NOT the dome's precise/full-clip settings, and this is a measured
    // decision: the dome is ~500 vertices of huge triangles that genuinely
    // cross the screen edge, while the field is ~3000 vertices of tiny quads
    // scattered all over it. Precise per-package classification plus the EE
    // clipper on that many crossing packages cost ~6 FPS of a 32 FPS sky view
    // in PCSX2 (26 -> 32 with the field off). A star is a few pixels: dropping
    // one whose package straddles the border is invisible, and clipping it is
    // not worth a millisecond.
    // _None, not the dome's _Precise: the field is CENTRED ON THE CAMERA, so
    // it surrounds the view by construction and per-package classification can
    // only ever answer "keep" while costing a bbox test per package.
    sb.info->frustumCulling = PipelineInfoBagFrustumCulling_None;
    sb.info->fullClipChecks = false;
    sb.info->fogDisabled = true;    // past the fog end, like the dome
    sb.info->dynLightPick = false;  // a torch must not tint the sky
    sb.info->blssProxy = false;     // a camera-centred shell, like the dome
    sb.info->additiveBlendFix = 128;
    sb.colorBag = std::make_unique<StaPipColorBag>();
    sb.colors.bind(sb.colorBag);
    sb.bag = std::make_unique<StaPipBag>();
    sb.bag->info = sb.info.get();
    sb.bag->color = sb.colorBag.get();
    sb.verts.bind(sb.bag);
    sb.bag->count = static_cast<u32>(sb.verts.size());
    if (beamCoronaTex) {
      sb.texBag = std::make_unique<StaPipTextureBag>();
      sb.texBag->texture = beamCoronaTex;
      sb.sts.bind(sb.texBag);
      sb.bag->texture = sb.texBag.get();
    } else {
      sb.bag->texture = nullptr;
    }
    sb.bag->lighting = nullptr;
    sb.bag->bboxVersion = ++g_bboxStamp;
  }
}



// Submits the field. The scene's star brightness and the twinkle both ride the
// additive FIX, so this is three byte writes and three submits - no geometry
// touched, whatever the time of day.
void TerrainGame::renderStarField() {
  const bool liveSky = daynight::active(currentScene);
  const float starLevel = liveSky ? daynight::g_stars : SCENE_STARS_BRIGHT;
  if (STAR_COUNT <= 0 || starLevel <= 0.004F) return;
  if (!g_gameplayPaused) g_starTime += g_frameDt;
  starMat.identity();
  starMat.data[12] = cameraPosition.x;
  starMat.data[13] = cameraPosition.y;
  starMat.data[14] = cameraPosition.z;
  for (int t = 0; t < STAR_TIERS; ++t) {
    StarBag& sb = starBags[t];
    if (!sb.bag) continue;
    float k = starLevel;
    if (SCENE_STARS_TWINKLE > 0.0F) {
      // Per TIER, not per star: each tier shimmers at its own rate, which is
      // enough to read as twinkling and costs three multiplies a frame.
      const float phase =
          g_starTime * (0.7F + 0.45F * (float)t) + (float)t * 2.1F;
      k *= 1.0F - SCENE_STARS_TWINKLE * 0.35F * (0.5F - 0.5F * cosf(phase));
    }
    // ...and the same compensation, averaged over the channels because the FIX
    // is a single scalar for the whole bag.
    if (liveSky)
      k *= (daynight::g_comp[0] + daynight::g_comp[1] + daynight::g_comp[2]) / 3.0F;
    float fix = 128.0F * k;
    sb.info->additiveBlendFix =
        fix > 255.0F ? 255 : (fix < 1.0F ? 1 : (u8)fix);
    stapip.core.render(sb.bag.get());
  }
}



// The runtime half of the day/night cycle (docs/day-night-cycle.md, "The
// hybrid"). One call a frame, and everything it moves is something the frame was
// already going to compute: the sun and moon directions, the sky gradient, the
// fog colour, the star brightness and a colour grade. The BAKED half - vertex
// shading, the AO lightmap, GI - stays at the hour the scene was built at,
// which is exactly what the grade is here to paper over.
void TerrainGame::dayNightTick() {
  if (!daynight::active(currentScene)) return;
  daynight::tick(currentScene, g_frameDt);

  // The horizon rides scriptCtx.skyColor, which the dome retint already
  // watches (and which a Set Ambience node also writes - last writer in the
  // frame wins, and a running clock is the more specific statement). The
  // zenith is staged for the same check.
  // g_comp cancels the full-screen grade on everything that is already
  // hour-correct - see ambience::driftCompensation. Without it the night sky is
  // graded a second time and comes out nearly black.
  auto c255 = [](float v, float comp) {
    const float x = v * 255.0F * comp;
    return x > 255.0F ? 255.0F : x;
  };
  scriptCtx.skyColor = Color(c255(daynight::g_sky[0], daynight::g_comp[0]),
                             c255(daynight::g_sky[1], daynight::g_comp[1]),
                             c255(daynight::g_sky[2], daynight::g_comp[2]));
  engine->renderer.setClearScreenColor(scriptCtx.skyColor);
  dayNightTopR = c255(daynight::g_top[0], daynight::g_comp[0]);
  dayNightTopG = c255(daynight::g_top[1], daynight::g_comp[1]);
  dayNightTopB = c255(daynight::g_top[2], daynight::g_comp[2]);

  if (FOG_ENABLED)
    engine->renderer.core.setFog(Color(c255(daynight::g_fog[0], daynight::g_comp[0]),
                                      c255(daynight::g_fog[1], daynight::g_comp[1]),
                                      c255(daynight::g_fog[2], daynight::g_comp[2])),
                                 FOG_START, FOG_END);

  // The drift grade. setGrading is a handful of register writes, so this is
  // cheaper than any of the geometry it stands in for - and it is identity while
  // the clock sits on the baked hour, so a parked cycle changes nothing.
  if (daynight::gradeOn(currentScene)) {
    // setGrading is fixed point: gain 128 = 1x, lift is a signed 0..255-scale
    // offset, mixAmt 128 = full replace. The float globals stay the twin of the
    // host's ambience::driftGrade; the conversion lives only here.
    auto u8 = [](float v) {
      const int n = (int)(v + 0.5F);
      return (unsigned char)(n < 0 ? 0 : (n > 255 ? 255 : n));
    };
    const unsigned char gain[3] = {u8(daynight::g_gain[0] * 128.0F),
                                   u8(daynight::g_gain[1] * 128.0F),
                                   u8(daynight::g_gain[2] * 128.0F)};
    const short lift[3] = {(short)(daynight::g_lift[0] * 255.0F),
                           (short)(daynight::g_lift[1] * 255.0F),
                           (short)(daynight::g_lift[2] * 255.0F)};
    const unsigned char mixColor[3] = {u8(daynight::g_mixColor[0] * 255.0F),
                                       u8(daynight::g_mixColor[1] * 255.0F),
                                       u8(daynight::g_mixColor[2] * 255.0F)};
    float amt = daynight::g_mixAmount * 128.0F;
    if (amt > 128.0F) amt = 128.0F;
    engine->renderer.core.postFx.setGrading(gain, lift, mixColor,
                                            (unsigned char)(amt + 0.5F));
  }
}



// Day/night cycle sky bodies (docs/day-night-cycle.md): one-time setup of the
// sun and moon quads. Six vertices each and a fixed full-sprite ST quad; the
// positions are written every frame by renderSkyBodies.
//
// The two differ in how they blend, and it is not a style choice. The sun is
// ADDITIVE (Cs*FIX + Cd), which is what makes it read as a light source and
// what feeds the bloom pass a bright spot to flare - so its sprite carries its
// shape in RGB, because an additive bag never reads texture alpha. The moon is
// an ordinary alpha-blended quad: it is a lit ROCK, and adding it to the sky
// would make a night sky glow through it.
void TerrainGame::setupSkyBodies() {
  if (!DAYCYCLE_USED) return;
  auto init = [](SkyBody& b, Tyra::Texture* tex, bool additive) {
    b.verts.assign(6, Vec4(0.0F, 0.0F, 0.0F, 1.0F));
    b.sts.clear();
    // Two triangles over the whole sprite, matching the corner order below.
    b.sts.push_back(Vec4(0.0F, 0.0F, 1.0F, 0.0F));
    b.sts.push_back(Vec4(1.0F, 0.0F, 1.0F, 0.0F));
    b.sts.push_back(Vec4(1.0F, 1.0F, 1.0F, 0.0F));
    b.sts.push_back(Vec4(0.0F, 0.0F, 1.0F, 0.0F));
    b.sts.push_back(Vec4(1.0F, 1.0F, 1.0F, 0.0F));
    b.sts.push_back(Vec4(0.0F, 1.0F, 1.0F, 0.0F));
    b.color = Color(128.0F, 128.0F, 128.0F, 128.0F);
    b.mat.identity();
    b.info = std::make_unique<StaPipInfoBag>();
    b.info->model = &b.mat;
    b.info->shadingType = TyraShadingFlat;
    b.info->frustumCulling = PipelineInfoBagFrustumCulling_Precise;
    // The discs ride the dome, past the fog end - hardware fog would paint
    // them solid fog colour, exactly as it would the dome itself.
    b.info->fogDisabled = true;
    // Centred on the camera like the dome: a nearby torch must not tint the sun.
    b.info->dynLightPick = false;
    // ...and it rides the dome, so it is a shell fragment too - see the dome's
    // blssProxy. A disc at 94% of the dome radius has a w range the upscaler
    // would read as "the far plane, everywhere it covers".
    b.info->blssProxy = false;
    b.info->fullClipChecks = true;  // crosses the screen edge constantly
    if (additive) b.info->additiveBlendFix = 128;
    else b.info->blendingEnabled = true;
    b.colorBag = std::make_unique<StaPipColorBag>();
    b.colorBag->single = &b.color;
    b.texBag = std::make_unique<StaPipTextureBag>();
    b.texBag->texture = tex;
    b.sts.bind(b.texBag);
    b.bag = std::make_unique<StaPipBag>();
    b.bag->info = b.info.get();
    b.bag->color = b.colorBag.get();
    b.bag->texture = b.texBag.get();
    b.verts.bind(b.bag);
    b.bag->count = 6;
  };
  if (sunDiscTex) init(sunBody, sunDiscTex, true);
  if (moonDiscTex) init(moonBody, moonDiscTex, false);
}



// Places and submits the two discs. Called right after the sky dome, so they
// are behind everything and write no depth of their own.
void TerrainGame::renderSkyBodies(const Vec4& eye, const Vec4& look) {
  if (!DAYCYCLE_USED) return;
  // View basis: the quads are billboards, so their corners are rebuilt from
  // this view's right/up every frame (six vertices - the beam-corona deal).
  V3 fwd = {look.x - eye.x, look.y - eye.y, look.z - eye.z};
  float fl = sqrtf(fwd.x * fwd.x + fwd.y * fwd.y + fwd.z * fwd.z);
  if (fl < 1e-4F) return;
  fwd.x /= fl, fwd.y /= fl, fwd.z /= fl;
  V3 right = {fwd.z, 0.0F, -fwd.x};
  float rl = sqrtf(right.x * right.x + right.z * right.z);
  if (rl < 1e-4F) {
    right = {1.0F, 0.0F, 0.0F};
    rl = 1.0F;
  }
  right.x /= rl, right.y = 0.0F, right.z /= rl;
  const V3 up = {right.y * fwd.z - right.z * fwd.y,
                 right.z * fwd.x - right.x * fwd.z,
                 right.x * fwd.y - right.y * fwd.x};

  // The dome's own radius, so a body sits ON the sky rather than in front of
  // the terrain. Mirrors buildSkyDome's clamp - keep the two in step.
  const float diag = TERRAIN_WIDTH > TERRAIN_DEPTH ? TERRAIN_WIDTH : TERRAIN_DEPTH;
  float domeR = diag * 1.5F;
  if (domeR < 60.0F) domeR = 60.0F;
  if (domeR > 450.0F) domeR = 450.0F;
  // Just inside the dome, or z-fighting decides per frame whether the sun is
  // in front of the sky.
  const float dist = domeR * 0.94F;

  auto place = [&](SkyBody& b, float dx, float dy, float dz, float rFrac,
                   float roll) {
    if (!b.bag || rFrac <= 0.0F) return;
    if (b.color.a <= 1.0F) return;  // fully transparent: nothing to draw
    const float cx = eye.x + dx * dist;
    const float cy = eye.y + dy * dist;
    const float cz = eye.z + dz * dist;
    const float half = dist * rFrac;
    // Roll the billboard axes so the moon's lit limb faces the sun; the sun
    // passes roll 0 and pays only a cosf/sinf of nothing.
    const float cr = cosf(roll), sr = sinf(roll);
    const V3 rx = {right.x * cr + up.x * sr, right.y * cr + up.y * sr,
                   right.z * cr + up.z * sr};
    const V3 uy = {up.x * cr - right.x * sr, up.y * cr - right.y * sr,
                   up.z * cr - right.z * sr};
    const Vec4 c0(cx + (-rx.x - uy.x) * half, cy + (-rx.y - uy.y) * half,
                  cz + (-rx.z - uy.z) * half, 1.0F);
    const Vec4 c1(cx + (rx.x - uy.x) * half, cy + (rx.y - uy.y) * half,
                  cz + (rx.z - uy.z) * half, 1.0F);
    const Vec4 c2(cx + (rx.x + uy.x) * half, cy + (rx.y + uy.y) * half,
                  cz + (rx.z + uy.z) * half, 1.0F);
    const Vec4 c3(cx + (-rx.x + uy.x) * half, cy + (-rx.y + uy.y) * half,
                  cz + (-rx.z + uy.z) * half, 1.0F);
    b.verts[0] = c0;
    b.verts[1] = c1;
    b.verts[2] = c2;
    b.verts[3] = c0;
    b.verts[4] = c2;
    b.verts[5] = c3;
    b.bag->bboxVersion = ++g_bboxStamp;
    stapip.core.render(b.bag.get());
  };

  // The sun takes the scene's light colour, so a red sunset sun is red without
  // a second authored colour anywhere.
  // With a running clock every one of these comes from the live evaluation
  // instead of the baked instant; without one they are the same constants they
  // always were. Two branches, no duplicated placement code.
  const bool live = daynight::active(currentScene);
  // The discs are hour-correct already, so they carry the grade compensation
  // (1..2x, which is exactly the headroom a 128-nominal colour bag has).
  const float cr = live ? daynight::g_comp[0] : 1.0F;
  const float cg = live ? daynight::g_comp[1] : 1.0F;
  const float cb2 = live ? daynight::g_comp[2] : 1.0F;
  const float lr = (live ? 1.0F : SCENE_LIGHT_COL_R) * cr;
  const float lg = (live ? 1.0F : SCENE_LIGHT_COL_G) * cg;
  const float lb = (live ? 1.0F : SCENE_LIGHT_COL_B) * cb2;
  sunBody.color.set(128.0F * lr, 128.0F * lg, 128.0F * lb, 128.0F);
  // The moon is an alpha-blended bag, so its VERTEX COLOUR ALPHA is its
  // opacity - no second texture and no extra pass for the slider.
  {
    const float op = live ? DAYCYCLE_MOON_ALPHAS[currentScene] : SCENE_MOON_ALPHA;
    moonBody.color.set(128.0F * cr, 128.0F * cg, 128.0F * cb2,
                       128.0F * (op < 0.0F ? 0.0F : (op > 1.0F ? 1.0F : op)));
  }
  if (live) {
    place(sunBody, daynight::g_sun[0], daynight::g_sun[1], daynight::g_sun[2],
          daynight::g_sunRad, 0.0F);
    place(moonBody, daynight::g_moon[0], daynight::g_moon[1], daynight::g_moon[2],
          daynight::g_moonRad, daynight::g_moonRoll);
  } else {
    place(sunBody, SCENE_SUN_X, SCENE_SUN_Y, SCENE_SUN_Z, SCENE_SUN_R, 0.0F);
    place(moonBody, SCENE_MOON_X, SCENE_MOON_Y, SCENE_MOON_Z, SCENE_MOON_R,
          SCENE_MOON_ROLL);
  }
}
}
